use crate::config::RuleConfig;
use crate::context::Ctx;

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Severity {
    Error,
    Warning,
    Info,
}

impl Severity {
    pub fn as_str(&self) -> &'static str {
        match self {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Info => "info",
        }
    }
    pub fn parse(s: &str) -> Option<Severity> {
        match s.to_ascii_lowercase().as_str() {
            "error" => Some(Severity::Error),
            "warning" | "warn" => Some(Severity::Warning),
            "info" => Some(Severity::Info),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Fix {
    pub start: usize,
    pub end: usize,
    pub replacement: String,
}

impl Fix {
    pub fn new(start: usize, end: usize, replacement: impl Into<String>) -> Fix {
        Fix { start, end, replacement: replacement.into() }
    }
}

#[derive(Clone, Debug)]
pub struct Warning {
    pub rule: &'static str,
    pub line: usize,
    pub column: usize,
    pub end_line: usize,
    pub end_column: usize,
    pub message: String,
    pub severity: Severity,
    pub fix: Option<Fix>,
}

impl Warning {
    pub fn new(rule: &'static str, line: usize, column: usize, end_line: usize, end_column: usize, message: impl Into<String>) -> Warning {
        Warning {
            rule,
            line,
            column,
            end_line,
            end_column,
            message: message.into(),
            severity: Severity::Warning,
            fix: None,
        }
    }
    pub fn with_fix(mut self, fix: Option<Fix>) -> Warning {
        self.fix = fix;
        self
    }
    pub fn sev(mut self, s: Severity) -> Warning {
        self.severity = s;
        self
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FixAvail {
    Always,
    None,
}

pub trait Rule: Send + Sync {
    fn name(&self) -> &'static str;
    fn description(&self) -> &'static str;
    fn alias(&self) -> &'static str;
    fn extra_aliases(&self) -> &'static [&'static str] {
        &[]
    }
    fn category(&self) -> &'static str;
    fn fix_availability(&self) -> FixAvail {
        FixAvail::Always
    }
    fn default_severity(&self) -> Severity {
        Severity::Warning
    }
    /// Default configuration (kebab-case keys, sorted alphabetically when displayed)
    fn default_config(&self) -> Vec<(&'static str, toml::Value)> {
        Vec::new()
    }
    /// Whether rule is enabled by default
    fn opt_in(&self) -> bool {
        false
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning>;
    /// Return fixed content; default applies all warning fixes
    fn fix(&self, ctx: &Ctx, cfg: &RuleConfig, warnings: &[Warning]) -> Option<String> {
        apply_fixes(&ctx.content, warnings)
    }
}

/// Apply non-overlapping fixes (sorted by start). Later overlapping fixes are skipped.
pub fn apply_fixes(content: &str, warnings: &[Warning]) -> Option<String> {
    let mut fixes: Vec<&Fix> = warnings.iter().filter_map(|w| w.fix.as_ref()).collect();
    if fixes.is_empty() {
        return None;
    }
    // sort by start descending, apply from end
    fixes.sort_by(|a, b| b.start.cmp(&a.start).then(b.end.cmp(&a.end)));
    let mut out = content.to_string();
    let mut last_start = usize::MAX;
    for f in fixes {
        if f.end > last_start && !(f.start == f.end && f.start == last_start) {
            continue;
        }
        if f.start > out.len() || f.end > out.len() || f.start > f.end {
            continue;
        }
        if !out.is_char_boundary(f.start) || !out.is_char_boundary(f.end) {
            continue;
        }
        out.replace_range(f.start..f.end, &f.replacement);
        last_start = f.start;
    }
    Some(out)
}
EOF"}

