    pub items: Vec<ListItem>,
    pub lists: Vec<ListBlock>,
    pub code_blocks: Vec<CodeBlock>,
    pub html_blocks: Vec<HtmlBlock>,
    pub paragraphs: Vec<Paragraph>,
    pub tables: Vec<TableBlock>,
