/// Cursor over a line handling tabs (tab stop = 4)
#[derive(Clone, Copy)]
struct Cur {
    pos: usize,
    col: usize,
    /// remaining virtual spaces of a partially consumed tab at pos
    partial: usize,
}

fn tab_width(col: usize) -> usize {
    4 - (col % 4)
}

/// Compute indentation (in columns) from cursor and the position of first non-ws char
fn peek_indent(line: &[u8], c: Cur) -> (usize, usize, usize) {
    // returns (indent cols, pos of first non-space, col at that pos)
    let mut pos = c.pos;
    let mut col = c.col;
    let mut ind = 0;
    if c.partial > 0 && pos < line.len() && line[pos] == b'\t' {
        ind += c.partial;
        col += c.partial;
        pos += 1;
    }
    while pos < line.len() {
        match line[pos] {
            b' ' => {
                ind += 1;
                col += 1;
                pos += 1;
            }
            b'\t' => {
                let w = tab_width(col);
                ind += w;
                col += w;
                pos += 1;
            }
            _ => break,
        }
    }
    (ind, pos, col)
}

/// Advance cursor by n columns (consuming spaces/tabs)
fn advance_cols(line: &[u8], mut c: Cur, mut n: usize) -> Cur {
    while n > 0 && c.pos < line.len() {
        let b = line[c.pos];
        if b == b'\t' {
            let w = if c.partial > 0 { c.partial } else { tab_width(c.col) };
            if n >= w {
                n -= w;
                c.col += w;
                c.pos += 1;
                c.partial = 0;
            } else {
                c.col += n;
                c.partial = w - n;
                n = 0;
            }
        } else if b == b' ' {
            c.pos += 1;
            c.col += 1;
            n -= 1;
        } else {
            break;
        }
    }
    c
}

/// advance to position (non-whitespace), computing column
fn advance_to(line: &[u8], c: Cur, pos: usize) -> Cur {
    let mut cur = c;
    while cur.pos < pos {
        let b = line[cur.pos];
        if b == b'\t' {
            let w = if cur.partial > 0 { cur.partial } else { tab_width(cur.col) };
            cur.col += w;
        } else {
            cur.col += 1;
        }
        cur.partial = 0;
        cur.pos += 1;
    }
    cur
}

fn is_blank_from(line: &[u8], pos: usize) -> bool {
    line[pos.min(line.len())..].iter().all(|&b| b == b' ' || b == b'\t')
}

pub fn is_thematic_break(s: &str) -> bool {
    let t = s.trim_end_matches([' ', '\t']);
    let b = t.as_bytes();
    if b.is_empty() {
        return false;
    }
    let ch = b[0];
    if ch != b'*' && ch != b'-' && ch != b'_' {
        return false;
    }
    let mut count = 0;
    for &x in b {
        if x == ch {
            count += 1;
        } else if x != b' ' && x != b'\t' {
            return false;
        }
    }
    count >= 3
}

fn atx_start(s: &str) -> bool {
    let b = s.as_bytes();
    let mut n = 0;
    while n < b.len() && b[n] == b'#' {
        n += 1;
    }
    (1..=6).contains(&n) && (n == b.len() || b[n] == b' ' || b[n] == b'\t')
}

fn fence_start(s: &str) -> Option<(char, usize, String)> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    let ch = b[0];
    if ch != b'`' && ch != b'~' {
        return None;
    }
    let mut n = 0;
    while n < b.len() && b[n] == ch {
        n += 1;
    }
    if n < 3 {
        return None;
    }
    let info = &s[n..];
    if ch == b'`' && info.contains('`') {
        return None;
    }
    Some((ch as char, n, info.trim().to_string()))
}

fn is_fence_close(s: &str, ch: char, len: usize) -> bool {
    let b = s.as_bytes();
    let mut n = 0;
    while n < b.len() && b[n] == ch as u8 {
        n += 1;
    }
    n >= len && is_blank_from(b, n)
}

fn setext_underline(s: &str) -> Option<u8> {
    let t = s.trim_end_matches([' ', '\t']);
    if t.is_empty() {
        return None;
    }
    let b = t.as_bytes();
    let ch = b[0];
    if (ch == b'=' || ch == b'-') && b.iter().all(|&x| x == ch) {
        Some(if ch == b'=' { 1 } else { 2 })
    } else {
        None
    }
}

const HTML_BLOCK6: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
    "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
    "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
    "optgroup", "option", "p", "param", "search", "section", "summary", "table", "tbody", "td", "tfoot",
    "th", "thead", "title", "tr", "track", "ul",
];

/// returns html block type 1..7
fn html_block_start(s: &str, can_interrupt_para: bool) -> Option<u8> {
    let b = s.as_bytes();
    if b.is_empty() || b[0] != b'<' {
        return None;
    }
    let lower = s.to_ascii_lowercase();
    for t in ["<pre", "<script", "<style", "<textarea"] {
        if lower.starts_with(t) {
            let rest = &lower.as_bytes()[t.len()..];
            if rest.is_empty() || rest[0] == b' ' || rest[0] == b'\t' || rest[0] == b'>' {
                return Some(1);
            }
        }
    }
    if s.starts_with("<!--") {
        return Some(2);
    }
    if s.starts_with("<?") {
        return Some(3);
    }
    if b.len() >= 3 && b[1] == b'!' && b[2].is_ascii_alphabetic() {
        return Some(4);
    }
    if s.starts_with("<![CDATA[") {
        return Some(5);
    }
    // type 6
    let mut i = 1;
    if i < b.len() && b[i] == b'/' {
        i += 1;
    }
    let st = i;
    while i < b.len() && b[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i > st {
        let name = &lower[st..i];
        if HTML_BLOCK6.contains(&name) {
            let rest = &b[i..];
            if rest.is_empty()
                || rest[0] == b' '
                || rest[0] == b'\t'
                || rest[0] == b'>'
                || (rest.len() >= 2 && rest[0] == b'/' && rest[1] == b'>')
            {
                return Some(6);
            }
        }
    }
    if !can_interrupt_para {
        return None;
    }
    // type 7: complete open or closing tag followed only by whitespace
    if let Some(end) = crate::inline::parse_html_tag(s, 0) {
        let tag = &s[..end];
        if tag.starts_with("<!") || tag.starts_with("<?") {
            return None;
        }
        if is_blank_from(b, end) {
            // tag name must not be one of type 1
            return Some(7);
        }
    }
    None
}

fn html_block_end(kind: u8, s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    match kind {
        1 => lower.contains("</pre>") || lower.contains("</script>") || lower.contains("</style>") || lower.contains("</textarea>"),
        2 => s.contains("-->"),
        3 => s.contains("?>"),
        4 => s.contains('>'),
        5 => s.contains("]]>"),
        _ => false,
    }
}

pub struct MarkerInfo {
    pub ordered: bool,
    pub bullet: char,
    pub delim: char,
    pub number: Option<u64>,
    pub marker_len: usize,
}

pub fn parse_marker(s: &str) -> Option<MarkerInfo> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    if b[0] == b'-' || b[0] == b'+' || b[0] == b'*' {
        if b.len() == 1 || b[1] == b' ' || b[1] == b'\t' {
            return Some(MarkerInfo { ordered: false, bullet: b[0] as char, delim: ' ', number: None, marker_len: 1 });
        }
        return None;
    }
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_digit() && i < 10 {
        i += 1;
    }
    if i == 0 || i > 9 || i >= b.len() {
        return None;
    }
    if b[i] != b'.' && b[i] != b')' {
        return None;
    }
    if i + 1 < b.len() && b[i + 1] != b' ' && b[i + 1] != b'\t' {
        return None;
    }
    let num: u64 = s[..i].parse().ok()?;
    Some(MarkerInfo { ordered: true, bullet: ' ', delim: b[i] as char, number: Some(num), marker_len: i + 1 })
}

pub fn parse(lines: &[&str], front_matter_end: Option<usize>) -> Blocks {
    let mut out = Blocks {
        lines: Vec::with_capacity(lines.len()),
        items: Vec::new(),
        lists: Vec::new(),
        code_blocks: Vec::new(),
        html_blocks: Vec::new(),
        paragraphs: Vec::new(),
        tables: Vec::new(),
    };
    let mut open: Vec<Cont> = Vec::new();
    let mut leaf = Leaf::None;
    // depth (number of containers) at which current leaf lives
    let mut leaf_depth = 0usize;
    let mut para_start = 0usize;
    // per container depth: last list id that may be continued (list open at that level)
    // we keep list membership via item.list; list remains open if last item at this level closed by a new item
    let mut open_list_at: Vec<Option<usize>> = vec![None; 64];
    let mut item_had_content: Vec<bool> = Vec::new(); // parallel to items
    let mut prev_blank_in_item: Vec<bool> = Vec::new();

    for (ln, raw) in lines.iter().enumerate() {
        let line = raw.as_bytes();
        if let Some(fe) = front_matter_end {
            if ln <= fe {
                out.lines.push(BLine {
                    kind: Kind::FrontMatter,
                    bq_depth: 0,
                    content_start: 0,
                    lazy: false,
                    items: vec![],
                    item_start: None,
                    item_starts: vec![],
                    code_block: None,
                    html_block: None,
                    table: None,
                    paragraph: None,
                    container_bq: 0,
                });
                continue;
            }
        }
        let mut cur = Cur { pos: 0, col: 0, partial: 0 };
        let mut matched = 0usize;
        let line_blank = is_blank_from(line, 0);
        // match containers
        for c in open.iter() {
            match c {
                Cont::Quote => {
                    let (ind, p, _) = peek_indent(line, cur);
                    if ind <= 3 && p < line.len() && line[p] == b'>' {
                        cur = advance_to(line, cur, p);
                        cur.pos += 1;
                        cur.col += 1;
                        cur.partial = 0;
                        // optional space
                        if cur.pos < line.len() {
                            if line[cur.pos] == b' ' {
                                cur.pos += 1;
                                cur.col += 1;
                            } else if line[cur.pos] == b'\t' {
                                cur = advance_cols(line, cur, 1);
                            }
                        }
                        matched += 1;
                    } else {
                        break;
                    }
                }
                Cont::Item(idx) => {
                    let it = &out.items[*idx];
                    let (ind, p, _) = peek_indent(line, cur);
                    let rel_needed = it.content_col; // absolute column
                    if p >= line.len() {
                        // blank
                        if !item_had_content[*idx] && it.empty && it.line + 1 == ln {
                            // item starting with blank line followed by blank: item ends
                            break;
                        }
                        if !item_had_content[*idx] && it.empty {
                            break;
                        }
                        cur = advance_to(line, cur, p);
                        matched += 1;
                    } else if cur.col + ind >= rel_needed {
                        let need = rel_needed.saturating_sub(cur.col);
                        cur = advance_cols(line, cur, need);
                        matched += 1;
                    } else {
                        break;
                    }
                }
            }
        }
        let all_matched = matched == open.len();

        // Continuation of fenced code / html in fully matched container
        if all_matched {
            match leaf.clone() {
                Leaf::Fenced { ch, len, indent: _, idx } => {
                    let (ind, p, _) = peek_indent(line, cur);
                    let rest = std::str::from_utf8(&line[p..]).unwrap_or("");
                    let bq = count_quotes(&open);
                    if ind <= 3 && is_fence_close(rest, ch, len) {
                        out.code_blocks[idx].end_line = ln;
                        out.code_blocks[idx].closed = true;
                        push_line(&mut out, Kind::FenceClose, bq, cur.pos, false, &open, None, vec![]);
                        out.lines.last_mut().unwrap().code_block = Some(idx);
                        leaf = Leaf::None;
                    } else {
                        out.code_blocks[idx].end_line = ln;
                        push_line(&mut out, Kind::FenceBody, bq, cur.pos, false, &open, None, vec![]);
                        out.lines.last_mut().unwrap().code_block = Some(idx);
                    }
                    mark_content(&open, &mut item_had_content, line_blank);
                    continue;
                }
                Leaf::Html { kind, idx } => {
                    let rest = std::str::from_utf8(&line[cur.pos..]).unwrap_or("");
                    let bq = count_quotes(&open);
                    if (kind == 6 || kind == 7) && is_blank_from(line, cur.pos) {
                        leaf = Leaf::None;
                        // blank line ends html block; treat as blank
                        push_line(&mut out, Kind::Blank, bq, cur.pos, false, &open, None, vec![]);
                        continue;
                    }
                    out.html_blocks[idx].end_line = ln;
                    push_line(&mut out, Kind::Html, bq, cur.pos, false, &open, None, vec![]);
                    out.lines.last_mut().unwrap().html_block = Some(idx);
                    mark_content(&open, &mut item_had_content, line_blank);
                    if html_block_end(kind, rest) {
                        leaf = Leaf::None;
                    }
                    continue;
                }
                _ => {}
            }
        }

        // Look for new container starts
        let mut new_items: Vec<usize> = Vec::new();
        let mut opened_new = false;
        let mut container_paragraph = all_matched && leaf == Leaf::Para;
        loop {
            let (ind, p, pcol) = peek_indent(line, cur);
            if ind >= 4 {
                break;
            }
            if p >= line.len() {
                break;
            }
            let rest = std::str::from_utf8(&line[p..]).unwrap_or("");
            if line[p] == b'>' {
                // new blockquote
                close_unmatched(&mut open, matched, &mut leaf, &mut out, ln, &mut open_list_at, &mut leaf_depth);
                if !opened_new {
                    // closing paragraph happens implicitly
                }
                cur = advance_to(line, cur, p);
                cur.pos += 1;
                cur.col += 1;
                if cur.pos < line.len() {
                    if line[cur.pos] == b' ' {
                        cur.pos += 1;
                        cur.col += 1;
                    } else if line[cur.pos] == b'\t' {
                        cur = advance_cols(line, cur, 1);
                    }
                }
                end_leaf(&mut leaf, &mut out, ln);
                open.push(Cont::Quote);
                matched = open.len();
                opened_new = true;
                container_paragraph = false;
                continue;
            }
            // thematic break takes precedence over list item
            if is_thematic_break(rest) {
                // but setext underline takes precedence when paragraph continues
                break;
            }
            if let Some(m) = parse_marker(rest) {
                // compute content
                let after = p + m.marker_len;
                let mcur = advance_to(line, cur, after);
                let (sp, np, _ncol) = peek_indent(line, mcur);
                let empty = np >= line.len();
                if container_paragraph && !opened_new {
                    // interrupting a paragraph
                    if empty || (m.ordered && m.number != Some(1)) {
                        break;
                    }
                }
                // lazy paragraph: if not all matched and leaf is para, list item can interrupt (closes para)
                if !all_matched && !opened_new && leaf == Leaf::Para && matched < open.len() {
                    if empty || (m.ordered && m.number != Some(1)) {
                        // would be lazy continuation
                        break;
                    }
                }
                let (content_col, content_cur, spaces_after) = if empty {
                    (pcol + m.marker_len + 1, mcur, sp)
                } else if sp >= 5 {
                    let c2 = advance_cols(line, mcur, 1);
                    (pcol + m.marker_len + 1, c2, 1)
                } else {
                    let c2 = advance_to(line, mcur, np);
                    (c2.col, c2, sp)
                };
                close_unmatched(&mut open, matched, &mut leaf, &mut out, ln, &mut open_list_at, &mut leaf_depth);
                end_leaf(&mut leaf, &mut out, ln);
                let depth_level = open.len();
                let bq = count_quotes(&open);
                // determine list
                let parent = open.iter().rev().find_map(|c| if let Cont::Item(i) = c { Some(*i) } else { None });
                let list_depth = open.iter().filter(|c| matches!(c, Cont::Item(_))).count();
                let mut list_id = None;
                if let Some(lid) = open_list_at[depth_level.min(63)] {
                    let l = &out.lists[lid];
                    if l.ordered == m.ordered && (if m.ordered { l.delim == m.delim } else { l.bullet == m.bullet }) && l.parent_item == parent {
                        list_id = Some(lid);
                    }
                }
                let lid = match list_id {
                    Some(l) => l,
                    None => {
                        out.lists.push(ListBlock {
                            ordered: m.ordered,
                            bullet: m.bullet,
                            delim: m.delim,
                            items: vec![],
                            start_line: ln,
                            end_line: ln,
                            parent_item: parent,
                            depth: list_depth,
                            bq_depth: bq,
                        });
                        out.lists.len() - 1
                    }
                };
                open_list_at[depth_level.min(63)] = Some(lid);
                for x in open_list_at.iter_mut().skip(depth_level + 1) {
                    *x = None;
                }
                let idx = out.items.len();
                out.items.push(ListItem {
                    line: ln,
                    marker_byte: p,
                    marker_col: pcol,
                    marker: rest[..m.marker_len].to_string(),
                    ordered: m.ordered,
                    number: m.number,
                    delim: m.delim,
                    bullet: m.bullet,
                    content_col,
                    content_byte: if empty { line.len() } else { content_cur.pos },
                    spaces_after: if empty { 0 } else { spaces_after },
                    empty,
                    list: lid,
                    parent,
                    depth: list_depth,
                    end_line: ln,
                    bq_depth: bq,
                });
                item_had_content.push(!empty);
                prev_blank_in_item.push(false);
                out.lists[lid].items.push(idx);
                out.lists[lid].end_line = ln;
                open.push(Cont::Item(idx));
                matched = open.len();
                new_items.push(idx);
                cur = content_cur;
                opened_new = true;
                container_paragraph = false;
                if empty {
                    break;
                }
                continue;
            }
            break;
        }

        let bq = count_quotes(&open);
        let (ind, p, _pcol) = peek_indent(line, cur);
        let rest = std::str::from_utf8(&line[p.min(line.len())..]).unwrap_or("");
        let blank = p >= line.len();
        let item_start = new_items.last().copied();

        // lazy continuation
        if !opened_new && matched < open.len() && leaf == Leaf::Para && !blank {
            // check whether rest starts a block that would interrupt a paragraph
            let interrupts = ind < 4
                && (atx_start(rest)
                    || fence_start(rest).is_some()
                    || is_thematic_break(rest)
                    || html_block_start(rest, false).is_some());
            if !interrupts {
                // lazy line: keep containers
                let idx = out.paragraphs.len() - 1;
                out.paragraphs[idx].end_line = ln;
                push_line(&mut out, Kind::Paragraph, count_quotes(&open[..matched]), cur.pos, true, &open, None, vec![]);
                let last = out.lines.last_mut().unwrap();
                last.paragraph = Some(idx);
                last.container_bq = count_quotes(&open);
                mark_content(&open, &mut item_had_content, false);
                continue;
            }
        }
        // table continuation
        if let Leaf::Table { idx } = leaf.clone() {
            if all_matched && !blank && !opened_new {
                let interrupts = ind < 4
                    && (atx_start(rest)
                        || fence_start(rest).is_some()
                        || is_thematic_break(rest)
                        || html_block_start(rest, false).is_some()
                        || rest.starts_with('>'));
                if !interrupts && (ind < 4 || rest.contains('|')) {
                    out.tables[idx].end_line = ln;
                    push_line(&mut out, Kind::Table, bq, cur.pos, false, &open, item_start, new_items.clone());
                    out.lines.last_mut().unwrap().table = Some(idx);
                    mark_content(&open, &mut item_had_content, false);
                    continue;
                }
            }
        }

        if !all_matched || opened_new {
            if !(matched < open.len()) || opened_new {
                // fine
            }
            close_unmatched(&mut open, matched, &mut leaf, &mut out, ln, &mut open_list_at, &mut leaf_depth);
        }
        let _ = leaf_depth;

        if blank {
            // blank line
            match leaf {
                Leaf::Indented { idx } => {
                    // may continue indented code; tentatively include
                    push_line(&mut out, Kind::Blank, bq, cur.pos, false, &open, item_start, new_items.clone());
                    let _ = idx;
                }
                _ => {
                    end_leaf(&mut leaf, &mut out, ln);
                    push_line(&mut out, Kind::Blank, bq, cur.pos, false, &open, item_start, new_items.clone());
                }
            }
            // blank line closes lists at deeper levels? (handled by item matching)
            for c in open.iter() {
                if let Cont::Item(i) = c {
                    prev_blank_in_item[*i] = true;
                }
            }
            continue;
        }
        mark_content(&open, &mut item_had_content, false);
        // a non-list line at this depth closes any open list at deeper/this level
        let depth_level = open.len();
        if item_start.is_none() {
            for x in open_list_at.iter_mut().skip(depth_level) {
                *x = None;
            }
        }

        // indented code
        if ind >= 4 {
            if leaf == Leaf::Para && !opened_new {
                // paragraph continuation
                let idx = out.paragraphs.len() - 1;
                out.paragraphs[idx].end_line = ln;
                push_line(&mut out, Kind::Paragraph, bq, cur.pos, false, &open, item_start, new_items.clone());
                out.lines.last_mut().unwrap().paragraph = Some(idx);
                continue;
            }
            if let Leaf::Indented { idx } = leaf {
                out.code_blocks[idx].end_line = ln;
                // convert intervening blank lines to code
                push_line(&mut out, Kind::IndentedCode, bq, cur.pos, false, &open, item_start, new_items.clone());
                out.lines.last_mut().unwrap().code_block = Some(idx);
                let start = out.code_blocks[idx].start_line;
                for l in start..ln {
                    if out.lines[l].kind == Kind::Blank {
                        out.lines[l].kind = Kind::IndentedCode;
                        out.lines[l].code_block = Some(idx);
                    }
                }
                continue;
            }
            end_leaf(&mut leaf, &mut out, ln);
            let idx = out.code_blocks.len();
            out.code_blocks.push(CodeBlock {
                fenced: false,
                start_line: ln,
                end_line: ln,
                fence_char: ' ',
                fence_len: 0,
                info: String::new(),
                closed: true,
                fence_indent: 0,
                bq_depth: bq,
                in_list: open.iter().any(|c| matches!(c, Cont::Item(_))),
            });
            leaf = Leaf::Indented { idx };
            push_line(&mut out, Kind::IndentedCode, bq, cur.pos, false, &open, item_start, new_items.clone());
            out.lines.last_mut().unwrap().code_block = Some(idx);
            continue;
        }
        let cur2 = advance_to(line, cur, p);
        let in_para = leaf == Leaf::Para && !opened_new;
        // ATX
        if atx_start(rest) {
            end_leaf(&mut leaf, &mut out, ln);
            push_line(&mut out, Kind::Atx, bq, cur2.pos, false, &open, item_start, new_items.clone());
            continue;
        }
        if let Some((ch, len, info)) = fence_start(rest) {
            end_leaf(&mut leaf, &mut out, ln);
            let idx = out.code_blocks.len();
            out.code_blocks.push(CodeBlock {
                fenced: true,
                start_line: ln,
                end_line: ln,
                fence_char: ch,
                fence_len: len,
                info,
                closed: false,
                fence_indent: ind,
                bq_depth: bq,
                in_list: open.iter().any(|c| matches!(c, Cont::Item(_))),
            });
            leaf = Leaf::Fenced { ch, len, indent: ind, idx };
            push_line(&mut out, Kind::FenceOpen, bq, cur2.pos, false, &open, item_start, new_items.clone());
            out.lines.last_mut().unwrap().code_block = Some(idx);
            continue;
        }
        if let Some(kind) = html_block_start(rest, !in_para) {
            end_leaf(&mut leaf, &mut out, ln);
            let idx = out.html_blocks.len();
            out.html_blocks.push(HtmlBlock { start_line: ln, end_line: ln, kind });
            push_line(&mut out, Kind::Html, bq, cur2.pos, false, &open, item_start, new_items.clone());
            out.lines.last_mut().unwrap().html_block = Some(idx);
            if !html_block_end(kind, rest) || kind >= 6 {
                leaf = Leaf::Html { kind, idx };
            } else if kind < 6 && html_block_end(kind, rest) {
                // ends on same line (check that end marker after start)
                let ends = match kind {
                    2 => rest[4..].contains("-->"),
                    3 => rest[2..].contains("?>"),
                    _ => true,
                };
                if !ends {
                    leaf = Leaf::Html { kind, idx };
                }
            }
            continue;
        }
        if in_para && all_matched {
            if let Some(level) = setext_underline(rest) {
                // setext heading
                let pidx = out.paragraphs.len() - 1;
                let start = out.paragraphs[pidx].start_line;
                for l in start..ln {
                    if out.lines[l].paragraph == Some(pidx) {
                        out.lines[l].kind = Kind::SetextText;
                    }
                }
                let _ = level;
                out.paragraphs.pop();
                for l in start..ln {
                    if out.lines[l].paragraph == Some(pidx) {
                        out.lines[l].paragraph = None;
                    }
                }
                leaf = Leaf::None;
                push_line(&mut out, Kind::SetextUnderline, bq, cur2.pos, false, &open, item_start, new_items.clone());
                continue;
            }
        }
        if is_thematic_break(rest) {
            end_leaf(&mut leaf, &mut out, ln);
            push_line(&mut out, Kind::ThematicBreak, bq, cur2.pos, false, &open, item_start, new_items.clone());
            continue;
        }
        // table start: previous line is para (single line para start) and this is delimiter row
        if in_para && all_matched && is_table_delim(rest) {
            let pidx = out.paragraphs.len() - 1;
            let hdr = ln - 1;
            if out.paragraphs[pidx].end_line == hdr && out.lines[hdr].paragraph == Some(pidx) {
                let hdr_text = &lines[hdr][out.lines[hdr].content_start..];
                if count_cells(hdr_text) == count_cells(rest) {
                    // convert header line
                    if out.paragraphs[pidx].start_line == hdr {
                        out.paragraphs.pop();
                    } else {
                        out.paragraphs[pidx].end_line = hdr - 1;
                    }
                    let tidx = out.tables.len();
                    out.tables.push(TableBlock { start_line: hdr, delim_line: ln, end_line: ln, bq_depth: bq });
                    out.lines[hdr].kind = Kind::Table;
                    out.lines[hdr].paragraph = None;
                    out.lines[hdr].table = Some(tidx);
                    push_line(&mut out, Kind::Table, bq, cur2.pos, false, &open, item_start, new_items.clone());
                    out.lines.last_mut().unwrap().table = Some(tidx);
                    leaf = Leaf::Table { idx: tidx };
                    continue;
                }
            }
        }
        // paragraph
        if in_para {
            let idx = out.paragraphs.len() - 1;
            out.paragraphs[idx].end_line = ln;
            push_line(&mut out, Kind::Paragraph, bq, cur2.pos, false, &open, item_start, new_items.clone());
            out.lines.last_mut().unwrap().paragraph = Some(idx);
            continue;
        }
        end_leaf(&mut leaf, &mut out, ln);
        out.paragraphs.push(Paragraph { start_line: ln, end_line: ln });
        para_start = ln;
        let _ = para_start;
        leaf = Leaf::Para;
        let idx = out.paragraphs.len() - 1;
        push_line(&mut out, Kind::Paragraph, bq, cur2.pos, false, &open, item_start, new_items.clone());
        out.lines.last_mut().unwrap().paragraph = Some(idx);
    }
    // close everything
    let n = lines.len();
    end_leaf(&mut leaf, &mut out, n);
    // trailing blank lines after indented code are not part of it: fix
    for cb in out.code_blocks.iter_mut() {
        if !cb.fenced {
            let mut e = cb.end_line;
            while e > cb.start_line && is_blank_from(lines[e].as_bytes(), 0) {
                e -= 1;
            }
            cb.end_line = e;
        }
    }
    // compute item end lines: last non-blank line contained in item
    for (ln, bl) in out.lines.iter().enumerate() {
        if bl.kind != Kind::Blank {
            for &i in &bl.items {
                out.items[i].end_line = ln;
            }
        }
    }
    for li in 0..out.lists.len() {
        let mut e = out.lists[li].start_line;
        for &i in &out.lists[li].items {
            e = e.max(out.items[i].end_line);
        }
        out.lists[li].end_line = e;
    }
    out
}

fn count_quotes(open: &[Cont]) -> usize {
    open.iter().filter(|c| matches!(c, Cont::Quote)).count()
}

fn mark_content(open: &[Cont], had: &mut [bool], blank: bool) {
    if blank {
        return;
    }
    for c in open {
        if let Cont::Item(i) = c {
            had[*i] = true;
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn push_line(out: &mut Blocks, kind: Kind, bq: usize, cs: usize, lazy: bool, open: &[Cont], item_start: Option<usize>, starts: Vec<usize>) {
    let items: Vec<usize> = open.iter().filter_map(|c| if let Cont::Item(i) = c { Some(*i) } else { None }).collect();
    out.lines.push(BLine {
        kind,
        bq_depth: bq,
        content_start: cs,
        lazy,
        items,
        item_start,
        item_starts: starts,
        code_block: None,
        html_block: None,
        table: None,
        paragraph: None,
        container_bq: bq,
    });
}

fn end_leaf(leaf: &mut Leaf, _out: &mut Blocks, _ln: usize) {
    *leaf = Leaf::None;
}

fn close_unmatched(open: &mut Vec<Cont>, matched: usize, leaf: &mut Leaf, out: &mut Blocks, ln: usize, open_list_at: &mut [Option<usize>], _leaf_depth: &mut usize) {
    if matched < open.len() {
        // closing containers ends leaf
        end_leaf(leaf, out, ln);
        // when closing an item, the list at that level remains open for continuation
        // when closing a quote, lists inside close
        let mut i = open.len();
        while i > matched {
            i -= 1;
            if let Cont::Quote = open[i] {
                for x in open_list_at.iter_mut().skip(i) {
                    *x = None;
                }
            } else {
                for x in open_list_at.iter_mut().skip(i + 1) {
                    *x = None;
                }
            }
        }
        open.truncate(matched);
    }
}

pub fn is_table_delim(s: &str) -> bool {
    let t = s.trim();
    if t.is_empty() {
        return false;
    }
    if !t.contains('-') {
        return false;
    }
    let inner = t.strip_prefix('|').unwrap_or(t);
    let inner = inner.strip_suffix('|').unwrap_or(inner);
    if !t.contains('|') {
        // single column without pipes is not valid delimiter for header w/o pipes
        // GFM requires at least one pipe unless... treat as not table
        return false;
    }
    for cell in inner.split('|') {
        let c = cell.trim();
        if c.is_empty() {
            return false;
        }
        let c = c.strip_prefix(':').unwrap_or(c);
        let c = c.strip_suffix(':').unwrap_or(c);
        if c.is_empty() || !c.bytes().all(|b| b == b'-') {
            return false;
        }
    }
    true
}

pub fn count_cells(s: &str) -> usize {
    crate::tables::split_cells(s).len()
}
EOF"}

