                        let (content_col, content_cur, spaces_after) = if empty {
                            (pcol + m.marker_len + 1, mcur, 0)
                        } else if sp >= 5 {
                            let c2 = advance_cols(line, mcur, 1);
                            (pcol + m.marker_len + 1, c2, sp)
                        } else {
                            let c2 = advance_to(line, mcur, np);
                            (c2.col, c2, sp)
                        };
