                        let mut lid = None;
                        if let Some(Cont::List(l)) = open.last() {
                            let lb = &out.lists[*l];
                            if lb.ordered == m.ordered && (if m.ordered { lb.delim == m.delim } else { lb.bullet == m.bullet }) {
                                lid = Some(*l);
                            } else {
                                open.pop();
                            }
                        }
                        let parent = open.iter().rev().find_map(|c| if let Cont::Item(i) = c { Some(*i) } else { None });
                        let depth = open.iter().filter(|c| matches!(c, Cont::Item(_))).count();
                        let bq = count_quotes(&open);
                        let lid = match lid {
                            Some(l) => l,
                            None => {
                                out.lists.push(ListBlock {
                                    ordered: m.ordered,
                                    bullet: m.bullet,
                                    delim: m.delim,
                                    items: vec![],
                                    start_line: ln,
                                    end_line: ln,
                                    parent_item: parent,
                                    depth,
                                    bq_depth: bq,
                                });
                                let l = out.lists.len() - 1;
                                open.push(Cont::List(l));
                                l
                            }
                        };
                        let idx = out.items.len();
                        out.items.push(ListItem {
                            line: ln,
                            marker_byte: p,
                            marker_col: pcol,
                            marker: rest[..m.marker_len].to_string(),
                            ordered: m.ordered,
                            number: m.number,
                            delim: m.delim,
                            bullet: m.bullet,
                            content_col,
                            content_byte: if empty { line.len() } else { content_cur.pos },
                            spaces_after,
                            empty,
                            list: lid,
                            parent,
                            depth,
                            end_line: ln,
                            bq_depth: bq,
                        });
