            let idx = out.paragraphs.len() - 1;
            out.paragraphs[idx].end_line = ln;
            let bq_matched = count_quotes(&open[..matched]);
            push_line(&mut out, Kind::Paragraph, bq_matched, p, true, &open, None, vec![]);
            let last = out.lines.last_mut().unwrap();
            last.paragraph = Some(idx);
            last.container_bq = count_quotes(&open);
            continue;
        }
        close_unmatched(&mut open, matched, &mut leaf);
        let bq = count_quotes(&open);
        if blank {
            if leaf == Leaf::Para || matches!(leaf, Leaf::Table { .. }) {
                leaf = Leaf::None;
            }
            push_line(&mut out, Kind::Blank, bq, p, false, &open, item_start, new_items.clone());
            continue;
        }
        mark_content(&open, &mut item_had_content, false);
        let rest = std::str::from_utf8(&line[p..]).unwrap_or("");
        if container_is_table && !opened_new {
            if let Leaf::Table { idx } = leaf {
                out.tables[idx].end_line = ln;
                push_line(&mut out, Kind::Table, bq, p, false, &open, item_start, new_items.clone());
                out.lines.last_mut().unwrap().table = Some(idx);
                continue;
            }
        }
        if container_is_para && !opened_new && leaf == Leaf::Para {
            // table start?
            if is_table_delim(rest) {
                let pidx = out.paragraphs.len() - 1;
                let hdr = ln - 1;
                if out.paragraphs[pidx].end_line == hdr && out.paragraphs[pidx].start_line == hdr {
                    let hdr_text = &lines[hdr][out.lines[hdr].content_start..];
                    if count_cells(hdr_text) == count_cells(rest) {
                        out.paragraphs.pop();
                        let tidx = out.tables.len();
                        out.tables.push(TableBlock { start_line: hdr, delim_line: ln, end_line: ln, bq_depth: bq });
                        out.lines[hdr].kind = Kind::Table;
                        out.lines[hdr].paragraph = None;
                        out.lines[hdr].table = Some(tidx);
                        push_line(&mut out, Kind::Table, bq, p, false, &open, item_start, new_items.clone());
                        out.lines.last_mut().unwrap().table = Some(tidx);
                        leaf = Leaf::Table { idx: tidx };
                        continue;
                    }
                }
            }
            let idx = out.paragraphs.len() - 1;
            out.paragraphs[idx].end_line = ln;
            push_line(&mut out, Kind::Paragraph, bq, p, false, &open, item_start, new_items.clone());
            out.lines.last_mut().unwrap().paragraph = Some(idx);
            continue;
        }
        // new paragraph
        close_list_if_top(&mut open);
        out.paragraphs.push(Paragraph { start_line: ln, end_line: ln });
        leaf = Leaf::Para;
        let idx = out.paragraphs.len() - 1;
        push_line(&mut out, Kind::Paragraph, count_quotes(&open), p, false, &open, item_start, new_items.clone());
        out.lines.last_mut().unwrap().paragraph = Some(idx);
    }
    // trailing blank lines after indented code are not part of it
    for (ci, cb) in out.code_blocks.iter_mut().enumerate() {
        if !cb.fenced {
            let mut e = cb.end_line;
            while e > cb.start_line && out.lines[e].kind == Kind::Blank {
                e -= 1;
            }
            cb.end_line = e;
            for l in (e + 1)..out.lines.len() {
                if out.lines[l].code_block == Some(ci) && out.lines[l].kind == Kind::Blank {
                    out.lines[l].code_block = None;
