// Inline parsing: code spans, autolinks, raw html, links/images, emphasis.
use std::collections::HashSet;

#[derive(Clone, Debug)]
pub struct CodeSpan {
    pub start: usize,
    pub end: usize,
    pub content_start: usize,
    pub content_end: usize,
    pub ticks: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LinkKind {
    Inline,
    Full,
    Collapsed,
    Shortcut,
    Autolink,
}

#[derive(Clone, Debug)]
pub struct Link {
    pub image: bool,
    pub kind: LinkKind,
    pub start: usize,
    pub end: usize,
    pub text_start: usize,
    pub text_end: usize,
    /// raw destination as written (inline links); for refs: the label
    pub dest: String,
    pub dest_start: usize,
    pub dest_end: usize,
    pub title: Option<String>,
    pub label: String,
    /// whether dest was <...>
