}

#[derive(Clone, Debug)]
pub struct HtmlTag {
    pub start: usize,
    pub end: usize,
    pub text: String,
}

#[derive(Clone, Debug)]
pub struct Emph {
    pub start: usize,
    pub end: usize,
    pub ch: char,
    pub strong: bool,
    pub content_start: usize,
    pub content_end: usize,
}

#[derive(Default, Clone, Debug)]
pub struct InlineResult {
    pub code_spans: Vec<CodeSpan>,
    pub links: Vec<Link>,
    pub html: Vec<HtmlTag>,
    pub emph: Vec<Emph>,
    pub autolinks: Vec<(usize, usize)>,
    /// brackets that did not form links, e.g. [foo] or [foo][bar] with undefined refs
    pub unresolved_refs: Vec<Link>,
}

pub fn is_ascii_punct(c: u8) -> bool {
    c.is_ascii_punctuation()
}

pub fn normalize_label(s: &str) -> String {
    let lowered = s.to_lowercase();
    lowered.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Parse an HTML tag (open, close, comment, PI, declaration, CDATA) starting at `pos` (which must be '<').
/// Returns end byte offset (exclusive).
pub fn parse_html_tag(s: &str, pos: usize) -> Option<usize> {
    let b = s.as_bytes();
    if pos >= b.len() || b[pos] != b'<' {
        return None;
    }
    let mut i = pos + 1;
    if i >= b.len() {
        return None;
    }
    // comment
    if s[i..].starts_with("!--") {
        let after = i + 3;
        if s[after..].starts_with('>') {
            return Some(after + 1);
        }
        if s[after..].starts_with("->") {
            return Some(after + 2);
        }
        if let Some(e) = s[after..].find("-->") {
            return Some(after + e + 3);
        }
        return None;
    }
    if b[i] == b'?' {
        if let Some(e) = s[i + 1..].find("?>") {
            return Some(i + 1 + e + 2);
        }
        return None;
    }
    if s[i..].starts_with("![CDATA[") {
        if let Some(e) = s[i + 8..].find("]]>") {
            return Some(i + 8 + e + 3);
        }
        return None;
    }
    if b[i] == b'!' {
        if i + 1 < b.len() && b[i + 1].is_ascii_alphabetic() {
            if let Some(e) = s[i + 1..].find('>') {
                return Some(i + 1 + e + 1);
            }
        }
        return None;
    }
    let closing = b[i] == b'/';
    if closing {
        i += 1;
    }
    if i >= b.len() || !b[i].is_ascii_alphabetic() {
        return None;
    }
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'-') {
        i += 1;
    }
    if closing {
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if i < b.len() && b[i] == b'>' {
            return Some(i + 1);
        }
        return None;
    }
    // attributes
    loop {
        let ws_start = i;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if i >= b.len() {
            return None;
        }
        if b[i] == b'>' {
            return Some(i + 1);
        }
        if b[i] == b'/' {
            if i + 1 < b.len() && b[i + 1] == b'>' {
                return Some(i + 2);
            }
            return None;
        }
        if i == ws_start {
            return None; // attribute must be preceded by whitespace
        }
        // attribute name
        if !(b[i].is_ascii_alphabetic() || b[i] == b'_' || b[i] == b':') {
            return None;
        }
        while i < b.len() && (b[i].is_ascii_alphanumeric() || b"_.:-".contains(&b[i])) {
            i += 1;
        }
        // optional value
        let save = i;
        let mut j = i;
        while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
            j += 1;
        }
        if j < b.len() && b[j] == b'=' {
            j += 1;
            while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
                j += 1;
            }
            if j >= b.len() {
                return None;
            }
            if b[j] == b'"' || b[j] == b'\'' {
                let q = b[j];
                j += 1;
                while j < b.len() && b[j] != q {
                    j += 1;
                }
                if j >= b.len() {
                    return None;
                }
                j += 1;
            } else {
                let st = j;
                while j < b.len() && !b" \t\n\"'=<>`".contains(&b[j]) {
                    j += 1;
                }
                if j == st {
                    return None;
                }
            }
            i = j;
        } else {
            i = save;
        }
    }
}

/// Try to parse autolink at pos ('<'). Returns end.
pub fn parse_autolink(s: &str, pos: usize) -> Option<usize> {
    let b = s.as_bytes();
    if b[pos] != b'<' {
        return None;
    }
    let mut i = pos + 1;
    // URI
    let st = i;
    if i < b.len() && b[i].is_ascii_alphabetic() {
        while i < b.len() && (b[i].is_ascii_alphanumeric() || b"+.-".contains(&b[i])) {
            i += 1;
        }
        let slen = i - st;
        if (2..=32).contains(&slen) && i < b.len() && b[i] == b':' {
            i += 1;
            while i < b.len() && b[i] != b'>' && b[i] != b'<' && b[i] > b' ' {
                i += 1;
            }
            if i < b.len() && b[i] == b'>' {
                return Some(i + 1);
            }
        }
    }
    // email
    i = pos + 1;
    let st = i;
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&b[i])) {
        i += 1;
    }
    if i == st || i >= b.len() || b[i] != b'@' {
        return None;
    }
    i += 1;
    let mut label_len = 0;
    let dst = i;
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_alphanumeric() || c == b'-' {
            label_len += 1;
            i += 1;
        } else if c == b'.' && label_len > 0 {
            label_len = 0;
            i += 1;
        } else {
            break;
        }
    }
    if i > dst && i < b.len() && b[i] == b'>' && label_len > 0 {
        return Some(i + 1);
    }
    None
}

/// Parse inline link destination+title after '(' at pos (pos points to '(').
/// Returns (end, dest, dest_start, dest_end, title, angle)
pub fn parse_inline_dest(s: &str, pos: usize) -> Option<(usize, String, usize, usize, Option<String>, bool)> {
    let b = s.as_bytes();
    if pos >= b.len() || b[pos] != b'(' {
        return None;
    }
    let mut i = pos + 1;
    let skip_ws = |i: &mut usize| {
        while *i < b.len() && (b[*i] == b' ' || b[*i] == b'\t' || b[*i] == b'\n') {
            *i += 1;
        }
    };
    skip_ws(&mut i);
    let dest_start;
    let dest_end;
    let mut angle = false;
    if i < b.len() && b[i] == b'<' {
        angle = true;
        let st = i + 1;
        let mut j = st;
        while j < b.len() && b[j] != b'>' && b[j] != b'\n' && b[j] != b'<' {
            if b[j] == b'\\' && j + 1 < b.len() {
                j += 2;
                continue;
            }
            j += 1;
        }
        if j >= b.len() || b[j] != b'>' {
            return None;
        }
        dest_start = st;
        dest_end = j;
        i = j + 1;
    } else {
        let st = i;
        let mut depth = 0i32;
        while i < b.len() {
            let c = b[i];
            if c == b'\\' && i + 1 < b.len() && is_ascii_punct(b[i + 1]) {
                i += 2;
                continue;
            }
            if c <= b' ' {
                break;
            }
            if c == b'(' {
                depth += 1;
                if depth > 32 {
                    return None;
                }
            } else if c == b')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            i += 1;
        }
        if depth != 0 {
            return None;
        }
        dest_start = st;
        dest_end = i;
    }
    let dest = s[dest_start..dest_end].to_string();
    let before_title = i;
    skip_ws(&mut i);
    let mut title = None;
    if i < b.len() && (b[i] == b'"' || b[i] == b'\'' || b[i] == b'(') && i > before_title {
        let close = if b[i] == b'(' { b')' } else { b[i] };
        let st = i + 1;
        let mut j = st;
        while j < b.len() && b[j] != close {
            if b[j] == b'\\' && j + 1 < b.len() {
                j += 2;
                continue;
            }
            if close == b')' && b[j] == b'(' {
                return None;
            }
            j += 1;
        }
        if j >= b.len() {
            return None;
        }
        title = Some(s[st..j].to_string());
        i = j + 1;
        skip_ws(&mut i);
    }
    if i < b.len() && b[i] == b')' {
        return Some((i + 1, dest, dest_start, dest_end, title, angle));
    }
    None
}

/// Parse a link label [..] at pos. returns (end, label_content_start, label_content_end)
pub fn parse_label(s: &str, pos: usize) -> Option<(usize, usize, usize)> {
    let b = s.as_bytes();
    if pos >= b.len() || b[pos] != b'[' {
        return None;
    }
    let mut i = pos + 1;
    let st = i;
    while i < b.len() {
        match b[i] {
            b'\\' if i + 1 < b.len() => i += 2,
            b'[' => return None,
            b']' => {
                if i - st > 999 {
                    return None;
                }
                return Some((i + 1, st, i));
            }
            _ => i += 1,
        }
    }
    None
}

struct Delim {
    pos: usize,
    ch: u8,
    count: usize,
    orig: usize,
    can_open: bool,
    can_close: bool,
    active: bool,
}

struct Bracket {
    pos: usize,
    image: bool,
    active: bool,
    delim_index: usize,
}

fn char_before(s: &str, pos: usize) -> Option<char> {
    s[..pos].chars().next_back()
}
fn char_at(s: &str, pos: usize) -> Option<char> {
    s[pos..].chars().next()
}

fn is_punct_char(c: char) -> bool {
    if c.is_ascii() {
        c.is_ascii_punctuation()
    } else {
        // Unicode punctuation / symbols approximation
        !c.is_alphanumeric() && !c.is_whitespace()
    }
}

/// Parse inline content of text `s` (joined block content). `refs` contains normalized labels.
pub fn parse_inlines(s: &str, refs: &HashSet<String>) -> InlineResult {
    let b = s.as_bytes();
    let mut res = InlineResult::default();
    let mut delims: Vec<Delim> = Vec::new();
    let mut brackets: Vec<Bracket> = Vec::new();
    // regions where text is "code" or html (skip emphasis inside)
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        match c {
            b'\\' => {
                i += if i + 1 < b.len() && is_ascii_punct(b[i + 1]) { 2 } else { 1 };
            }
            b'`' => {
                let mut n = 0;
                while i + n < b.len() && b[i + n] == b'`' {
                    n += 1;
                }
                // find closing run of n
                let mut j = i + n;
                let mut found = None;
                while j < b.len() {
                    if b[j] == b'`' {
                        let mut m = 0;
                        while j + m < b.len() && b[j + m] == b'`' {
                            m += 1;
                        }
                        if m == n {
                            found = Some(j);
                            break;
                        }
                        j += m;
                    } else {
                        j += 1;
                    }
                }
                if let Some(j) = found {
                    res.code_spans.push(CodeSpan { start: i, end: j + n, content_start: i + n, content_end: j, ticks: n });
                    i = j + n;
                } else {
                    i += n;
                }
            }
            b'<' => {
                if let Some(e) = parse_autolink(s, i) {
                    res.autolinks.push((i, e));
                    res.links.push(Link {
                        image: false,
                        kind: LinkKind::Autolink,
                        start: i,
                        end: e,
                        text_start: i + 1,
                        text_end: e - 1,
                        dest: s[i + 1..e - 1].to_string(),
                        dest_start: i + 1,
                        dest_end: e - 1,
                        title: None,
                        label: String::new(),
                        angle: true,
                    });
                    i = e;
                } else if let Some(e) = parse_html_tag(s, i) {
                    res.html.push(HtmlTag { start: i, end: e, text: s[i..e].to_string() });
                    i = e;
                } else {
                    i += 1;
                }
            }
            b'*' | b'_' => {
                let mut n = 0;
                while i + n < b.len() && b[i + n] == c {
                    n += 1;
                }
                let before = char_before(s, i);
                let after = char_at(s, i + n);
                let before_ws = before.map(|x| x.is_whitespace()).unwrap_or(true);
                let after_ws = after.map(|x| x.is_whitespace()).unwrap_or(true);
                let before_p = before.map(is_punct_char).unwrap_or(false);
                let after_p = after.map(is_punct_char).unwrap_or(false);
                let left = !after_ws && (!after_p || before_ws || before_p);
                let right = !before_ws && (!before_p || after_ws || after_p);
                let (can_open, can_close) = if c == b'*' {
                    (left, right)
                } else {
                    (left && (!right || before_p), right && (!left || after_p))
                };
                delims.push(Delim { pos: i, ch: c, count: n, orig: n, can_open, can_close, active: true });
                i += n;
            }
            b'!' if i + 1 < b.len() && b[i + 1] == b'[' => {
                brackets.push(Bracket { pos: i, image: true, active: true, delim_index: delims.len() });
                i += 2;
            }
            b'[' => {
                brackets.push(Bracket { pos: i, image: false, active: true, delim_index: delims.len() });
                i += 1;
            }
            b']' => {
                if let Some(bi) = brackets.len().checked_sub(1) {
                    let br = brackets.pop().unwrap();
                    let _ = bi;
                    if !br.active {
                        i += 1;
                        continue;
                    }
                    let text_start = br.pos + if br.image { 2 } else { 1 };
                    let text_end = i;
                    let mut matched: Option<Link> = None;
                    // inline
                    if i + 1 < b.len() && b[i + 1] == b'(' {
                        if let Some((end, dest, ds, de, title, angle)) = parse_inline_dest(s, i + 1) {
                            matched = Some(Link {
                                image: br.image,
                                kind: LinkKind::Inline,
                                start: br.pos,
                                end,
                                text_start,
                                text_end,
                                dest,
                                dest_start: ds,
                                dest_end: de,
                                title,
                                label: String::new(),
                                angle,
                            });
                        }
                    }
                    if matched.is_none() {
                        // full reference
                        let mut handled = false;
                        if i + 1 < b.len() && b[i + 1] == b'[' {
                            if let Some((end, ls, le)) = parse_label(s, i + 1) {
                                handled = true;
                                let label = if le > ls { &s[ls..le] } else { &s[text_start..text_end] };
                                let kind = if le > ls { LinkKind::Full } else { LinkKind::Collapsed };
                                let l = Link {
                                    image: br.image,
                                    kind,
                                    start: br.pos,
                                    end,
                                    text_start,
                                    text_end,
                                    dest: String::new(),
                                    dest_start: ls,
                                    dest_end: le,
                                    title: None,
                                    label: label.to_string(),
                                    angle: false,
                                };
                                if refs.contains(&normalize_label(label)) {
                                    matched = Some(l);
                                } else {
                                    res.unresolved_refs.push(l);
                                }
                            }
                        }
                        if !handled {
                            let label = &s[text_start..text_end];
                            let l = Link {
                                image: br.image,
                                kind: LinkKind::Shortcut,
                                start: br.pos,
                                end: i + 1,
                                text_start,
                                text_end,
                                dest: String::new(),
                                dest_start: text_start,
                                dest_end: text_end,
                                title: None,
                                label: label.to_string(),
                                angle: false,
                            };
                            if refs.contains(&normalize_label(label)) {
                                matched = Some(l);
                            } else {
                                res.unresolved_refs.push(l);
                            }
                        }
                    }
                    if let Some(l) = matched {
                        let end = l.end;
                        // process emphasis inside link text
                        process_emphasis(s, &mut delims, br.delim_index, &mut res.emph);
                        delims.truncate(br.delim_index);
                        if !l.image {
                            for x in brackets.iter_mut() {
                                if !x.image {
                                    x.active = false;
                                }
                            }
                        }
                        res.links.push(l);
                        i = end;
                        continue;
                    }
                }
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }
    process_emphasis(s, &mut delims, 0, &mut res.emph);
    res.links.sort_by_key(|l| l.start);
    res
}

fn process_emphasis(_s: &str, delims: &mut Vec<Delim>, bottom: usize, out: &mut Vec<Emph>) {
    // simplified CommonMark process emphasis
    let mut closer = bottom;
    let mut openers_bottom: std::collections::HashMap<(u8, bool, usize), usize> = std::collections::HashMap::new();
    while closer < delims.len() {
        if !(delims[closer].can_close && delims[closer].active && delims[closer].count > 0) {
            closer += 1;
            continue;
        }
        let ch = delims[closer].ch;
        let key = (ch, delims[closer].can_open, delims[closer].orig % 3);
        let ob = *openers_bottom.get(&key).unwrap_or(&bottom);
        let mut found = None;
        let mut o = closer;
        while o > ob.max(bottom) {
            o -= 1;
            let d = &delims[o];
            if d.ch == ch && d.can_open && d.active && d.count > 0 {
                // rule of 3
                let cl = &delims[closer];
                if (d.can_close || cl.can_open) && (d.orig + cl.orig) % 3 == 0 && !(d.orig % 3 == 0 && cl.orig % 3 == 0) {
                    continue;
                }
                found = Some(o);
                break;
            }
        }
        match found {
            Some(o) => {
                let use_n = if delims[o].count >= 2 && delims[closer].count >= 2 { 2 } else { 1 };
                // opener remaining delimiters are at the start: emphasis uses the inner-most chars
                let open_pos = delims[o].pos + delims[o].count - use_n;
                let close_pos = delims[closer].pos + (delims[closer].orig - delims[closer].count);
                out.push(Emph {
                    start: open_pos,
                    end: close_pos + use_n,
                    ch: ch as char,
                    strong: use_n == 2,
                    content_start: open_pos + use_n,
                    content_end: close_pos,
                });
                delims[o].count -= use_n;
                delims[closer].count -= use_n;
                // deactivate delimiters between
                for d in delims.iter_mut().take(closer).skip(o + 1) {
                    d.active = false;
                }
                if delims[closer].count == 0 {
                    closer += 1;
                }
            }
            None => {
                openers_bottom.insert(key, closer);
                if !delims[closer].can_open {
                    delims[closer].active = false;
                }
                closer += 1;
            }
        }
    }
}
