    pub end: usize,
}

pub struct LineInfo {
    pub start: usize,
    pub end: usize,
    pub kind: Kind,
    pub bq_depth: usize,
    pub content_start: usize,
    pub lazy: bool,
    pub in_code: bool,
    pub in_fence: bool,
    pub in_html_block: bool,
    pub in_html_comment: bool,
    pub in_front_matter: bool,
    pub items: Vec<usize>,
    pub item_start: Option<usize>,
    pub item_starts: Vec<usize>,
    pub heading: Option<usize>,
    pub code_block: Option<usize>,
    pub table: Option<usize>,
    pub paragraph: Option<usize>,
    pub ref_def: Option<usize>,
    pub blank: bool,
    pub in_math: bool,
}

pub struct Ctx {
    pub content: String,
    pub lines: Vec<LineInfo>,
    pub blocks: Blocks,
    pub front_matter: Option<FrontMatter>,
    pub headings: Vec<Heading>,
    pub ref_defs: Vec<RefDef>,
    pub ref_labels: HashSet<String>,
    pub code_spans: Vec<CodeSpan>,
    pub links: Vec<Link>,
    pub unresolved: Vec<Link>,
    pub html_tags: Vec<HtmlTag>,
    pub emph: Vec<Emph>,
    pub autolinks: Vec<(usize, usize)>,
    pub flavor: Flavor,
    pub html_comment_ranges: Vec<(usize, usize)>,
    pub file_path: Option<std::path::PathBuf>,
    pub line_starts: Vec<usize>,
}

pub fn detect_front_matter(lines: &[&str]) -> Option<FrontMatter> {
    if lines.is_empty() {
        return None;
    }
    let first = lines[0].trim_end();
    if first == "---" {
        for (i, l) in lines.iter().enumerate().skip(1) {
            let t = l.trim_end();
            if t == "---" {
                return Some(FrontMatter { kind: FmKind::Yaml, start_line: 0, end_line: i });
            }
        }
        return None;
    }
    if first == "+++" {
        for (i, l) in lines.iter().enumerate().skip(1) {
            if l.trim_end() == "+++" {
                return Some(FrontMatter { kind: FmKind::Toml, start_line: 0, end_line: i });
            }
        }
        return None;
    }
    None
}

impl Ctx {
    pub fn new(content: &str, flavor: Flavor) -> Ctx {
        let content = content.to_string();
        // split lines
        let mut ranges: Vec<(usize, usize)> = Vec::new();
        let mut s = 0;
        for (i, b) in content.bytes().enumerate() {
            if b == b'\n' {
                ranges.push((s, i));
                s = i + 1;
            }
        }
        if s < content.len() {
            ranges.push((s, content.len()));
        }
        let line_strs: Vec<&str> = ranges.iter().map(|&(a, b)| &content[a..b]).collect();
        let fm = detect_front_matter(&line_strs);
        let blocks = blocks::parse(&line_strs, fm.as_ref().map(|f| f.end_line));
        let mut lines: Vec<LineInfo> = Vec::with_capacity(ranges.len());
        for (i, &(a, b)) in ranges.iter().enumerate() {
            let bl = &blocks.lines[i];
            let k = bl.kind;
            let in_code = matches!(k, Kind::FenceOpen | Kind::FenceBody | Kind::FenceClose | Kind::IndentedCode)
                || (k == Kind::Blank && bl.code_block.is_some());
            lines.push(LineInfo {
                start: a,
                end: b,
                kind: k,
                bq_depth: bl.bq_depth,
                content_start: bl.content_start,
                lazy: bl.lazy,
                in_code,
                in_fence: matches!(k, Kind::FenceOpen | Kind::FenceBody | Kind::FenceClose),
                in_html_block: k == Kind::Html,
                in_html_comment: false,
                in_front_matter: k == Kind::FrontMatter,
                items: bl.items.clone(),
                item_start: bl.item_start,
                item_starts: bl.item_starts.clone(),
                heading: None,
                code_block: bl.code_block,
                table: bl.table,
                paragraph: bl.paragraph,
                ref_def: None,
                blank: content[a..b].trim().is_empty(),
                in_math: false,
            });
        }
        let line_starts = ranges.iter().map(|r| r.0).collect();
        let mut ctx = Ctx {
            content: String::new(),
            lines,
            blocks,
            front_matter: fm,
            headings: Vec::new(),
            ref_defs: Vec::new(),
            ref_labels: HashSet::new(),
            code_spans: Vec::new(),
            links: Vec::new(),
            unresolved: Vec::new(),
            html_tags: Vec::new(),
            emph: Vec::new(),
            autolinks: Vec::new(),
            flavor,
            html_comment_ranges: Vec::new(),
            file_path: None,
            line_starts,
        };
        ctx.content = content;
        ctx.compute_html_comments();
        ctx.compute_ref_defs();
        ctx.compute_headings();
        ctx.compute_inlines();
        ctx
    }

    pub fn line(&self, i: usize) -> &str {
        let l = &self.lines[i];
        &self.content[l.start..l.end]
    }

    pub fn num_lines(&self) -> usize {
        self.lines.len()
    }

    /// content of line after container prefixes
    pub fn line_content(&self, i: usize) -> &str {
        let l = &self.lines[i];
        let s = self.line(i);
        &s[l.content_start.min(s.len())..]
    }

    /// 1-based line, col (char-based) for byte offset
    pub fn offset_to_line_col(&self, off: usize) -> (usize, usize) {
        let idx = match self.line_starts.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i.saturating_sub(1),
        };
        if self.lines.is_empty() {
            return (1, 1);
        }
        let idx = idx.min(self.lines.len() - 1);
        let ls = self.lines[idx].start;
        let end = off.min(self.content.len());
        let col = if end >= ls { self.content[ls..end].chars().count() + 1 } else { 1 };
        (idx + 1, col)
    }

    pub fn line_of_offset(&self, off: usize) -> usize {
        match self.line_starts.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i.saturating_sub(1),
        }
    }

    pub fn is_in_code_span(&self, off: usize) -> bool {
        self.code_spans.iter().any(|c| off >= c.start && off < c.end)
    }

    pub fn in_html_comment_off(&self, off: usize) -> bool {
        self.html_comment_ranges.iter().any(|&(a, b)| off >= a && off < b)
    }

    fn compute_html_comments(&mut self) {
        // find <!-- ... --> outside code blocks
        let c = &self.content;
        let mut ranges = Vec::new();
        let mut i = 0;
        while let Some(p) = c[i..].find("<!--") {
            let st = i + p;
            let ln = self.line_of_offset(st);
            if self.lines[ln].in_code {
                i = st + 4;
                continue;
            }
            if self.is_offset_in_code_span_raw(st) {
                i = st + 4;
                continue;
            }
            match c[st + 4..].find("-->") {
                Some(e) => {
                    let end = st + 4 + e + 3;
                    ranges.push((st, end));
                    i = end;
                }
                None => {
                    ranges.push((st, c.len()));
                    break;
                }
            }
        }
        for &(a, b) in &ranges {
            let la = self.line_of_offset(a);
            let lb = self.line_of_offset(b.saturating_sub(1).max(a));
            for l in la..=lb {
                if l < self.lines.len() {
                    // whole line inside comment?
                    let ls = self.lines[l].start;
                    let le = self.lines[l].end;
                    if l > la && l < lb {
                        self.lines[l].in_html_comment = true;
                    } else {
                        let t = self.content[ls..le].trim();
                        let lead_ok = l > la || self.content[ls..a.max(ls)].trim().is_empty();
                        let trail_ok = l < lb || self.content[b.min(le)..le].trim().is_empty();
                        if lead_ok && trail_ok && !t.is_empty() {
                            self.lines[l].in_html_comment = true;
                        }
                    }
                }
            }
        }
        self.html_comment_ranges = ranges;
    }

    fn is_offset_in_code_span_raw(&self, off: usize) -> bool {
        // quick check: count backticks on the line before off (approximation)
        let ln = self.line_of_offset(off);
        let ls = self.lines[ln].start;
        let before = &self.content[ls..off];
        let ticks = before.bytes().filter(|&b| b == b'`').count();
        if ticks % 2 == 1 {
            // is there a closing backtick after?
            let le = self.lines[ln].end;
            return self.content[off..le].contains('`');
        }
        false
    }

    fn compute_ref_defs(&mut self) {
        // reference definitions: at start of paragraphs (line by line)
        let n = self.lines.len();
        let mut defs = Vec::new();
        let paras: Vec<(usize, usize)> = self.blocks.paragraphs.iter().map(|p| (p.start_line, p.end_line)).collect();
        for (ps, pe) in paras {
            let mut l = ps;
            while l <= pe && l < n {
                let text = self.line_content(l).to_string();
                match parse_ref_def_line(&text) {
                    Some((label_raw, url, title, consumed_title_next)) => {
                        let mut end_line = l;
                        let mut title = title;
                        if title.is_none() && !consumed_title_next && l + 1 <= pe {
                            let next = self.line_content(l + 1).trim().to_string();
                            if let Some(t) = parse_title_only(&next) {
                                title = Some(t);
                                end_line = l + 1;
                            }
                        }
                        let label = inline::normalize_label(&label_raw);
                        if !label.is_empty() {
                            defs.push(RefDef {
                                line: l,
                                end_line,
                                label,
                                label_raw,
                                url,
                                title,
                                start: self.lines[l].start,
                                end: self.lines[end_line].end,
                            });
                        }
                        l = end_line + 1;
                    }
                    None => break,
                }
            }
        }
        for (i, d) in defs.iter().enumerate() {
            for l in d.line..=d.end_line {
                self.lines[l].ref_def = Some(i);
            }
            self.ref_labels.insert(d.label.clone());
        }
        self.ref_defs = defs;
    }

    fn compute_headings(&mut self) {
        let n = self.lines.len();
        let mut i = 0;
        while i < n {
            let k = self.lines[i].kind;
            if k == Kind::Atx {
                let raw = self.line(i);
                let cs = self.lines[i].content_start;
                let content = &raw[cs..];
                let b = content.as_bytes();
                let mut h = 0;
                while h < b.len() && b[h] == b'#' {
                    h += 1;
                }
                let after = &content[h..];
                // strip closing sequence
                let trimmed_end = after.trim_end_matches([' ', '\t']);
                let mut text_part = trimmed_end;
                let mut closing = 0;
                {
                    let tb = trimmed_end.as_bytes();
                    let mut e = tb.len();
                    while e > 0 && tb[e - 1] == b'#' {
                        e -= 1;
                    }
                    let nh = tb.len() - e;
                    if nh > 0 && (e == 0 || tb[e - 1] == b' ' || tb[e - 1] == b'\t') {
                        // check not escaped
                        closing = nh;
                        text_part = &trimmed_end[..e];
                    }
                }
                let lead_ws = text_part.len() - text_part.trim_start().len();
                let text = text_part.trim().to_string();
                let text_start = cs + h + lead_ws;
                let text_end = text_start + text.len();
                // indent relative to line start (column count)
                let line_ind = raw.len() - raw.trim_start().len();
                let indent = if self.lines[i].bq_depth > 0 || !self.lines[i].items.is_empty() {
                    // relative to container content (approx)
                    let ws = &raw[..cs];
                    let _ = ws;
                    0
                } else {
                    line_ind
                };
                let (text, custom_id) = extract_custom_id(&text);
                self.headings.push(Heading {
                    line: i,
                    end_line: i,
                    level: h,
                    style: if closing > 0 { HeadingStyle::AtxClosed } else { HeadingStyle::Atx },
                    text,
                    text_start,
                    text_end,
                    indent,
                    hashes: h,
                    closing_hashes: closing,
                    custom_id,
                    bq_depth: self.lines[i].bq_depth,
                    in_list: !self.lines[i].items.is_empty(),
                });
                self.lines[i].heading = Some(self.headings.len() - 1);
                i += 1;
                continue;
            }
            if k == Kind::SetextText {
                let start = i;
                let mut j = i;
                while j < n && self.lines[j].kind == Kind::SetextText {
                    j += 1;
                }
                // j is underline
                if j < n && self.lines[j].kind == Kind::SetextUnderline {
                    let ul = self.line_content(j).trim();
                    let level = if ul.starts_with('=') { 1 } else { 2 };
                    let mut parts = Vec::new();
                    for l in start..j {
                        parts.push(self.line_content(l).trim().to_string());
                    }
                    let text = parts.join(" ");
                    let raw = self.line(start);
                    let cs = self.lines[start].content_start;
                    let lead = raw[cs..].len() - raw[cs..].trim_start().len();
                    let ts = cs + lead;
                    let first_text = raw[ts..].trim_end();
                    let (text, custom_id) = extract_custom_id(&text);
                    self.headings.push(Heading {
                        line: start,
                        end_line: j,
                        level,
                        style: if level == 1 { HeadingStyle::Setext1 } else { HeadingStyle::Setext2 },
                        text,
                        text_start: ts,
                        text_end: ts + first_text.len(),
                        indent: lead,
                        hashes: 0,
                        closing_hashes: 0,
                        custom_id,
                        bq_depth: self.lines[start].bq_depth,
                        in_list: !self.lines[start].items.is_empty(),
                    });
                    let hi = self.headings.len() - 1;
                    for l in start..=j {
                        self.lines[l].heading = Some(hi);
                    }
                    i = j + 1;
                    continue;
                }
                i = j;
                continue;
            }
            i += 1;
        }
    }

    fn compute_inlines(&mut self) {
        // group lines into inline blocks
        let n = self.lines.len();
        let mut i = 0;
        let refs = self.ref_labels.clone();
        let mut all = InlineResult::default();
        while i < n {
            let k = self.lines[i].kind;
            let is_inline = matches!(k, Kind::Paragraph | Kind::SetextText | Kind::Atx | Kind::Table) && self.lines[i].ref_def.is_none();
            if !is_inline {
                i += 1;
                continue;
            }
            // collect group
            let mut group = vec![i];
            if k == Kind::Paragraph || k == Kind::SetextText {
                let pid = self.lines[i].paragraph;
                let mut j = i + 1;
                while j < n {
                    let kj = self.lines[j].kind;
                    if self.lines[j].ref_def.is_some() {
                        break;
                    }
                    if k == Kind::Paragraph && kj == Kind::Paragraph && self.lines[j].paragraph == pid {
                        group.push(j);
                        j += 1;
                    } else if k == Kind::SetextText && kj == Kind::SetextText {
                        group.push(j);
                        j += 1;
                    } else {
                        break;
                    }
                }
                i = j;
            } else {
                i += 1;
            }
            // build joined text
            let mut text = String::new();
            let mut map: Vec<(usize, usize, usize)> = Vec::new(); // (seg_start, doc_start, len)
            for (gi, &l) in group.iter().enumerate() {
                let li = &self.lines[l];
                let mut cs = li.content_start;
                let raw = &self.content[li.start..li.end];
                // skip leading whitespace
                while cs < raw.len() && (raw.as_bytes()[cs] == b' ' || raw.as_bytes()[cs] == b'\t') {
                    cs += 1;
                }
                let mut seg = &raw[cs.min(raw.len())..];
                if k == Kind::Atx {
                    // only heading text
                    if let Some(h) = li.heading {
                        let hd = &self.headings[h];
                        cs = hd.text_start;
                        seg = &raw[hd.text_start.min(raw.len())..hd.text_end.min(raw.len()).max(hd.text_start.min(raw.len()))];
                    }
                }
                if gi > 0 {
                    text.push('\n');
                }
                map.push((text.len(), li.start + cs, seg.len()));
                text.push_str(seg);
            }
            let r = inline::parse_inlines(&text, &refs);
            let mapf = |o: usize| -> usize {
                for &(ss, ds, len) in map.iter().rev() {
                    if o >= ss {
                        return ds + (o - ss).min(len);
                    }
                }
                o
            };
            for mut c in r.code_spans {
                c.start = mapf(c.start);
                c.end = mapf(c.end);
                c.content_start = mapf(c.content_start);
                c.content_end = mapf(c.content_end);
                all.code_spans.push(c);
            }
            for mut l in r.links {
                l.start = mapf(l.start);
                l.end = mapf(l.end);
                l.text_start = mapf(l.text_start);
                l.text_end = mapf(l.text_end);
                l.dest_start = mapf(l.dest_start);
                l.dest_end = mapf(l.dest_end);
                all.links.push(l);
            }
            for mut l in r.unresolved_refs {
                l.start = mapf(l.start);
                l.end = mapf(l.end);
                l.text_start = mapf(l.text_start);
                l.text_end = mapf(l.text_end);
                l.dest_start = mapf(l.dest_start);
                l.dest_end = mapf(l.dest_end);
                all.unresolved_refs.push(l);
            }
            for mut h in r.html {
                h.start = mapf(h.start);
                h.end = mapf(h.end);
                all.html.push(h);
            }
            for mut e in r.emph {
                e.start = mapf(e.start);
                e.end = mapf(e.end);
                e.content_start = mapf(e.content_start);
                e.content_end = mapf(e.content_end);
                all.emph.push(e);
            }
            for (a, b) in r.autolinks {
                all.autolinks.push((mapf(a), mapf(b)));
            }
        }
        self.code_spans = all.code_spans;
        self.links = all.links;
        self.unresolved = all.unresolved_refs;
        self.html_tags = all.html;
        self.emph = all.emph;
        self.autolinks = all.autolinks;
        let _ = HashMap::<u8, u8>::new();
    }

    pub fn is_heading_line(&self, i: usize) -> bool {
        self.lines[i].heading.is_some()
    }

    pub fn is_list_item_line(&self, i: usize) -> bool {
        self.lines[i].item_start.is_some()
    }
}

pub fn extract_custom_id(text: &str) -> (String, Option<String>) {
    let t = text.trim_end();
    if t.ends_with('}') {
        if let Some(p) = t.rfind("{#") {
            let id = &t[p + 2..t.len() - 1];
            if !id.is_empty() && id.chars().all(|c| c.is_alphanumeric() || c == '-' || c == '_' || c == ':' || c == '.') {
                return (t[..p].trim_end().to_string(), Some(id.to_string()));
            }
        }
    }
    (text.to_string(), None)
}

/// Parse a reference definition from a single line: returns (label, url, title, title_consumed)
pub fn parse_ref_def_line(text: &str) -> Option<(String, String, Option<String>, bool)> {
    let t = text.trim_start();
    if text.len() - t.len() > 3 {
        return None;
    }
    let b = t.as_bytes();
    if b.is_empty() || b[0] != b'[' {
        return None;
    }
    let (end, ls, le) = inline::parse_label(t, 0)?;
    if end >= b.len() || b[end] != b':' {
        return None;
    }
    let label = t[ls..le].to_string();
    if label.trim().is_empty() {
        return None;
    }
    let rest = &t[end + 1..];
    let rest_t = rest.trim_start();
    if rest_t.is_empty() {
        return None; // dest on next line not supported
    }
    let (url, after) = if let Some(stripped) = rest_t.strip_prefix('<') {
        let e = stripped.find('>')?;
        (stripped[..e].to_string(), &stripped[e + 1..])
    } else {
        let e = rest_t.find([' ', '\t']).unwrap_or(rest_t.len());
        (rest_t[..e].to_string(), &rest_t[e..])
    };
    let after_t = after.trim();
    if after_t.is_empty() {
        return Some((label, url, None, false));
    }
    if !after.starts_with([' ', '\t']) {
        return None;
    }
    let title = parse_title_only(after_t)?;
    Some((label, url, Some(title), true))
}

pub fn parse_title_only(t: &str) -> Option<String> {
    let b = t.as_bytes();
    if b.len() < 2 {
        return None;
    }
    let (o, c) = (b[0], b[b.len() - 1]);
    let ok = (o == b'"' && c == b'"') || (o == b'\'' && c == b'\'') || (o == b'(' && c == b')');
    if ok {
        Some(t[1..t.len() - 1].to_string())
    } else {
        None
    }
}
