    }

    pub fn apply_global_table(&mut self, t: &toml::map::Map<String, Value>) {
        for (k, v) in t {
            let nk = norm_key(k);
            match nk.as_str() {
                "enable" => self.global.enable = Some(val_str_list(v)),
                "disable" => self.global.disable = val_str_list(v),
                "extend-enable" => self.global.extend_enable = val_str_list(v),
                "extend-disable" => self.global.extend_disable = val_str_list(v),
                "exclude" => self.global.exclude = val_str_list(v),
                "include" => self.global.include = val_str_list(v),
