                    if let Value::Boolean(b) = v {
                        self.global.cache = Some(*b)
                    }
                }
                "cache-dir" => {
                    if let Value::String(s) = v {
                        self.global.cache_dir = Some(s.clone())
                    }
                }
                "force-exclude" => {
                    if let Value::Boolean(b) = v {
                        self.global.force_exclude = Some(*b)
                    }
                }
                _ => {
                    continue;
                }
            }
            if !self.global.set_keys.contains(&nk) {
                self.global.set_keys.push(nk);
            }
        }
    }

    pub fn apply_rule_table(&mut self, rule: &str, t: &toml::map::Map<String, Value>) {
        let entry = self.rules.entry(rule.to_string()).or_default();
        for (k, v) in t {
            let nk = norm_key(k);
            if nk == "enabled" {
                if let Value::Boolean(b) = v {
                    self.rule_enabled.insert(rule.to_string(), *b);
                }
            }
            entry.insert(nk, v.clone());
        }
    }

    pub fn apply_toml_root(&mut self, root: &toml::map::Map<String, Value>, is_pyproject: bool) {
        for (k, v) in root {
            let nk = norm_key(k);
            match (nk.as_str(), v) {
                ("global", Value::Table(t)) => self.apply_global_table(t),
                ("per-file-ignores", Value::Table(t)) => {
                    for (pat, rules) in t {
                        self.per_file_ignores.push((pat.clone(), val_str_list(rules)));
                    }
                }
                ("per-file-flavor", Value::Table(t)) => {
                    for (pat, fl) in t {
                        if let Value::String(s) = fl {
                            self.per_file_flavor.push((pat.clone(), s.clone()));
                        }
                    }
                }
                (_, Value::Table(t)) => {
                    if let Some(rule) = crate::rules::resolve_rule_name(k) {
                        self.apply_rule_table(rule, t);
                    }
                }
                _ => {
                    if is_pyproject {
                        let mut m = toml::map::Map::new();
                        m.insert(k.clone(), v.clone());
                        self.apply_global_table(&m);
