        for (k, v) in root {
            let nk = norm_key(k);
            match (nk.as_str(), v) {
                ("global", Value::Table(t)) => self.apply_global_table(t),
                ("per-file-ignores", Value::Table(t)) => {
                    for (pat, rules) in t {
                        self.per_file_ignores.push((pat.clone(), val_str_list(rules)));
                    }
                }
                ("per-file-flavor", Value::Table(t)) => {
                    for (pat, fl) in t {
                        if let Value::String(s) = fl {
                            self.per_file_flavor.push((pat.clone(), s.clone()));
                        }
                    }
                }
                (_, Value::Table(t)) => {
                    if let Some(rule) = crate::rules::resolve_rule_name(k) {
                        self.apply_rule_table(rule, t);
                    }
                }
                _ => {
                    if is_pyproject {
                        let mut m = toml::map::Map::new();
                        m.insert(k.clone(), v.clone());
                        self.apply_global_table(&m);
                    } else {
                        // top-level global keys also accepted
                        let mut m = toml::map::Map::new();
                        m.insert(k.clone(), v.clone());
                        self.apply_global_table(&m);
                    }
                }
            }
        }
    }

    pub fn apply_markdownlint(&mut self, v: &Value) {
        if let Value::Table(t) = v {
            for (k, val) in t {
                if k == "$schema" || k == "extends" {
                    continue;
                }
                if k == "default" {
                    continue;
                }
                if norm_key(k) == "line-length" && !matches!(val, Value::Table(_)) {
                    if let Value::Integer(i) = val {
                        self.global.line_length = Some(*i as u64);
                    }
                    continue;
                }
                if let Some(rule) = crate::rules::resolve_rule_name(k) {
                    match val {
                        Value::Boolean(false) => {
                            if !self.global.disable.contains(&rule.to_string()) {
                                self.global.disable.push(rule.to_string());
                            }
                        }
                        Value::Boolean(true) => {}
                        Value::Table(rt) => {
                            let mut rt2 = rt.clone();
                            // markdownlint style aliases
                            rt2.remove("enabled");
                            self.apply_rule_table(rule, &rt2);
                        }
                        _ => {}
                    }
                }
            }
        }
    }
}

pub fn find_config_file(start: &Path) -> Option<PathBuf> {
    let mut dir = Some(start.to_path_buf());
    while let Some(d) = dir {
        for name in [".rumdl.toml", "rumdl.toml", ".config/rumdl.toml", "pyproject.toml"] {
            let p = d.join(name);
            if p.is_file() {
                if name == "pyproject.toml" {
                    if let Ok(s) = std::fs::read_to_string(&p) {
                        if let Ok(v) = s.parse::<toml::Table>() {
                            if v.get("tool").and_then(|t| t.get("rumdl")).is_some() {
                                return Some(p);
                            }
                        }
                    }
                    continue;
                }
                return Some(p);
            }
        }
        for name in [".markdownlint.json", ".markdownlint.jsonc", ".markdownlint.yaml", ".markdownlint.yml", "markdownlint.json", "markdownlint.yaml", "markdownlint.yml"] {
            let p = d.join(name);
            if p.is_file() {
                return Some(p);
            }
        }
        if d.join(".git").exists() {
            break;
        }
        dir = d.parent().map(|p| p.to_path_buf());
    }
    None
}

pub fn strip_json_comments(s: &str) -> String {
    let mut out = String::new();
    let b: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut in_str = false;
    while i < b.len() {
        let c = b[i];
        if in_str {
            out.push(c);
            if c == '\\' && i + 1 < b.len() {
                out.push(b[i + 1]);
                i += 2;
                continue;
            }
            if c == '"' {
                in_str = false;
            }
            i += 1;
            continue;
        }
        if c == '"' {
            in_str = true;
            out.push(c);
            i += 1;
            continue;
        }
        if c == '/' && i + 1 < b.len() && b[i + 1] == '/' {
            while i < b.len() && b[i] != '\n' {
                i += 1;
            }
            continue;
        }
        if c == '/' && i + 1 < b.len() && b[i + 1] == '*' {
            i += 2;
            while i + 1 < b.len() && !(b[i] == '*' && b[i + 1] == '/') {
                i += 1;
            }
            i += 2;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}

pub fn load_config_file(path: &Path) -> Result<Config, String> {
    let mut cfg = Config::default();
    let content = std::fs::read_to_string(path).map_err(|e| format!("Failed to read config file {}: {}", path.display(), e))?;
    let name = path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    let lower = name.to_ascii_lowercase();
    if lower.ends_with(".json") || lower.ends_with(".jsonc") || lower == ".markdownlintrc" {
        let v: serde_json::Value = serde_json::from_str(&strip_json_comments(&content)).map_err(|e| format!("Failed to parse JSON: {}", e))?;
        if let Some(t) = json_to_toml(&v) {
            cfg.apply_markdownlint(&t);
        }
    } else if lower.ends_with(".yaml") || lower.ends_with(".yml") {
        let v: serde_json::Value = serde_yaml::from_str(&content).map_err(|e| format!("Failed to parse YAML: {}", e))?;
        if let Some(t) = json_to_toml(&v) {
            cfg.apply_markdownlint(&t);
        }
    } else {
        let root: toml::Table = content.parse::<toml::Table>().map_err(|e| format!("Failed to parse TOML: {}", e))?;
        if lower == "pyproject.toml" {
            if let Some(Value::Table(t)) = root.get("tool").and_then(|t| t.get("rumdl")) {
                cfg.apply_toml_root(t, true);
            }
        } else {
            cfg.apply_toml_root(&root, false);
        }
    }
    cfg.source = Some(std::fs::canonicalize(path).unwrap_or(path.to_path_buf()));
    Ok(cfg)
}
EOF

