use crate::context::Ctx;
use crate::rule::{Fix, Warning};

/// Number of chars in a string
pub fn clen(s: &str) -> usize {
    s.chars().count()
}

/// 1-based char column for byte offset within a line
pub fn col_of(line: &str, byte: usize) -> usize {
    line[..byte.min(line.len())].chars().count() + 1
}

pub fn warn(rule: &'static str, ctx: &Ctx, line: usize, start_byte: usize, end_byte: usize, msg: impl Into<String>, fix: Option<Fix>) -> Warning {
    // line is 0-based, bytes relative to line start
    let l = ctx.line(line);
    let c1 = col_of(l, start_byte);
    let c2 = col_of(l, end_byte);
    Warning::new(rule, line + 1, c1, line + 1, c2, msg).with_fix(fix)
}

/// Warning from absolute byte offsets
pub fn warn_abs(rule: &'static str, ctx: &Ctx, start: usize, end: usize, msg: impl Into<String>, fix: Option<Fix>) -> Warning {
    let (l1, c1) = ctx.offset_to_line_col(start);
    let (l2, c2) = ctx.offset_to_line_col(end);
    Warning::new(rule, l1, c1, l2, c2, msg).with_fix(fix)
}

/// Byte range of full line including trailing newline
pub fn line_range_with_nl(ctx: &Ctx, i: usize) -> (usize, usize) {
    let l = &ctx.lines[i];
    let end = if l.end < ctx.content.len() { l.end + 1 } else { l.end };
    (l.start, end)
}

pub fn leading_ws(s: &str) -> usize {
    s.len() - s.trim_start_matches([' ', '\t']).len()
}

/// visual indentation (tabs to 4)
pub fn visual_indent(s: &str) -> usize {
    let mut col = 0;
    for c in s.chars() {
        match c {
            ' ' => col += 1,
            '\t' => col += 4 - (col % 4),
            _ => break,
        }
    }
    col
}

pub fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}
