use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD009;

impl Rule for MD009 {
    fn name(&self) -> &'static str {
        "MD009"
    }
    fn description(&self) -> &'static str {
        "Trailing spaces should be removed"
    }
    fn alias(&self) -> &'static str {
        "no-trailing-spaces"
    }
    fn category(&self) -> &'static str {
        "whitespace"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("br-spaces", Value::Integer(2)), ("list-item-empty-lines", Value::Boolean(false)), ("strict", Value::Boolean(false))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let br = cfg.usize("br-spaces", 2);
        let strict = cfg.bool("strict", false);
        let lie = cfg.bool("list-item-empty-lines", false);
        let mut out = Vec::new();
        let n = ctx.num_lines();
        let ends_nl = ctx.content.ends_with('\n');
        for i in 0..n {
            let li = &ctx.lines[i];
            if li.in_code {
                continue;
            }
            let line = ctx.line(i);
            let trimmed = line.trim_end_matches(' ');
            let trailing = line.len() - trimmed.len();
            if trailing == 0 {
                continue;
            }
            let is_last_no_nl = i == n - 1 && !ends_nl;
            if trimmed.trim().is_empty() {
                // empty line with spaces
                if lie && !li.items.is_empty() {
                    continue;
                }
                let fix = Fix::new(li.start, li.end, "");
                out.push(warn("MD009", ctx, i, 0, line.len(), "Empty line has trailing spaces", Some(fix)));
                continue;
            }
            // blockquote-only line
            let t = trimmed.trim_start();
            if t.starts_with('>') && t.chars().all(|c| c == '>' || c == ' ' || c == '\t') && trailing == 1 {
                continue;
            }
            if !strict && !is_last_no_nl && trailing == br {
                continue;
            }
            let msg = if trailing == 1 { "Trailing space found".to_string() } else { format!("{} trailing spaces found", trailing) };
            let fix = Fix::new(li.start + trimmed.len(), li.end, "");
            out.push(warn("MD009", ctx, i, trimmed.len(), line.len(), msg, Some(fix)));
        }
        out
    }
}
