use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD012;

impl Rule for MD012 {
    fn name(&self) -> &'static str {
        "MD012"
    }
    fn description(&self) -> &'static str {
        "Multiple consecutive blank lines"
    }
    fn alias(&self) -> &'static str {
        "no-multiple-blanks"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("maximum", Value::Integer(1))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let max = cfg.usize("maximum", 1);
        let n = ctx.num_lines();
        let mut out = Vec::new();
        let is_blank_line = |i: usize| -> bool {
            let li = &ctx.lines[i];
            !li.in_fence && !li.in_front_matter && ctx.line(i).trim().is_empty()
        };
        // find last non-blank line
        let mut last_content = None;
        for i in (0..n).rev() {
            if !is_blank_line(i) {
                last_content = Some(i);
                break;
            }
        }
        let last_content = match last_content {
            Some(l) => l,
            None => {
                return out;
            }
        };
        let mut i = 0;
        while i <= last_content {
            if is_blank_line(i) {
                let st = i;
                while i <= last_content && is_blank_line(i) {
                    i += 1;
                }
                let cnt = i - st;
                if cnt > max {
                    let msg = if st == 0 { "Multiple consecutive blank lines at start of file" } else { "Multiple consecutive blank lines between content" };
                    for l in (st + max)..i {
                        let (a, b) = line_range_with_nl(ctx, l);
                        out.push(warn("MD012", ctx, l, 0, 0, msg, Some(Fix::new(a, b, ""))));
                    }
                }
            } else {
                i += 1;
            }
        }
        // trailing
        let trailing = n - 1 - last_content;
        if trailing > 0 && (trailing > max || ctx.content.ends_with("\n\n")) {
            let start = ctx.lines[last_content].end + 1;
            let end = ctx.content.len();
            if start <= end {
                out.push(warn("MD012", ctx, n - 1, 0, 0, "Multiple consecutive blank lines at end of file", Some(Fix::new(start, end, ""))));
            }
        }
        out
    }
}
