// Inline configuration comments: <!-- rumdl-disable ... --> etc.
use crate::context::Ctx;
use std::collections::{BTreeMap, HashSet};

#[derive(Clone, Debug, Default)]
struct State {
    all_disabled: bool,
    disabled: HashSet<String>,
    // rules explicitly enabled while all disabled
    enabled: HashSet<String>,
}

impl State {
    fn is_disabled(&self, rule: &str) -> bool {
        if self.all_disabled {
            !self.enabled.contains(rule)
        } else {
            self.disabled.contains(rule)
        }
    }
}

#[derive(Default, Debug)]
pub struct InlineConfig {
    /// per line (0-based) state
    states: Vec<State>,
    /// line-specific disables: line -> (all, rules)
    line_disables: BTreeMap<usize, (bool, HashSet<String>)>,
    file_all_disabled: bool,
    file_disabled: HashSet<String>,
    pub file_config: BTreeMap<String, BTreeMap<String, toml::Value>>,
}

fn parse_rules(s: &str) -> Vec<String> {
    s.split(|c: char| c.is_whitespace() || c == ',')
        .filter(|x| !x.is_empty())
        .map(|x| crate::rules::resolve_rule_name(x).map(|r| r.to_string()).unwrap_or_else(|| x.to_ascii_uppercase()))
        .collect()
}

/// Extract all comments in a line: returns (command, args)
fn find_directives(line: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut rest = line;
    while let Some(p) = rest.find("<!--") {
        let after = &rest[p + 4..];
        let end = match after.find("-->") {
            Some(e) => e,
            None => break,
        };
        let inner = after[..end].trim();
        for prefix in ["rumdl-", "markdownlint-"] {
            if let Some(cmd_rest) = inner.strip_prefix(prefix) {
                let (cmd, args) = match cmd_rest.find(|c: char| c.is_whitespace()) {
                    Some(i) => (&cmd_rest[..i], cmd_rest[i..].trim()),
                    None => (cmd_rest, ""),
                };
                out.push((cmd.to_string(), args.to_string()));
            }
        }
        if inner == "prettier-ignore" {
            out.push(("prettier-ignore".to_string(), String::new()));
        }
        rest = &after[end + 3..];
    }
    out
}

impl InlineConfig {
    pub fn parse(ctx: &Ctx) -> InlineConfig {
        let n = ctx.num_lines();
        let mut ic = InlineConfig::default();
        let mut cur = State::default();
        let mut captured: Option<State> = None;
        ic.states = Vec::with_capacity(n);
        for i in 0..n {
            let li = &ctx.lines[i];
            let line = ctx.line(i);
            // state for this line is state before processing directives on it
            let mut line_state = cur.clone();
            if !li.in_code && line.contains("<!--") {
                for (cmd, args) in find_directives(line) {
                    match cmd.as_str() {
                        "disable" => {
                            let rules = parse_rules(&args);
                            if rules.is_empty() {
                                cur.all_disabled = true;
                                cur.enabled.clear();
                            } else {
                                for r in rules {
                                    if cur.all_disabled {
                                        cur.enabled.remove(&r);
                                    }
                                    cur.disabled.insert(r);
                                }
                            }
                            line_state = cur.clone();
                        }
                        "enable" => {
                            let rules = parse_rules(&args);
                            if rules.is_empty() {
                                cur = State::default();
                            } else {
                                for r in rules {
                                    cur.disabled.remove(&r);
                                    if cur.all_disabled {
                                        cur.enabled.insert(r);
                                    }
                                }
                            }
                        }
                        "disable-line" => {
                            let rules = parse_rules(&args);
                            let e = ic.line_disables.entry(i).or_default();
                            if rules.is_empty() {
                                e.0 = true;
                            } else {
                                e.1.extend(rules);
                            }
                        }
                        "disable-next-line" => {
                            let rules = parse_rules(&args);
                            let e = ic.line_disables.entry(i + 1).or_default();
                            if rules.is_empty() {
                                e.0 = true;
                            } else {
                                e.1.extend(rules);
                            }
                        }
                        "prettier-ignore" => {
                            let e = ic.line_disables.entry(i + 1).or_default();
                            e.0 = true;
                        }
                        "disable-file" => {
                            let rules = parse_rules(&args);
                            if rules.is_empty() {
                                ic.file_all_disabled = true;
                            } else {
                                ic.file_disabled.extend(rules);
                            }
                        }
                        "enable-file" => {}
                        "capture" => {
                            captured = Some(cur.clone());
                        }
                        "restore" => {
                            cur = captured.clone().unwrap_or_default();
                        }
                        "configure-file" => {
                            if let Ok(v) = serde_json::from_str::<serde_json::Value>(&args) {
                                if let Some(serde_json::Value::Object(o)) = Some(v) {
                                    for (k, val) in o {
                                        if let Some(rule) = crate::rules::resolve_rule_name(&k) {
                                            if let Some(toml::Value::Table(t)) = crate::config::json_to_toml(&val) {
                                                let e = ic.file_config.entry(rule.to_string()).or_default();
                                                for (kk, vv) in t {
                                                    e.insert(crate::config::norm_key(&kk), vv);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                }
            }
            ic.states.push(line_state);
        }
        ic
    }

    pub fn is_disabled(&self, rule: &str, line: usize) -> bool {
        // line is 1-based
        if self.file_all_disabled || self.file_disabled.contains(rule) {
            return true;
        }
        let l = line.saturating_sub(1);
        if let Some((all, rules)) = self.line_disables.get(&l) {
            if *all || rules.contains(rule) {
                return true;
            }
        }
        if let Some(s) = self.states.get(l) {
            return s.is_disabled(rule);
        }
        if let Some(s) = self.states.last() {
            return s.is_disabled(rule);
        }
        false
    }
}
EOF"}

