use crate::config::{Config, RuleConfig};
use crate::context::{Ctx, Flavor};
use crate::inline_config::InlineConfig;
use crate::rule::{Rule, Severity, Warning};

pub struct Engine<'a> {
    pub rules: Vec<&'a dyn Rule>,
    pub config: &'a Config,
}

pub fn rule_cfg(config: &Config, rule: &dyn Rule, ic: Option<&InlineConfig>) -> RuleConfig {
    let mut rc = config.rule_config(rule.name());
    if let Some(ic) = ic {
        if let Some(fc) = ic.file_config.get(rule.name()) {
            for (k, v) in fc {
                rc.values.insert(k.clone(), v.clone());
            }
        }
    }
    rc
}

pub fn severity_for(config: &Config, rule: &dyn Rule) -> Severity {
    if let Some(t) = config.rules.get(rule.name()) {
        if let Some(toml::Value::String(s)) = t.get("severity") {
            if let Some(sv) = Severity::parse(s) {
                return sv;
            }
        }
    }
    rule.default_severity()
}

impl<'a> Engine<'a> {
    pub fn check_ctx(&self, ctx: &Ctx, use_inline: bool) -> Vec<Warning> {
        let ic = if use_inline { Some(InlineConfig::parse(ctx)) } else { None };
        let mut all = Vec::new();
        for r in &self.rules {
            let cfg = rule_cfg(self.config, *r, ic.as_ref());
            let mut ws = r.check(ctx, &cfg);
            if let Some(ic) = &ic {
                ws.retain(|w| !ic.is_disabled(r.name(), w.line));
            }
            let sev = severity_for(self.config, *r);
            for w in ws.iter_mut() {
                w.severity = sev;
            }
            all.extend(ws);
        }
        all
    }

