use globset::{Glob, GlobMatcher};
use std::path::{Path, PathBuf};

pub const MD_EXTS: &[&str] = &["md", "markdown", "mdx", "qmd", "Rmd", "rmd", "mkd", "mdown", "mkdn", "mdwn"];

pub fn is_md_file(p: &Path) -> bool {
    match p.extension().and_then(|e| e.to_str()) {
        Some(e) => MD_EXTS.contains(&e),
        None => false,
    }
}

pub struct PatternSet {
    pub raw: Vec<String>,
    matchers: Vec<(String, GlobMatcher, Option<GlobMatcher>)>,
}

pub fn normalize_pattern(p: &str) -> String {
    let mut s = p.trim().to_string();
    if let Some(x) = s.strip_prefix("./") {
        s = x.to_string();
    }
    if s.ends_with('/') {
        s.push_str("**");
        return s;
    }
    let has_glob = s.contains('*') || s.contains('?') || s.contains('[');
    let last = s.rsplit('/').next().unwrap_or("");
    if !has_glob && !last.contains('.') {
        s.push_str("/**");
    }
    s
}

impl PatternSet {
    pub fn new(pats: &[String]) -> PatternSet {
        let mut matchers = Vec::new();
        for p in pats {
            let n = normalize_pattern(p);
            if let Ok(g) = Glob::new(&n) {
                let alt = if !n.contains('/') || n.starts_with("**") {
                    None
                } else {
                    Glob::new(&format!("**/{}", n)).ok().map(|g| g.compile_matcher())
                };
                matchers.push((n.clone(), g.compile_matcher(), alt));
            }
        }
        PatternSet { raw: pats.to_vec(), matchers }
    }
    pub fn is_empty(&self) -> bool {
        self.matchers.is_empty()
    }
    /// returns matching (normalized) pattern
    pub fn matches(&self, rel: &str) -> Option<String> {
        let rel = rel.strip_prefix("./").unwrap_or(rel);
        let name = rel.rsplit('/').next().unwrap_or(rel);
        for (n, m, alt) in &self.matchers {
            if m.is_match(rel) {
                return Some(n.clone());
            }
            if !n.contains('/') && m.is_match(name) {
                return Some(n.clone());
            }
            if let Some(a) = alt {
                if a.is_match(rel) {
                    return Some(n.clone());
                }
            }
            // directory prefix match: pattern "dir/**" matches "x/dir/..."
            if !n.contains('/') {
                for comp in rel.split('/') {
                    if m.is_match(comp) {
                        return Some(n.clone());
                    }
                }
            }
        }
        None
    }
}

pub fn display_path(p: &Path, cwd: &Path) -> String {
    let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
    let abs = clean_path(&abs);
    if let Ok(r) = abs.strip_prefix(cwd) {
        let s = r.to_string_lossy().to_string();
        if s.is_empty() {
            return ".".to_string();
        }
        return s;
    }
    abs.to_string_lossy().to_string()
}

pub fn clean_path(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                out.pop();
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

pub struct Discovery {
    pub files: Vec<PathBuf>,
    pub warnings: Vec<String>,
}

pub fn discover(paths: &[String], cwd: &Path, include: &PatternSet, exclude: &PatternSet, respect_gitignore: bool) -> Result<Discovery, String> {
    let mut files: Vec<PathBuf> = Vec::new();
    let mut warnings = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for p in paths {
        let path = PathBuf::from(p);
        let abs = clean_path(&if path.is_absolute() { path.clone() } else { cwd.join(&path) });
        if !abs.exists() {
            return Err(format!("File not found: {}", p));
        }
        if abs.is_file() {
            let rel = display_path(&abs, cwd);
            if let Some(pat) = exclude.matches(&rel) {
                warnings.push(format!("warning: {} ignored because of exclude pattern '{}'. Use --no-exclude to override", rel, pat));
                continue;
            }
            if seen.insert(abs.clone()) {
                files.push(abs);
            }
            continue;
        }
        // directory walk
        let mut wb = ignore::WalkBuilder::new(&abs);
        wb.hidden(false)
            .git_ignore(respect_gitignore)
            .git_global(false)
            .git_exclude(respect_gitignore)
            .ignore(respect_gitignore)
            .parents(respect_gitignore)
            .require_git(false);
        let mut found: Vec<PathBuf> = Vec::new();
        for e in wb.build().flatten() {
            let ep = e.path();
            if ep.components().any(|c| c.as_os_str() == ".git") {
                continue;
            }
            if !ep.is_file() || !is_md_file(ep) {
                continue;
            }
            let eabs = clean_path(ep);
            let rel = display_path(&eabs, cwd);
            if !include.is_empty() && include.matches(&rel).is_none() {
                continue;
            }
            if exclude.matches(&rel).is_some() {
                continue;
            }
            found.push(eabs);
        }
        found.sort();
        for f in found {
            if seen.insert(f.clone()) {
                files.push(f);
            }
        }
    }
    Ok(Discovery { files, warnings })
}
EOF"}

