use crate::rule::{Severity, Warning};

pub struct Colors {
    pub on: bool,
}

impl Colors {
    pub fn c(&self, code: &str, s: &str) -> String {
        if self.on {
            format!("\x1b[{}m{}\x1b[0m", code, s)
        } else {
            s.to_string()
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Format {
    Text,
    Full,
    Concise,
    Grouped,
    Json,
    JsonLines,
    Github,
    Gitlab,
    Pylint,
    Azure,
    Sarif,
    Junit,
}

impl Format {
    pub fn parse(s: &str) -> Option<Format> {
        Some(match s {
            "text" => Format::Text,
            "full" => Format::Full,
            "concise" => Format::Concise,
            "grouped" => Format::Grouped,
            "json" => Format::Json,
            "json-lines" | "jsonl" => Format::JsonLines,
            "github" => Format::Github,
            "gitlab" => Format::Gitlab,
            "pylint" => Format::Pylint,
            "azure" => Format::Azure,
            "sarif" => Format::Sarif,
            "junit" => Format::Junit,
            _ => return None,
        })
    }
    pub fn is_batch(&self) -> bool {
        matches!(self, Format::Json | Format::Gitlab | Format::Sarif | Format::Junit)
    }
}

pub fn json_escape(s: &str) -> String {
    serde_json::to_string(s).unwrap()
}

pub fn format_text_line(path: &str, w: &Warning, col: &Colors, fixed_mode: bool, show_marker: bool) -> String {
    let marker = if !show_marker {
        String::new()
    } else if w.fix.is_some() {
        if fixed_mode {
            " [fixed]".to_string()
        } else {
            " [*]".to_string()
        }
    } else {
        String::new()
    };
    let rule = format!("[{}]", w.rule);
    let rc = col.c("33", &rule);
    let marker_s = if col.on && show_marker { col.c("32", &marker) } else { marker };
    format!("{}:{}:{}: {} {}{}", col.c("4;34", path), col.c("36", &w.line.to_string()), col.c("36", &w.column.to_string()), rc, w.message, marker_s)
}

pub fn format_file_warnings(fmt: Format, path: &str, ws: &[Warning], col: &Colors, fixed_mode: bool) -> Vec<String> {
    let mut out = Vec::new();
    match fmt {
        Format::Text | Format::Full => {
            for w in ws {
                out.push(format_text_line(path, w, col, fixed_mode, true));
            }
        }
        Format::Concise => {
            for w in ws {
                out.push(format!("{}:{}:{}: [{}] {}", path, w.line, w.column, w.rule, w.message));
            }
        }
        Format::Grouped => {
            if ws.is_empty() {
                return out;
            }
            out.push(format!("{}:", path));
            let mut rules: Vec<&str> = ws.iter().map(|w| w.rule).collect();
            rules.sort();
            rules.dedup();
            for r in rules {
                out.push(format!("  {}:", r));
                for w in ws.iter().filter(|w| w.rule == r) {
                    let fx = if w.fix.is_some() { " (fixable)" } else { "" };
                    out.push(format!("    {}:{} {}{}", w.line, w.column, w.message, fx));
                }
            }
            out.push(String::new());
        }
        Format::JsonLines => {
            for w in ws {
                out.push(format!(
                    "{{\"file\":{},\"line\":{},\"column\":{},\"rule\":{},\"message\":{},\"severity\":{},\"fixable\":{}}}",
                    json_escape(path),
                    w.line,
                    w.column,
                    json_escape(w.rule),
                    json_escape(&w.message),
                    json_escape(w.severity.as_str()),
                    w.fix.is_some()
                ));
            }
        }
        Format::Github => {
            for w in ws {
                let level = match w.severity {
                    Severity::Error => "error",
                    Severity::Warning => "warning",
                    Severity::Info => "notice",
                };
                out.push(format!(
                    "::{} file={},line={},col={},endLine={},endColumn={},title={}::{}",
                    level,
                    gh_escape_prop(path),
                    w.line,
                    w.column,
                    w.end_line,
                    w.end_column,
                    w.rule,
                    gh_escape_data(&w.message)
                ));
            }
        }
        Format::Pylint => {
            for w in ws {
                out.push(format!("{}:{}:{}: [C{}] {}", path, w.line, w.column, w.rule, w.message));
            }
        }
        Format::Azure => {
            for w in ws {
                let level = match w.severity {
                    Severity::Error => "error",
                    _ => "warning",
                };
                out.push(format!(
                    "##vso[task.logissue type={};sourcepath={};linenumber={};columnnumber={};code={}]{}",
                    level, path, w.line, w.column, w.rule, w.message
                ));
            }
        }
        _ => {}
    }
    out
}

fn gh_escape_data(s: &str) -> String {
    s.replace('%', "%25").replace('\r', "%0D").replace('\n', "%0A")
}
fn gh_escape_prop(s: &str) -> String {
    s.replace('%', "%25").replace('\r', "%0D").replace('\n', "%0A").replace(':', "%3A").replace(',', "%2C")
}

pub fn json_warning(path: &str, w: &Warning) -> serde_json::Value {
    let fix = match &w.fix {
        Some(f) => serde_json::json!({"range": {"start": f.start, "end": f.end}, "replacement": f.replacement}),
        None => serde_json::Value::Null,
    };
    let mut m = serde_json::Map::new();
    m.insert("file".into(), path.into());
    m.insert("line".into(), w.line.into());
    m.insert("column".into(), w.column.into());
    m.insert("rule".into(), w.rule.into());
    m.insert("message".into(), w.message.clone().into());
    m.insert("severity".into(), w.severity.as_str().into());
    m.insert("fixable".into(), w.fix.is_some().into());
    m.insert("fix".into(), fix);
    serde_json::Value::Object(m)
}

pub fn batch_output(fmt: Format, all: &[(String, Vec<Warning>)], elapsed_ms: u128) -> String {
    match fmt {
        Format::Json => {
            let mut arr = Vec::new();
            for (p, ws) in all {
                for w in ws {
                    arr.push(json_warning(p, w));
                }
            }
            serde_json::to_string_pretty(&serde_json::Value::Array(arr)).unwrap()
        }
        Format::Gitlab => {
            let mut arr = Vec::new();
            for (p, ws) in all {
                for w in ws {
                    let mut m = serde_json::Map::new();
                    m.insert("description".into(), w.message.clone().into());
                    m.insert("check_name".into(), w.rule.into());
                    m.insert("fingerprint".into(), format!("{}-{}-{}-{}", p, w.line, w.column, w.rule).into());
                    m.insert("severity".into(), "minor".into());
                    let mut loc = serde_json::Map::new();
