// Minimal unified diff
pub fn unified_diff(old: &str, new: &str, old_name: &str, new_name: &str) -> String {
    let a: Vec<&str> = split_lines(old);
    let b: Vec<&str> = split_lines(new);
    let n = a.len();
    let m = b.len();
    // LCS table
    let mut dp = vec![vec![0u32; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[i][j] = if a[i] == b[j] { dp[i + 1][j + 1] + 1 } else { dp[i + 1][j].max(dp[i][j + 1]) };
        }
    }
    // ops: (tag, a_idx, b_idx)
    let mut ops: Vec<(char, usize, usize)> = Vec::new();
    let (mut i, mut j) = (0, 0);
    while i < n || j < m {
        if i < n && j < m && a[i] == b[j] {
            ops.push((' ', i, j));
            i += 1;
            j += 1;
        } else if j < m && (i >= n || dp[i][j + 1] >= dp[i + 1][j]) {
            ops.push(('+', i, j));
            j += 1;
        } else {
            ops.push(('-', i, j));
            i += 1;
        }
    }
    // reorder so that '-' come before '+' within change groups
    let mut ops2: Vec<(char, usize, usize)> = Vec::new();
    let mut k = 0;
    while k < ops.len() {
        if ops[k].0 == ' ' {
            ops2.push(ops[k]);
            k += 1;
            continue;
        }
        let st = k;
        while k < ops.len() && ops[k].0 != ' ' {
            k += 1;
        }
        for o in &ops[st..k] {
            if o.0 == '-' {
                ops2.push(*o);
            }
        }
        for o in &ops[st..k] {
            if o.0 == '+' {
                ops2.push(*o);
            }
        }
    }
    let ops = ops2;
    let ctx = 3;
    let mut out = String::new();
    out.push_str(&format!("--- {}\n+++ {}\n", old_name, new_name));
    let changes: Vec<usize> = ops.iter().enumerate().filter(|(_, o)| o.0 != ' ').map(|(i, _)| i).collect();
    if changes.is_empty() {
        return out;
    }
    let mut groups: Vec<(usize, usize)> = Vec::new();
    for &c in &changes {
        let s = c.saturating_sub(ctx);
        let e = (c + ctx + 1).min(ops.len());
        if let Some(last) = groups.last_mut() {
            if s <= last.1 {
                last.1 = last.1.max(e);
                continue;
            }
        }
        groups.push((s, e));
    }
    for (s, e) in groups {
        let slice = &ops[s..e];
        let a_start = slice.iter().find(|o| o.0 != '+').map(|o| o.1).unwrap_or(slice[0].1);
        let b_start = slice.iter().find(|o| o.0 != '-').map(|o| o.2).unwrap_or(slice[0].2);
        let a_len = slice.iter().filter(|o| o.0 != '+').count();
        let b_len = slice.iter().filter(|o| o.0 != '-').count();
        let fa = if a_len == 0 { a_start } else { a_start + 1 };
        let fb = if b_len == 0 { b_start } else { b_start + 1 };
        out.push_str(&format!("@@ -{},{} +{},{} @@\n", fa, a_len, fb, b_len));
        for o in slice {
            match o.0 {
                ' ' => out.push_str(&format!(" {}\n", a[o.1])),
                '-' => out.push_str(&format!("-{}\n", a[o.1])),
                _ => out.push_str(&format!("+{}\n", b[o.2])),
            }
        }
    }
    out
}

fn split_lines(s: &str) -> Vec<&str> {
    let mut v: Vec<&str> = s.split('\n').collect();
    if s.ends_with('\n') {
        v.pop();
    }
    v
}
