    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    if let Some(p) = config::find_config_file(&cwd) {
        return config::load_config_file(&p);
    }
    Ok(Config::default())
}

fn main() {
    let matches = cli::build_cli().get_matches();
    let color = color_enabled(&matches);
    let (sub, sm) = match matches.subcommand() {
        Some(x) => x,
        None => std::process::exit(2),
    };
    let g = GlobalOpts {
        color,
        config_path: sm.get_one::<String>("config").cloned(),
        no_config: sm.get_flag("no_config") || sm.get_flag("isolated"),
    };
    let code = match sub {
        "check" => run_check(sm, &g, false),
        "fmt" => run_check(sm, &g, true),
        "version" => {
            println!("rumdl 0.1.13");
            0
        }
        other => commands::run(other, sm, &g),
    };
    std::process::exit(code);
}

fn split_list(s: Option<&String>) -> Option<Vec<String>> {
    s.map(|x| x.split(',').map(|y| y.trim().to_string()).filter(|y| !y.is_empty()).collect())
}

fn check_rule_names(list: &[String], opt: &str) {
    for r in list {
        if rules::resolve_rule_name(r).is_none() && !r.eq_ignore_ascii_case("all") {
            let sugg = commands::suggest_rule(r);
            match sugg {
                Some(s) => warn_yellow("[cli warning]", &format!("Unknown rule in {}: {} (did you mean: {}?)", opt, r, s)),
                None => warn_yellow("[cli warning]", &format!("Unknown rule in {}: {}", opt, r)),
            }
        }
    }
}

pub fn select_rules<'a>(all: &'a [Box<dyn Rule>], cfg: &Config) -> Vec<&'a dyn Rule> {
    let g = &cfg.global;
    let resolve = |v: &Vec<String>| -> Vec<String> { v.iter().filter_map(|r| rules::resolve_rule_name(r).map(|s| s.to_string())).collect() };
    let enable: Option<Vec<String>> = g.enable.as_ref().map(resolve);
    let enable_all = g.enable.as_ref().map(|v| v.iter().any(|r| r.eq_ignore_ascii_case("all"))).unwrap_or(false);
    let disable = resolve(&g.disable);
    let disable_all = g.disable.iter().any(|r| r.eq_ignore_ascii_case("all"));
    let ext_en = resolve(&g.extend_enable);
    let ext_dis = resolve(&g.extend_disable);
    let mut out = Vec::new();
    for r in all {
        let name = r.name();
        let mut on = match &enable {
            Some(e) if !e.is_empty() && !enable_all => e.iter().any(|x| x == name),
            _ => true,
        };
        if ext_en.iter().any(|x| x == name) {
            on = true;
        }
        if disable_all || disable.iter().any(|x| x == name) {
            on = false;
        }
        if ext_dis.iter().any(|x| x == name) {
            on = false;
        }
        if on {
            out.push(r.as_ref());
        }
    }
    out
}

pub fn flavor_for(cfg: &Config, path: Option<&Path>, cli_flavor: Option<&str>, cwd: &Path) -> Flavor {
    if let Some(f) = cli_flavor {
        return Flavor::parse(f).unwrap_or(Flavor::Standard);
    }
    if let Some(p) = path {
        let rel = files::display_path(p, cwd);
        for (pat, fl) in &cfg.per_file_flavor {
            if let Ok(g) = globset::Glob::new(pat) {
                if g.compile_matcher().is_match(&rel) {
                    if let Some(f) = Flavor::parse(fl) {
                        return f;
                    }
                }
            }
        }
    }
    if let Some(f) = &cfg.global.flavor {
        if let Some(fl) = Flavor::parse(f) {
            return fl;
        }
    }
    if let Some(p) = path {
        match p.extension().and_then(|e| e.to_str()) {
            Some("mdx") => return Flavor::Mdx,
            Some("qmd") | Some("Rmd") | Some("rmd") => return Flavor::Quarto,
            _ => {}
        }
    }
    Flavor::Standard
}

fn per_file_ignored(cfg: &Config, rel: &str) -> Vec<String> {
    let mut out = Vec::new();
    for (pat, rules) in &cfg.per_file_ignores {
        if let Ok(g) = globset::Glob::new(pat) {
            let m = g.compile_matcher();
            let name = rel.rsplit('/').next().unwrap_or(rel);
            if m.is_match(rel) || (!pat.contains('/') && m.is_match(name)) {
                for r in rules {
                    if let Some(n) = rules::resolve_rule_name(r) {
                        out.push(n.to_string());
                    }
                }
            }
        }
    }
    out
}

struct FileResult {
    display: String,
    warnings: Vec<Warning>,
    fixed_count: usize,
    remaining: Vec<Warning>,
    diff: Option<String>,
    changed: bool,
}

fn fail_on_hit(ws: &[Warning], fail_on: &str) -> bool {
    match fail_on {
        "never" => false,
        "error" => ws.iter().any(|w| w.severity == Severity::Error),
        "warning" => ws.iter().any(|w| w.severity == Severity::Error || w.severity == Severity::Warning),
        _ => !ws.is_empty(),
    }
}

fn run_check(m: &clap::ArgMatches, g: &GlobalOpts, is_fmt: bool) -> i32 {
    let start = Instant::now();
    let mut cfg = match load_config(g) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            return 1;
        }
    };
    for w in &cfg.warnings {
        warn_yellow("[config warning]", w);
    }
    let all_rules = rules::all_rules();
    if m.get_flag("list_rules") {
        println!("Available rules:");
        for r in &all_rules {
            println!("  {} - {}", r.name(), r.description());
        }
        return 0;
    }
    // CLI overrides
    if let Some(v) = split_list(m.get_one::<String>("enable")) {
        check_rule_names(&v, "--enable");
        cfg.global.enable = Some(v);
    }
    if let Some(v) = split_list(m.get_one::<String>("disable")) {
        check_rule_names(&v, "--disable");
        cfg.global.disable = v;
    }
    if let Some(v) = split_list(m.get_one::<String>("extend_enable")) {
        check_rule_names(&v, "--extend-enable");
        cfg.global.extend_enable.extend(v);
    }
    if let Some(v) = split_list(m.get_one::<String>("extend_disable")) {
        check_rule_names(&v, "--extend-disable");
        cfg.global.extend_disable.extend(v);
    }
    if let Some(v) = split_list(m.get_one::<String>("exclude")) {
        cfg.global.exclude = v;
    }
    if let Some(v) = split_list(m.get_one::<String>("include")) {
        cfg.global.include = v;
    }
    if m.get_flag("no_exclude") {
        cfg.global.exclude.clear();
    }
    let respect_gitignore = m.get_one::<bool>("respect_gitignore").copied().or(cfg.global.respect_gitignore).unwrap_or(true);
    let fix_mode = is_fmt || m.get_flag("fix");
    let diff_mode = m.get_flag("diff");
    let check_mode = m.get_flag("check");
    let quiet = m.get_flag("quiet");
    let silent = m.get_flag("silent");
    let verbose = m.get_flag("verbose");
    let statistics = m.get_flag("statistics");
    let to_stderr = m.get_flag("stderr");
    let fail_on = m.get_one::<String>("fail_on").cloned().unwrap_or_else(|| "any".into());
    let cli_flavor = m.get_one::<String>("flavor").cloned();
    let colors = Colors { on: g.color };

    // output format
    let mut fmt = Format::Text;
    if let Some(f) = cfg.global.output_format.as_ref().and_then(|s| Format::parse(s)) {
        fmt = f;
    }
    if let Ok(e) = std::env::var("RUMDL_OUTPUT_FORMAT") {
        if let Some(f) = Format::parse(&e) {
            fmt = f;
        }
    }
    if let Some(o) = m.get_one::<String>("output") {
        if o == "json" {
            fmt = Format::Json;
        }
    }
    if let Some(f) = m.get_one::<String>("output_format").and_then(|s| Format::parse(s)) {
        fmt = f;
    }

    let rules_sel = select_rules(&all_rules, &cfg);
    let paths: Vec<String> = m.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default();
    let stdin_mode = m.get_flag("stdin") || (paths.len() == 1 && paths[0] == "-");
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));

    if stdin_mode {
        let mut input = String::new();
        let _ = std::io::stdin().read_to_string(&mut input);
        let display = m.get_one::<String>("stdin_filename").cloned().unwrap_or_else(|| "<stdin>".into());
        let fpath = m.get_one::<String>("stdin_filename").map(PathBuf::from);
        let flavor = flavor_for(&cfg, fpath.as_deref(), cli_flavor.as_deref(), &cwd);
        let crlf = input.contains("\r\n");
        let content = input.replace("\r\n", "\n");
        let mut rsel = rules_sel.clone();
        if let Some(fp) = &fpath {
            let ign = per_file_ignored(&cfg, &files::display_path(fp, &cwd));
            rsel.retain(|r| !ign.iter().any(|x| x == r.name()));
        }
        let engine = engine::Engine { rules: rsel, config: &cfg };
        let warnings = engine.check(&content, flavor, false, fpath.as_deref());
        if fix_mode && !diff_mode {
            let fixed = engine.fix(&content, flavor, false, fpath.as_deref());
            let out = if crlf { fixed.replace('\n', "\r\n") } else { fixed.clone() };
            print!("{}", out);
            let _ = std::io::stdout().flush();
            let mut remaining = engine.check_ctx(&context::Ctx::new(&fixed, flavor), false);
            let _ = &mut remaining;
            if !remaining.is_empty() && !silent {
                for w in &remaining {
                    eprintln!("{}", output::format_text_line(&display, w, &colors, false, true));
                }
                let fixed_n = warnings.len().saturating_sub(remaining.len());
                if !quiet {
                    eprintln!("\n{} issue(s) fixed, {} issue(s) remaining", fixed_n, remaining.len());
                }
            }
            if !is_fmt && fail_on_hit(&remaining, &fail_on) {
                return 1;
            }
            return 0;
        }
        if !silent {
            let mut lines = Vec::new();
            if fmt.is_batch() {
                lines.push(output::batch_output(fmt, &[(display.clone(), warnings.clone())], start.elapsed().as_millis()));
            } else {
                lines.extend(output::format_file_warnings(fmt, &display, &warnings, &colors, false));
                if !quiet && !matches!(fmt, Format::Grouped) || (!quiet && matches!(fmt, Format::Grouped)) {
                    if warnings.is_empty() {
                        lines.push("No issues found in ".to_string() + &display);
                    } else {
                        lines.push(String::new());
                        lines.push(format!("Found {} issue(s) in {}", warnings.len(), display));
                    }
                }
            }
            for l in lines {
                eprintln!("{}", l);
            }
        }
        return if fail_on_hit(&warnings, &fail_on) { 1 } else { 0 };
    }

    let paths = if paths.is_empty() { vec![".".to_string()] } else { paths };
    if m.get_flag("force_exclude") {
        eprintln!("warning: --force-exclude is deprecated and has no effect");
        eprintln!("Exclude patterns are now always respected by default (as of v0.0.156)");
        eprintln!("Use --no-exclude if you want to disable exclusions");
    }
    let include = files::PatternSet::new(&cfg.global.include);
    let exclude = files::PatternSet::new(&cfg.global.exclude);
    let disc = match files::discover(&paths, &cwd, &include, &exclude, respect_gitignore) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Error: Failed to find markdown files: {}", e);
            return 1;
        }
    };
    for w in &disc.warnings {
        eprintln!("{}", w);
    }
    if verbose && !silent {
        println!("Enabled rules:");
        for r in &rules_sel {
            println!("  - {} ({})", r.name(), r.description());
        }
        println!();
        println!("Exclude patterns: {:?}", cfg.global.exclude);
    }
    if disc.files.is_empty() {
        if !silent {
            println!("No markdown files found to check.");
        }
        return 0;
    }
    let show_full = m.get_flag("show_full_path");
    let mut results: Vec<FileResult> = Vec::new();
    for f in &disc.files {
        let display = if show_full { f.to_string_lossy().to_string() } else { files::display_path(f, &cwd) };
        let raw = match std::fs::read(f) {
            Ok(b) => String::from_utf8_lossy(&b).to_string(),
            Err(e) => {
                eprintln!("Error reading file {}: {}", display, e);
                continue;
            }
        };
        let crlf = raw.contains("\r\n");
        let content = raw.replace("\r\n", "\n");
        let flavor = flavor_for(&cfg, Some(f), cli_flavor.as_deref(), &cwd);
        let mut rsel = rules_sel.clone();
        let ign = per_file_ignored(&cfg, &files::display_path(f, &cwd));
        rsel.retain(|r| !ign.iter().any(|x| x == r.name()));
        let engine = engine::Engine { rules: rsel, config: &cfg };
        if verbose && !silent {
            println!("Processing file: {}", display);
        }
        let warnings = engine.check(&content, flavor, true, Some(f));
        let mut fr = FileResult { display, warnings, fixed_count: 0, remaining: vec![], diff: None, changed: false };
        if (fix_mode || diff_mode) && fr.warnings.iter().any(|w| w.fix.is_some()) {
            let fixed = engine.fix(&content, flavor, true, Some(f));
            if fixed != content {
                fr.changed = true;
                if diff_mode || check_mode {
                    fr.diff = Some(diff::unified_diff(&content, &fixed, &fr.display, &format!("{} (fixed)", fr.display)));
                } else {
                    let out = if crlf { fixed.replace('\n', "\r\n") } else { fixed.clone() };
                    let _ = std::fs::write(f, out);
                }
            }
            let rem = engine.check(&fixed, flavor, true, Some(f));
            fr.fixed_count = fr.warnings.len().saturating_sub(rem.len());
            fr.remaining = rem;
        } else {
            fr.remaining = fr.warnings.clone();
        }
        results.push(fr);
    }
    let elapsed = start.elapsed().as_millis();
    let total_files = results.len();
    let total_warnings: usize = results.iter().map(|r| r.warnings.len()).sum();
    let files_with = results.iter().filter(|r| !r.warnings.is_empty()).count();
    let fixable: usize = results.iter().map(|r| r.warnings.iter().filter(|w| w.fix.is_some()).count()).sum();
    let mut out_lines: Vec<String> = Vec::new();
    let fixed_display = fix_mode && !diff_mode && !check_mode;
    if fmt.is_batch() {
        let all: Vec<(String, Vec<Warning>)> = results
            .iter()
            .map(|r| (r.display.clone(), if fixed_display { r.remaining.clone() } else { r.warnings.clone() }))
            .collect();
        if !silent {
            out_lines.push(output::batch_output(fmt, &all, elapsed));
        }
    } else {
        for r in &results {
            if diff_mode || (fix_mode && check_mode) {
                let ws: Vec<Warning> = if fix_mode && check_mode { vec![] } else { r.warnings.iter().filter(|w| w.fix.is_none()).cloned().collect() };
                out_lines.extend(output::format_file_warnings(fmt, &r.display, &ws, &colors, false));
                if let Some(d) = &r.diff {
                    out_lines.push(d.clone());
                }
            } else {
                out_lines.extend(output::format_file_warnings(fmt, &r.display, &r.warnings, &colors, fixed_display));
            }
        }
        if !quiet && !silent {
            let files_word = |n: usize| if n == 1 { "file" } else { "files" };
            if fix_mode && !diff_mode {
                let fixed_total: usize = results.iter().map(|r| r.fixed_count).sum();
                let fixed_files = results.iter().filter(|r| r.fixed_count > 0 || r.changed).count();
                if total_warnings == 0 {
                    out_lines.push(String::new());
                    out_lines.push(format!("{} No issues found in {} {} ({}ms)", colors.c("1;32", "Success:"), total_files, files_word(total_files), elapsed));
                } else {
                    out_lines.push(String::new());
                    let nf = if fixed_files == 0 { files_with } else { fixed_files };
                    out_lines.push(format!("{} Fixed {}/{} issues in {} {} ({}ms)", colors.c("1;32", "Fixed:"), fixed_total, total_warnings, nf, files_word(nf), elapsed));
                }
            } else if total_warnings == 0 {
                out_lines.push(String::new());
                out_lines.push(format!("{} No issues found in {} {} ({}ms)", colors.c("1;32", "Success:"), total_files, files_word(total_files), elapsed));
            } else {
                out_lines.push(String::new());
                let files_part = if files_with == total_files {
                    format!("{} {}", files_with, files_word(files_with))
                } else {
                    format!("{}/{} files", files_with, total_files)
                };
                out_lines.push(format!("{} Found {} issues in {} ({}ms)", colors.c("33", "Issues:"), total_warnings, files_part, elapsed));
                if fixable > 0 {
                    out_lines.push(format!("Run `rumdl fmt` to automatically fix {} of the {} issues", fixable, total_warnings));
                }
            }
            if statistics && total_warnings > 0 {
                out_lines.push(String::new());
                out_lines.extend(statistics_lines(&results));
            }
        }
    }
    if !silent {
        let text = out_lines.join("\n");
        if !text.is_empty() {
            if to_stderr {
                eprintln!("{}", text);
            } else {
                println!("{}", text);
            }
        }
    }
    let _ = std::io::stdout().flush();
    let final_ws: Vec<Warning> = results.iter().flat_map(|r| if fix_mode && !diff_mode { r.remaining.clone() } else { r.warnings.clone() }).collect();
    if is_fmt && !check_mode {
        return 0;
    }
    if is_fmt && check_mode {
        return if results.iter().any(|r| r.changed) { 1 } else { 0 };
    }
    if fail_on_hit(&final_ws, &fail_on) {
        1
    } else {
        0
    }
}

fn statistics_lines(results: &[FileResult]) -> Vec<String> {
    let mut counts: Vec<(String, usize, usize)> = Vec::new();
    for r in results {
        for w in &r.warnings {
            if let Some(e) = counts.iter_mut().find(|x| x.0 == w.rule) {
                e.1 += 1;
                if w.fix.is_some() {
                    e.2 += 1;
                }
            } else {
                counts.push((w.rule.to_string(), 1, if w.fix.is_some() { 1 } else { 0 }));
            }
        }
    }
    counts.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let total: usize = counts.iter().map(|c| c.1).sum();
    let total_fix: usize = counts.iter().map(|c| c.2).sum();
    let mut out = vec![
        "Rule Violation Statistics:".to_string(),
        format!("{:<8} {:<12} {:<9} {:>10}", "Rule", "Violations", "Fixable", "Percentage"),
        "-".repeat(50),
    ];
    for (r, n, f) in &counts {
        let pct = *n as f64 * 100.0 / total as f64;
        out.push(format!("{:<8} {:<12} {:<9} {:>9.1}%", r, n, f, pct));
    }
    out.push("-".repeat(50));
    out.push(format!("{:<8} {:<12} {:<9} {:>9.1}%", "Total", total, total_fix, 100.0));
    out
}
