use crate::GlobalOpts;

pub fn suggest_rule(name: &str) -> Option<String> {
    let up = name.to_ascii_uppercase();
    let low = name.to_ascii_lowercase();
    let mut best: Option<(f64, String)> = None;
    for m in crate::rules::RULE_META {
        for cand in [m.name.to_string(), m.alias.to_string()] {
            let a = if cand.starts_with("MD") { &up } else { &low };
            let s = strsim_jw(a, &cand);
            if s > 0.7 && best.as_ref().map(|b| s > b.0).unwrap_or(true) {
                best = Some((s, cand.clone()));
            }
        }
    }
    best.map(|b| b.1)
}

fn strsim_jw(a: &str, b: &str) -> f64 {
    // Jaro-Winkler similarity
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let md = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut am = vec![false; a.len()];
    let mut bm = vec![false; b.len()];
    let mut m = 0;
    for i in 0..a.len() {
        let lo = i.saturating_sub(md);
        let hi = (i + md + 1).min(b.len());
        for j in lo..hi {
            if !bm[j] && a[i] == b[j] {
                am[i] = true;
                bm[j] = true;
                m += 1;
                break;
            }
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0;
    let mut k = 0;
    for i in 0..a.len() {
        if am[i] {
            while !bm[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = m as f64;
    let jaro = (m / a.len() as f64 + m / b.len() as f64 + (m - t as f64 / 2.0) / m) / 3.0;
    let mut l = 0;
    for i in 0..a.len().min(b.len()).min(4) {
        if a[i] == b[i] {
            l += 1;
        } else {
            break;
        }
    }
    jaro + l as f64 * 0.1 * (1.0 - jaro)
}

