use crate::config::RuleConfig;
use crate::context::{Ctx, Heading, HeadingStyle};
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD003;

#[derive(Clone, Copy, PartialEq, Debug)]
enum Target {
    Atx,
    AtxClosed,
    Setext,
}

fn style_name_found(h: &Heading) -> &'static str {
    match h.style {
        HeadingStyle::Atx => "# Heading",
        HeadingStyle::AtxClosed => "# Heading #",
        HeadingStyle::Setext1 => "Heading (underlined with =)",
        HeadingStyle::Setext2 => "Heading (underlined with -)",
    }
}

impl Rule for MD003 {
    fn name(&self) -> &'static str {
        "MD003"
    }
    fn description(&self) -> &'static str {
        "Heading style"
    }
    fn alias(&self) -> &'static str {
        "heading-style"
    }
    fn category(&self) -> &'static str {
        "heading"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("style", Value::String("consistent".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let style = cfg.str("style", "consistent");
        let heads: Vec<&Heading> = ctx.headings.iter().collect();
        if heads.is_empty() {
            return vec![];
        }
        // determine target style for levels
        let (base, atx_for_high): (Target, Target) = match style.as_str() {
            "atx" => (Target::Atx, Target::Atx),
            "atx_closed" | "atx-closed" => (Target::AtxClosed, Target::AtxClosed),
            "setext" | "setext_with_atx" | "setext-with-atx" => (Target::Setext, Target::Atx),
            "setext_with_atx_closed" | "setext-with-atx-closed" => (Target::Setext, Target::AtxClosed),
            _ => {
                let mut atx = 0;
                let mut closed = 0;
                let mut setext = 0;
                for h in &heads {
                    match h.style {
                        HeadingStyle::Atx => atx += 1,
                        HeadingStyle::AtxClosed => closed += 1,
                        _ => setext += 1,
                    }
                }
                if setext > atx && setext >= closed {
                    (Target::Setext, Target::Atx)
                } else if closed > atx && closed > setext {
                    (Target::AtxClosed, Target::AtxClosed)
                } else {
                    (Target::Atx, Target::Atx)
                }
            }
        };
        let mut out = Vec::new();
        for h in heads {
            let target = if base == Target::Setext && h.level > 2 { atx_for_high } else { base };
            let ok = match (target, h.style) {
                (Target::Atx, HeadingStyle::Atx) => true,
                (Target::AtxClosed, HeadingStyle::AtxClosed) => true,
                (Target::Setext, HeadingStyle::Setext1) | (Target::Setext, HeadingStyle::Setext2) => true,
                _ => false,
            };
            if ok {
                continue;
            }
            let expected = match target {
                Target::Atx => "# Heading".to_string(),
                Target::AtxClosed => "# Heading #".to_string(),
                Target::Setext => {
                    if h.level == 1 {
                        "Heading\n=======".to_string()
                    } else {
                        "Heading\n-------".to_string()
                    }
                }
            };
            let line = ctx.line(h.line);
            let li = &ctx.lines[h.line];
            let indent = &line[..leading_ws(line)];
            let text = &h.raw_text;
            let rep = match target {
                Target::Atx => format!("{}{} {}", indent, "#".repeat(h.level), text),
                Target::AtxClosed => format!("{}{} {} {}", indent, "#".repeat(h.level), text, "#".repeat(h.level)),
                Target::Setext => {
                    let ch = if h.level == 1 { "=" } else { "-" };
                    format!("{}{}\n{}{}", indent, text, indent, ch.repeat(clen(text).max(1)))
                }
            };
            let fix = Fix::new(li.start, li.end, rep);
            out.push(warn(
                "MD003",
                ctx,
                h.line,
                0,
                line.len(),
                format!("Heading style should be {}, found {}", expected, style_name_found(h)),
                Some(fix),
            ));
        }
        out
    }
}
