use crate::config::RuleConfig;
use crate::context::{Ctx, Flavor};
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD018;

pub fn line_skippable(ctx: &Ctx, i: usize) -> bool {
    let li = &ctx.lines[i];
    li.in_code || li.in_front_matter || li.in_html_block || li.in_html_comment || li.bq_depth > 0
}

impl Rule for MD018 {
    fn name(&self) -> &'static str {
        "MD018"
    }
    fn description(&self) -> &'static str {
        "No space after hash in heading"
    }
    fn alias(&self) -> &'static str {
        "no-missing-space-atx"
    }
    fn category(&self) -> &'static str {
        "heading"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("magiclink", Value::Boolean(false))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let magiclink = cfg.bool("magiclink", false);
        let mut out = Vec::new();
        for i in 0..ctx.num_lines() {
            if line_skippable(ctx, i) {
                continue;
            }
            let li = &ctx.lines[i];
            if !li.items.is_empty() && li.item_start.is_some() {
                continue;
            }
            let line = ctx.line(i);
            let b = line.as_bytes();
            if b.is_empty() || b[0] != b'#' {
                continue;
            }
            let mut h = 0;
            while h < b.len() && b[h] == b'#' {
                h += 1;
            }
            if h >= b.len() {
                continue;
            }
            let hashes = h.min(6);
            if h <= 6 {
                let next = line[h..].chars().next().unwrap();
                if next.is_whitespace() {
                    continue;
                }
                // emoji keycap
                if next == '\u{fe0f}' || next == '\u{20e3}' {
                    continue;
                }
                if magiclink && next.is_ascii_digit() {
                    continue;
                }
                if ctx.flavor == Flavor::Obsidian && h == 1 && !next.is_ascii_digit() {
                    continue;
                }
            } else {
                // 7+ hashes: check the char after 6 hashes is '#'
            }
            let rest = &line[hashes..];
            let fix = Fix::new(li.start, li.end, format!("{} {}", &line[..hashes], rest));
            out.push(warn("MD018", ctx, i, hashes, hashes, format!("No space after {} in heading", "#".repeat(hashes)), Some(fix)));
        }
        out
    }
}
