use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;

pub struct MD020;

/// Analyze a closed-ATX-like heading line content (after indentation).
/// Returns (open_hashes, space_after_open, text, space_before_close, close_hashes, close_start_byte)
pub fn analyze_closed(s: &str) -> Option<(usize, usize, String, usize, usize, usize)> {
    let b = s.as_bytes();
    let mut h = 0;
    while h < b.len() && b[h] == b'#' {
        h += 1;
    }
    if h == 0 || h > 6 {
        return None;
    }
    let t = s.trim_end_matches([' ', '\t']);
    let tb = t.as_bytes();
    let mut e = tb.len();
    while e > h && tb[e - 1] == b'#' {
        e -= 1;
    }
    let close = tb.len() - e;
    if close == 0 || e <= h {
        return None;
    }
    // escaped closing hash
    if tb[e - 1] == b'\\' {
        return None;
    }
    let inner = &t[h..e];
    let sa = inner.len() - inner.trim_start_matches([' ', '\t']).len();
    let sb = inner.len() - inner.trim_end_matches([' ', '\t']).len();
    let text = inner.trim().to_string();
    if text.is_empty() {
        return None;
    }
    Some((h, sa, text, sb, close, e))
}

impl Rule for MD020 {
    fn name(&self) -> &'static str {
        "MD020"
    }
    fn description(&self) -> &'static str {
        "No space inside hashes on closed heading"
    }
    fn alias(&self) -> &'static str {
        "no-missing-space-closed-atx"
    }
    fn category(&self) -> &'static str {
        "heading"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        for i in 0..ctx.num_lines() {
            if crate::rules::md018::line_skippable(ctx, i) {
                continue;
            }
            let li = &ctx.lines[i];
            if li.item_start.is_some() {
                continue;
            }
            let line = ctx.line(i);
            let ind = leading_ws(line);
            if ind > 3 {
                continue;
            }
            let s = &line[ind..];
            if !s.starts_with('#') {
                continue;
            }
            let (h, sa, text, sb, close, cstart) = match analyze_closed(s) {
                Some(x) => x,
                None => continue,
            };
            if sa > 0 && sb > 0 {
                continue;
            }
            let trailing = &s[s.trim_end_matches([' ', '\t']).len()..];
            let rep = format!("{}{} {} {}{}", &line[..ind], "#".repeat(h), text, "#".repeat(close), trailing);
            let fix = Fix::new(li.start, li.end, rep);
            let (msg, col) = if sa == 0 && sb == 0 {
                (format!("Missing space inside hashes on closed heading (with {} at start and end)", "#".repeat(h)), ind + h)
            } else if sa == 0 {
                (format!("Missing space after {} at start of closed heading", "#".repeat(h)), ind + h)
            } else {
                (format!("Missing space before {} at end of closed heading", "#".repeat(close)), ind + cstart - 1)
            };
            out.push(warn("MD020", ctx, i, col, col, msg, Some(fix)));
        }
        out
    }
}
