    }
    fn category(&self) -> &'static str {
        "heading"
    }
    fn default_severity(&self) -> Severity {
        Severity::Error
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("allow-different-nesting", Value::Boolean(false)), ("siblings-only", Value::Boolean(true))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let siblings = cfg.bool("siblings-only", true);
        let diff_nesting = cfg.bool("allow-different-nesting", false);
        let mut out = Vec::new();
        // stack of (level, idx)
        let mut stack: Vec<(usize, usize)> = Vec::new();
        let mut seen: Vec<(Option<usize>, usize, String)> = Vec::new();
        for (idx, h) in ctx.headings.iter().enumerate() {
            while let Some(&(l, _)) = stack.last() {
                if l >= h.level {
                    stack.pop();
                } else {
                    break;
                }
            }
            let parent = stack.last().map(|x| x.1);
            let text = h.text.trim().to_string();
            if !text.is_empty() {
                let dup = seen.iter().any(|(p, lvl, t)| {
                    if *t != text {
                        return false;
                    }
                    if siblings {
                        *p == parent && *lvl == h.level
                    } else if diff_nesting {
                        *lvl == h.level
                    } else {
                        true
                    }
                });
                if dup {
                    let line = ctx.line(h.line);
                    let ts = h.text_start.min(line.len());
                    let te = (ts + text.len()).min(line.len());
                    out.push(warn("MD024", ctx, h.line, ts, te, format!("Duplicate heading: '{}'.", text), None));
                }
                seen.push((parent, h.level, text));
            }
            stack.push((h.level, idx));
        }
        out
    }
}
