use crate::config::RuleConfig;
use crate::context::{Ctx, HeadingStyle};
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD026;

impl Rule for MD026 {
    fn name(&self) -> &'static str {
        "MD026"
    }
    fn description(&self) -> &'static str {
        "Trailing punctuation in heading"
    }
    fn alias(&self) -> &'static str {
        "no-trailing-punctuation"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("punctuation", Value::String(".,;:!".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let punct = cfg.str("punctuation", ".,;:!");
        if punct.is_empty() {
            return vec![];
        }
        let mut out = Vec::new();
        for h in &ctx.headings {
            let text = &h.raw_text;
            let last = match text.chars().last() {
                Some(c) => c,
                None => continue,
            };
            if !punct.contains(last) {
                continue;
            }
            let stripped = text.trim_end_matches(|c: char| punct.contains(c));
            let line = ctx.line(h.line);
            let li = &ctx.lines[h.line];
            let ts = h.text_start.min(line.len());
            let pstart = ts + stripped.len();
            let pend = ts + text.len();
            let rep = match h.style {
                HeadingStyle::Atx => {
                    let pre = &line[..ts];
                    format!("{}{}", pre.trim_end_matches(|c: char| c == ' ' || c == '\t').to_string() + " ", stripped)
                }
                HeadingStyle::AtxClosed => {
                    let pre = &line[..ts];
                    format!("{} {} {}", pre.trim_end(), stripped, "#".repeat(h.closing_hashes))
                }
                _ => format!("{}{}", &line[..ts], stripped),
            };
            let fix = Fix::new(li.start, li.end, rep);
            out.push(warn(
                "MD026",
                ctx,
                h.line,
                pstart,
                pend,
                format!("Heading '{}' ends with punctuation '{}'", text, last),
                Some(fix),
            ));
        }
        out
    }
}
