use crate::blocks::Kind;
use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD032;

fn bq_prefix(line: &str) -> String {
    // prefix consisting of blockquote markers and spaces
    let mut end = 0;
    let b = line.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'>' {
            end = i + 1;
            i += 1;
        } else if b[i] == b' ' || b[i] == b'\t' {
            i += 1;
        } else {
            break;
        }
    }
    line[..end].to_string()
}

pub fn exempt_neighbor(ctx: &Ctx, i: usize, list_bq: usize) -> bool {
    let li = &ctx.lines[i];
    if li.in_html_block || li.in_html_comment {
        return true;
    }
    if li.kind == Kind::FenceClose {
        return true;
    }
    if li.in_front_matter {
        return true;
    }
    if li.bq_depth != list_bq {
        return true;
    }
    false
}

impl Rule for MD032 {
    fn name(&self) -> &'static str {
        "MD032"
    }
    fn description(&self) -> &'static str {
        "Lists should be surrounded by blank lines"
    }
    fn alias(&self) -> &'static str {
        "blanks-around-lists"
    }
    fn category(&self) -> &'static str {
        "list"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("allow-lazy-continuation", Value::Boolean(true))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let allow_lazy = cfg.bool("allow-lazy-continuation", true);
        let n = ctx.num_lines();
        let mut out = Vec::new();
        for g in ctx.list_groups() {
            if g.parent_item.is_some() {
                continue;
            }
            let s = g.start_line;
            let mut e = g.end_line;
            // lazy line followed by setext underline: treat as heading
            while e > s && ctx.lines[e].lazy && e + 1 < n && {
                let t = ctx.line_content(e + 1).trim();
                !t.is_empty() && (t.chars().all(|c| c == '-') || t.chars().all(|c| c == '=')) && t.len() >= 1
            } {
                e -= 1;
            }
            if s > 0 {
                let p = s - 1;
                if !ctx.is_blank_ctx(p) && !exempt_neighbor(ctx, p, g.bq_depth) {
                    let line = ctx.line(s);
                    let pre = if g.bq_depth > 0 { format!("{}\n", bq_prefix(line).trim_end().to_string() + " ") } else { "\n".to_string() };
                    let pos = ctx.lines[s].start;
                    out.push(warn("MD032", ctx, s, 0, line.len(), "List should be preceded by blank line", Some(Fix::new(pos, pos, pre))));
                }
            }
            if !allow_lazy {
                for l in s..=e {
                    if ctx.lines[l].lazy {
                        // find content col of containing item
                        let it = ctx.lines[l].items.last().copied();
                        if let Some(it) = it {
                            let col = ctx.blocks.items[it].content_col;
                            let pos = ctx.lines[l].start;
                            out.push(warn(
                                "MD032",
                                ctx,
                                l,
                                0,
                                ctx.line(l).len(),
                                "Lazy continuation line should be properly indented or preceded by blank line",
                                Some(Fix::new(pos, pos, " ".repeat(col))),
                            ));
                        }
                    }
                }
            }
            if e + 1 < n {
                let q = e + 1;
                if !ctx.is_blank_ctx(q) && !exempt_neighbor(ctx, q, g.bq_depth) {
                    let line = ctx.line(e);
                    let pre = if g.bq_depth > 0 { format!("{}\n", bq_prefix(ctx.line(q)).trim_end().to_string() + " ") } else { "\n".to_string() };
                    let pos = ctx.lines[q].start;
                    out.push(warn("MD032", ctx, e, 0, line.len(), "List should be followed by blank line", Some(Fix::new(pos, pos, pre))));
                }
            }
        }
        out
    }
}
