use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD004;

impl Rule for MD004 {
    fn name(&self) -> &'static str {
        "MD004"
    }
    fn description(&self) -> &'static str {
        "Use consistent style for unordered list markers"
    }
    fn alias(&self) -> &'static str {
        "ul-style"
    }
    fn category(&self) -> &'static str {
        "list"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("style", Value::String("consistent".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let style = cfg.str("style", "consistent");
        let items: Vec<_> = ctx.blocks.items.iter().filter(|i| !i.ordered).collect();
        if items.is_empty() {
            return vec![];
        }
        let fixed: Option<char> = match style.as_str() {
            "asterisk" => Some('*'),
            "plus" => Some('+'),
            "dash" => Some('-'),
            "sublist" => None,
            _ => {
                let c = |ch: char| items.iter().filter(|i| i.bullet == ch).count();
                let (d, a, p) = (c('-'), c('*'), c('+'));
                if d >= a && d >= p {
                    Some('-')
                } else if a >= p {
                    Some('*')
                } else {
                    Some('+')
                }
            }
        };
        let mut out = Vec::new();
        for it in items {
            // nesting level among unordered ancestors
            let (expected, suffix) = match fixed {
                Some(c) => (c, String::new()),
                None => {
                    let mut lvl = 0;
                    let mut p = it.parent;
                    while let Some(pi) = p {
                        if !ctx.blocks.items[pi].ordered {
                            lvl += 1;
                        }
                        p = ctx.blocks.items[pi].parent;
                    }
                    let c = ['*', '+', '-'][lvl % 3];
                    (c, format!(" for nesting level {}", lvl))
                }
            };
            if it.bullet == expected {
                continue;
            }
            let li = &ctx.lines[it.line];
            let pos = li.start + it.marker_byte;
            out.push(warn(
                "MD004",
                ctx,
                it.line,
                it.marker_byte,
                it.marker_byte + 1,
                format!("List marker '{}' does not match expected style '{}'{}", it.bullet, expected, suffix),
                Some(Fix::new(pos, pos + 1, expected.to_string())),
            ));
        }
        out
    }
}
