use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD029;

#[derive(Clone, Copy, PartialEq)]
enum St {
    One,
    Ordered,
    Ordered0,
}

fn st_name(s: St) -> &'static str {
    match s {
        St::One => "one",
        St::Ordered => "ordered",
        St::Ordered0 => "ordered0",
    }
}

impl Rule for MD029 {
    fn name(&self) -> &'static str {
        "MD029"
    }
    fn description(&self) -> &'static str {
        "Ordered list marker value"
    }
    fn alias(&self) -> &'static str {
        "ol-prefix"
    }
    fn category(&self) -> &'static str {
        "list"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("style", Value::String("one-or-ordered".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        if !ctx.content.contains(['-', '*', '+']) {
            return vec![];
        }
        let style = cfg.str("style", "one-or-ordered");
        let items = &ctx.blocks.items;
        // build groups: per list, split by marker column; under-indented sublists flagged specially
        struct Group {
            items: Vec<usize>,
            sub: bool,
        }
        let mut groups: Vec<Group> = Vec::new();
        for l in &ctx.blocks.lists {
            if !l.ordered {
                continue;
            }
            let first_col = items[l.items[0]].marker_col;
            let mut main = Vec::new();
            let mut subs: Vec<Vec<usize>> = Vec::new();
            let mut cur_sub: Option<(usize, Vec<usize>)> = None;
            for &i in &l.items {
                let c = items[i].marker_col;
                if c == first_col {
                    if let Some((_, s)) = cur_sub.take() {
                        subs.push(s);
                    }
                    main.push(i);
                } else {
                    match cur_sub.as_mut() {
                        Some((cc, s)) if *cc == c => s.push(i),
                        _ => {
                            if let Some((_, s)) = cur_sub.take() {
                                subs.push(s);
                            }
                            cur_sub = Some((c, vec![i]));
                        }
                    }
                }
            }
            if let Some((_, s)) = cur_sub.take() {
                subs.push(s);
            }
            groups.push(Group { items: main, sub: false });
            for s in subs {
                groups.push(Group { items: s, sub: true });
            }
        }
        // under-indented nested lists (parent content col > marker col) are also "sub"
        for g in groups.iter_mut() {
            if g.sub {
                continue;
            }
            let f = &items[g.items[0]];
            if let Some(p) = f.parent {
                let pi = &items[p];
                if f.marker_col < pi.content_col {
                    g.sub = true;
                }
            }
        }
        // consistent: determine document style
        let doc_style = if style == "consistent" {
            let mut ones = 0;
            let mut ord = 0;
            for g in &groups {
                let nums: Vec<u64> = g.items.iter().map(|&i| items[i].number.unwrap_or(0)).collect();
                if nums.len() > 1 && nums.iter().all(|&n| n == 1) {
                    ones += 1;
                } else {
                    ord += 1;
                }
            }
            Some(if ones > ord { St::One } else { St::Ordered })
        } else {
            None
        };
        let mut out = Vec::new();
        for g in &groups {
            let nums: Vec<u64> = g.items.iter().map(|&i| items[i].number.unwrap_or(0)).collect();
            let start = nums[0];
            let (st, kind, base, fixable) = match style.as_str() {
                "one" | "one-one" | "one_one" => (St::One, "configured", 1, true),
                "ordered" => (St::Ordered, "configured", start, true),
                "ordered0" | "zero" => (St::Ordered0, "configured", 0, true),
                "consistent" => {
                    let s = doc_style.unwrap();
                    (s, "document", if s == St::Ordered { start } else { 1 }, start == 1 || s == St::One)
                }
                _ => {
                    if g.sub {
                        if nums.len() == 1 {
                            (St::One, "list", 1, true)
                        } else {
                            (St::Ordered, "list", 1, true)
                        }
                    } else if nums.iter().all(|&n| n == 1) {
                        (St::One, "list", 1, true)
                    } else {
                        (St::Ordered, "list", start, start == 1)
                    }
                }
            };
            for (k, &i) in g.items.iter().enumerate() {
                let n = nums[k];
                let exp = match st {
                    St::One => 1,
                    St::Ordered => base + k as u64,
                    St::Ordered0 => k as u64,
                };
                if n == exp {
                    continue;
                }
                let it = &items[i];
                let li = &ctx.lines[it.line];
                let digits = it.marker.len() - 1;
                let pos = li.start + it.marker_byte;
                let fix = if fixable { Some(Fix::new(pos, pos + digits, exp.to_string())) } else { None };
                out.push(warn(
                    "MD029",
                    ctx,
                    it.line,
                    it.marker_byte,
                    it.marker_byte + it.marker.len(),
                    format!("Ordered list item number {} does not match {} style '{}' (expected {})", n, kind, st_name(st), exp),
                    fix,
                ));
            }
        }
        out.sort_by_key(|w| (w.line, w.column));
        out
    }
}
