use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD046;

fn looks_like_list_item(s: &str) -> bool {
    let t = s.trim_start();
    crate::blocks::parse_marker(t).is_some()
}

/// returns true if style is fenced
fn detect_style(ctx: &Ctx, style: &str) -> bool {
    match style {
        "fenced" => true,
        "indented" => false,
        _ => {
            let mut fenced = 0;
            let mut indented = 0;
            for cb in &ctx.blocks.code_blocks {
                if cb.fenced {
                    fenced += 1;
                } else {
                    if cb.in_list {
                        continue;
                    }
                    let first = ctx.line(cb.start_line);
                    if looks_like_list_item(first) {
                        continue;
                    }
                    indented += 1;
                }
            }
            !(indented > fenced)
        }
    }
}

impl Rule for MD046 {
    fn name(&self) -> &'static str {
        "MD046"
    }
    fn description(&self) -> &'static str {
        "Code blocks should use a consistent style"
    }
    fn alias(&self) -> &'static str {
        "code-block-style"
    }
    fn category(&self) -> &'static str {
        "code-block"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("style", Value::String("consistent".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let style = cfg.str("style", "consistent");
        let fenced_style = detect_style(ctx, &style);
        let mut out = Vec::new();
        for cb in &ctx.blocks.code_blocks {
            let l = cb.start_line;
            let li = &ctx.lines[l];
            let line = ctx.line(l);
            if cb.fenced {
                if !cb.closed {
                    let fence: String = std::iter::repeat(cb.fence_char).take(cb.fence_len).collect();
                    let end = ctx.content.len();
                    let rep = if ctx.content.ends_with('\n') { format!("{}\n", fence) } else { format!("\n{}", fence) };
                    let _ = rep;
                    out.push(warn(
                        "MD046",
                        ctx,
                        l,
                        0,
                        line.len(),
                        format!("Code block opened with '{}' but never closed", fence),
                        Some(Fix::new(end, end, format!("\n{}", fence))),
                    ));
                    continue;
                }
                if !fenced_style {
                    out.push(warn("MD046", ctx, l, 0, line.len(), "Use indented code blocks", Some(Fix::new(li.start, li.start, ""))));
                }
            } else if fenced_style {
                let content = ctx.line_content(l).to_string();
                out.push(warn("MD046", ctx, l, 0, line.len(), "Use fenced code blocks", Some(Fix::new(li.start, li.start, format!("```\n{}", content.trim_start())))));
            }
        }
        out
    }
    fn fix(&self, ctx: &Ctx, cfg: &RuleConfig, warnings: &[Warning]) -> Option<String> {
        let style = cfg.str("style", "consistent");
        let fenced_style = detect_style(ctx, &style);
        let flagged: std::collections::HashSet<usize> = warnings.iter().map(|w| w.line - 1).collect();
        let n = ctx.num_lines();
        let mut out_lines: Vec<String> = Vec::new();
        let mut i = 0;
        let mut changed = false;
        while i < n {
            let cbi = ctx.lines[i].code_block;
            if let Some(ci) = cbi {
                let cb = &ctx.blocks.code_blocks[ci];
                if cb.start_line == i && flagged.contains(&i) {
                    if cb.fenced && !cb.closed {
                        // add closing fence at end
                        for l in cb.start_line..n {
                            out_lines.push(ctx.line(l).to_string());
                        }
                        let fence: String = std::iter::repeat(cb.fence_char).take(cb.fence_len).collect();
                        out_lines.push(fence);
                        changed = true;
                        i = n;
                        continue;
                    }
                    if cb.fenced && !fenced_style && !cb.in_list && cb.bq_depth == 0 {
                        for l in (cb.start_line + 1)..cb.end_line {
                            let t = ctx.line(l);
                            out_lines.push(if t.is_empty() { String::new() } else { format!("    {}", t) });
                        }
                        changed = true;
                        i = cb.end_line + 1;
                        continue;
                    }
                    if !cb.fenced && fenced_style && !cb.in_list && cb.bq_depth == 0 {
                        out_lines.push("```".to_string());
                        for l in cb.start_line..=cb.end_line {
                            let t = ctx.line(l);
                            let ws = t.len() - t.trim_start_matches(' ').len();
                            out_lines.push(t[ws.min(4)..].to_string());
                        }
                        out_lines.push("```".to_string());
                        changed = true;
                        i = cb.end_line + 1;
                        continue;
                    }
                }
            }
            out_lines.push(ctx.line(i).to_string());
            i += 1;
        }
        if !changed {
            return None;
        }
        let mut s = out_lines.join("\n");
        if ctx.content.ends_with('\n') {
            s.push('\n');
        }
        Some(s)
    }
}
