use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD048;

impl Rule for MD048 {
    fn name(&self) -> &'static str {
        "MD048"
    }
    fn description(&self) -> &'static str {
        "Code fence style should be consistent"
    }
    fn alias(&self) -> &'static str {
        "code-fence-style"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("style", Value::String("consistent".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let style = cfg.str("style", "consistent");
        let fences: Vec<_> = ctx.blocks.code_blocks.iter().filter(|c| c.fenced).collect();
        if fences.is_empty() {
            return vec![];
        }
        let target = match style.as_str() {
            "backtick" => '`',
            "tilde" => '~',
            _ => {
                let bt = fences.iter().filter(|c| c.fence_char == '`').count();
                let tl = fences.len() - bt;
                if tl > bt {
                    '~'
                } else {
                    '`'
                }
            }
        };
        let (tname, fname) = if target == '`' { ("```", "~~~") } else { ("~~~", "```") };
        let mut out = Vec::new();
        for cb in fences {
            if cb.fence_char == target {
                continue;
            }
            for l in [cb.start_line, cb.end_line] {
                if l == cb.end_line && (!cb.closed || cb.end_line == cb.start_line) {
                    continue;
                }
                let line = ctx.line(l);
                let li = &ctx.lines[l];
                let ind = leading_ws(line);
                let t = line[ind..].trim_end();
                let rep = t.replacen(fname, tname, 1);
                let fix = Fix::new(li.start + ind, li.start + ind + t.len(), rep);
                out.push(warn("MD048", ctx, l, 0, line.len(), format!("Code fence style: use {} instead of {}", tname, fname), Some(fix)));
            }
        }
        out
    }
}
EOF
