        let allowed = cfg.str_list("allowed-languages").unwrap_or_default();
        let disallowed = cfg.str_list("disallowed-languages").unwrap_or_default();
        let mut out = Vec::new();
        for cb in &ctx.blocks.code_blocks {
            if !cb.fenced {
                continue;
            }
            let l = cb.start_line;
            let line = ctx.line(l);
            let li = &ctx.lines[l];
            let ind = leading_ws(line);
            let fence: String = std::iter::repeat(cb.fence_char).take(cb.fence_len).collect();
            let lang = cb.info.split_whitespace().next().unwrap_or("").to_string();
            if lang.is_empty() {
                let fix = Fix::new(li.start + ind, li.start + ind + cb.fence_len, format!("{}text", fence));
                out.push(warn("MD040", ctx, l, 0, line.len(), "Code block (```) missing language", Some(fix)));
                continue;
            }
            let lang_clean = lang.trim_start_matches('{').trim_end_matches('}').to_string();
            if !allowed.is_empty() && !allowed.iter().any(|a| a.eq_ignore_ascii_case(&lang_clean)) {
                out.push(warn(
                    "MD040",
                    ctx,
                    l,
                    0,
                    line.len(),
                    format!("Language '{}' is not in the allowed list: {}", lang_clean, allowed.join(", ")),
                    None,
                ));
                continue;
            }
            if disallowed.iter().any(|a| a.eq_ignore_ascii_case(&lang_clean)) {
                out.push(warn("MD040", ctx, l, 0, line.len(), format!("Language '{}' is disallowed", lang_clean), None));
            }
        }
        out
    }
}
