            if line.trim() != target {
                out.push(warn(
                    "MD035",
                    ctx,
                    i,
                    0,
                    line.len(),
                    format!("Horizontal rule style should be \"{}\"", target),
                    Some(Fix::new(li.start, li.start, target.clone())),
                ));
            }
        }
        out
    }
