        "MD035"
    }
    fn description(&self) -> &'static str {
        "Horizontal rule style"
    }
    fn alias(&self) -> &'static str {
        "hr-style"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("style", Value::String("consistent".into()))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let style = cfg.str("style", "consistent");
        let hrs: Vec<usize> = (0..ctx.num_lines()).filter(|&i| ctx.lines[i].kind == Kind::ThematicBreak && ctx.lines[i].bq_depth == 0).collect();
        if hrs.is_empty() {
            return vec![];
        }
        let target = if style == "consistent" { ctx.line(hrs[0]).trim().to_string() } else { style.clone() };
        let mut out = Vec::new();
        for i in hrs {
            let line = ctx.line(i);
            let li = &ctx.lines[i];
            let ind = leading_ws(line);
            if ind > 0 {
                out.push(warn("MD035", ctx, i, 0, line.len(), "Horizontal rule should not be indented", Some(Fix::new(li.start, li.start, target.clone()))));
                continue;
            }
            if line.trim() != target {
                out.push(warn(
                    "MD035",
                    ctx,
                    i,
                    0,
                    line.len(),
                    format!("Horizontal rule style should be \"{}\"", target),
                    Some(Fix::new(li.start, li.start, target.clone())),
                ));
            }
        }
        out
    }
    fn fix(&self, ctx: &Ctx, _cfg: &RuleConfig, warnings: &[Warning]) -> Option<String> {
        let ws: Vec<Warning> = warnings
            .iter()
            .cloned()
            .map(|mut w| {
                let l = w.line - 1;
                if let Some(f) = w.fix.as_mut() {
                    f.end = ctx.lines[l].end;
                }
                w
            })
            .collect();
        apply_fixes(&ctx.content, &ws)
    }
}
