use crate::blocks::Kind;
use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use regex::Regex;
use std::sync::OnceLock;

pub struct MD034;

fn url_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r#"(?:https?|ftp)://[^\s<>"'`\\\[\]]+|www\.[^\s<>"'`\\\[\]]+|xmpp:[^\s<>"'`\\\[\]]+"#).unwrap())
}
fn email_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}").unwrap())
}

pub fn trim_url(u: &str) -> &str {
    let mut s = u;
    loop {
        if let Some(c) = s.chars().last() {
            if ".,!?;".contains(c) {
                s = &s[..s.len() - 1];
                continue;
            }
            if c == ')' {
                let open = s.matches('(').count();
                let close = s.matches(')').count();
                if close > open {
                    s = &s[..s.len() - 1];
                    continue;
                }
            }
        }
        break;
    }
    s
}

/// excluded byte ranges for inline scanning
pub fn excluded_ranges(ctx: &Ctx) -> Vec<(usize, usize)> {
    let mut r: Vec<(usize, usize)> = Vec::new();
    for c in &ctx.code_spans {
        r.push((c.start, c.end));
    }
    for l in &ctx.links {
        r.push((l.start, l.end));
    }
    for l in &ctx.unresolved {
        if l.kind != crate::inline::LinkKind::Shortcut {
            r.push((l.start, l.end));
        }
    }
    for h in &ctx.html_tags {
        r.push((h.start, h.end));
    }
    for &(a, b) in &ctx.html_comment_ranges {
        r.push((a, b));
    }
    r
}

pub fn in_ranges(r: &[(usize, usize)], a: usize, b: usize) -> bool {
    r.iter().any(|&(x, y)| a < y && b > x)
}

impl Rule for MD034 {
    fn name(&self) -> &'static str {
        "MD034"
    }
    fn description(&self) -> &'static str {
        "No bare URLs - wrap URLs in angle brackets"
    }
    fn alias(&self) -> &'static str {
        "no-bare-urls"
    }
    fn category(&self) -> &'static str {
        "link"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        let excl = excluded_ranges(ctx);
        for i in 0..ctx.num_lines() {
            let li = &ctx.lines[i];
            if !matches!(li.kind, Kind::Paragraph | Kind::Atx | Kind::SetextText | Kind::Table) {
                continue;
            }
            if li.ref_def.is_some() || li.in_html_comment {
                continue;
            }
            let line = ctx.line(i);
            let mut found: Vec<(usize, usize, String, bool)> = Vec::new();
            for m in url_re().find_iter(line) {
                let s = m.start();
                let raw = m.as_str();
                let t = trim_url(raw);
                if t.starts_with("www.") {
                    if s > 0 {
                        let pc = line[..s].chars().last().unwrap();
                        if pc.is_alphanumeric() || pc == '/' || pc == '.' || pc == '@' {
                            continue;
                        }
                    }
                    if !t[4..].contains('.') && t.len() <= 4 {
                        continue;
                    }
                } else if let Some(p) = t.find("://") {
                    if t.len() <= p + 3 {
                        continue;
                    }
                } else if t.starts_with("xmpp:") {
                    if !t.contains('@') {
                        continue;
                    }
                }
                found.push((s, s + t.len(), t.to_string(), false));
            }
            for m in email_re().find_iter(line) {
                let (s, e) = (m.start(), m.end());
                if found.iter().any(|f| s < f.1 && e > f.0) {
                    continue;
                }
                found.push((s, e, m.as_str().to_string(), true));
            }
            found.sort_by_key(|f| f.0);
            for (s, e, t, is_email) in found {
                let abs_s = li.start + s;
                let abs_e = li.start + e;
                if in_ranges(&excl, abs_s, abs_e) {
                    continue;
                }
                let (msg, rep) = if is_email {
                    (format!("Email address without angle brackets or link formatting: '{}'", t), format!("<{}>", t))
                } else if t.starts_with("www.") {
                    (format!("URL without angle brackets or link formatting: '{}'", t), format!("<https://{}>", t))
                } else {
                    (format!("URL without angle brackets or link formatting: '{}'", t), format!("<{}>", t))
                };
                out.push(warn("MD034", ctx, i, s, e, msg, Some(Fix::new(abs_s, abs_e, rep))));
            }
        }
        out
    }
}
