    fn alias(&self) -> &'static str {
        "no-space-in-code"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        for cs in &ctx.code_spans {
            let content = &ctx.content[cs.content_start..cs.content_end];
            if content.contains('\n') {
