use crate::blocks::Kind;
use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;

pub struct MD037;

fn is_word(c: char) -> bool {
    c.is_alphanumeric()
}

pub fn math_ranges(line: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let b = line.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'$' {
            let dbl = i + 1 < b.len() && b[i + 1] == b'$';
            let w = if dbl { 2 } else { 1 };
            let st = i;
            let mut j = i + w;
            let mut found = None;
            while j < b.len() {
                if b[j] == b'$' {
                    if dbl {
                        if j + 1 < b.len() && b[j + 1] == b'$' {
                            found = Some(j + 2);
                            break;
                        }
                    } else {
                        found = Some(j + 1);
                        break;
                    }
                }
                j += 1;
            }
            if let Some(e) = found {
                if e > st + w + w - 1 {
                    out.push((st, e));
                    i = e;
                    continue;
                }
            }
            i += w;
            continue;
        }
        i += 1;
    }
    out
}

impl Rule for MD037 {
    fn name(&self) -> &'static str {
        "MD037"
    }
    fn description(&self) -> &'static str {
        "Spaces inside emphasis markers"
    }
    fn alias(&self) -> &'static str {
        "no-space-in-emphasis"
    }
    fn category(&self) -> &'static str {
        "emphasis"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        for i in 0..ctx.num_lines() {
            let li = &ctx.lines[i];
            if !matches!(li.kind, Kind::Paragraph | Kind::Atx | Kind::SetextText | Kind::Table) {
                continue;
            }
            if li.in_html_comment {
                continue;
            }
            let line = ctx.line(i);
            let cs = li.content_start.min(line.len());
            // skip list marker
            let mut start = cs;
            if let Some(it) = li.item_start {
                let item = &ctx.blocks.items[it];
                start = start.max(item.content_byte.min(line.len()));
            }
            if li.kind == Kind::Atx {
                let rest = &line[start..];
                let ws = leading_ws(rest);
                let h = rest[ws..].bytes().take_while(|&b| b == b'#').count();
                start += ws + h;
            }
            let maths = math_ranges(line);
            let chars: Vec<(usize, char)> = line.char_indices().filter(|(b, _)| *b >= start).collect();
            // runs of * or _
            struct Run {
                pos: usize,
                ch: char,
                len: usize,
                ci: usize,
            }
            let mut runs: Vec<Run> = Vec::new();
            let mut k = 0;
            while k < chars.len() {
                let (b, c) = chars[k];
                if c == '\\' {
                    k += 2;
                    continue;
                }
                if c == '*' || c == '_' {
                    let mut n = 0;
                    while k + n < chars.len() && chars[k + n].1 == c {
                        n += 1;
                    }
                    let abs = li.start + b;
                    if !ctx.is_in_code_span(abs) && !maths.iter().any(|&(a, e)| b >= a && b < e) {
                        runs.push(Run { pos: b, ch: c, len: n, ci: k });
                    }
                    k += n;
                    continue;
                }
                k += 1;
            }
            let mut r = 0;
            while r < runs.len() {
                let o = &runs[r];
                if o.len > 2 {
                    r += 1;
                    continue;
                }
                let before = if o.ci > 0 { Some(chars[o.ci - 1].1) } else { None };
                if before.map(is_word).unwrap_or(false) {
                    r += 1;
                    continue;
                }
                // find closer
                let mut found = None;
                for (q, c) in runs.iter().enumerate().skip(r + 1) {
                    if c.ch == o.ch && c.len == o.len {
                        let after = chars.get(c.ci + c.len).map(|x| x.1);
                        if after.map(is_word).unwrap_or(false) {
                            continue;
                        }
                        found = Some(q);
                        break;
                    }
                }
                let q = match found {
                    Some(q) => q,
                    None => {
                        r += 1;
                        continue;
                    }
                };
                let c = &runs[q];
                let inner_s = o.pos + o.len;
                let inner_e = c.pos;
                let inner = &line[inner_s..inner_e];
                let has_marker_inside = runs[r + 1..q].iter().any(|x| x.ch == o.ch) || inner.contains(o.ch);
                if !has_marker_inside && !inner.trim().is_empty() && (inner.starts_with(char::is_whitespace) || inner.ends_with(char::is_whitespace)) {
                    let m: String = std::iter::repeat(o.ch).take(o.len).collect();
                    let full = &line[o.pos..c.pos + c.len];
                    let rep = format!("{}{}{}", m, inner.trim(), m);
                    out.push(warn(
                        "MD037",
                        ctx,
                        i,
                        o.pos,
                        c.pos + c.len,
                        format!("Spaces inside emphasis markers: \"{}\"", full),
                        Some(Fix::new(li.start + o.pos, li.start + c.pos + c.len, rep)),
                    ));
                }
                r = q + 1;
            }
        }
        out
    }
}
