use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD049;

fn run_len_at(s: &str, pos: usize, ch: u8) -> usize {
    let b = s.as_bytes();
    let mut a = pos;
    while a > 0 && b[a - 1] == ch {
        a -= 1;
    }
    let mut e = pos;
    while e < b.len() && b[e] == ch {
        e += 1;
    }
    e - a
}

pub fn emphasis_check(ctx: &Ctx, cfg: &RuleConfig, strong: bool, rule: &'static str) -> Vec<Warning> {
    let style = cfg.str("style", "consistent");
    let spans: Vec<_> = ctx
        .emph
        .iter()
        .filter(|e| e.strong == strong)
        .filter(|e| {
            let ch = e.ch as u8;
            let rl = run_len_at(&ctx.content, e.start, ch);
            rl < 3
        })
        .filter(|e| {
            let l = ctx.line_of_offset(e.start);
            !ctx.lines[l].in_code
        })
        .collect();
    if spans.is_empty() {
        return vec![];
    }
    let target = match style.as_str() {
        "asterisk" => '*',
        "underscore" => '_',
        _ => {
            let a = spans.iter().filter(|e| e.ch == '*').count();
            let u = spans.len() - a;
            if a > u {
                '*'
            } else if u > a {
                '_'
            } else {
                let mut sorted = spans.clone();
                sorted.sort_by_key(|e| e.start);
                sorted[0].ch
            }
        }
    };
    let mut out = Vec::new();
    let (tm, what) = if strong { (if target == '*' { "**" } else { "__" }, "Strong emphasis") } else { (if target == '*' { "*" } else { "_" }, "Emphasis") };
    let fm = if strong { if target == '*' { "__" } else { "**" } } else if target == '*' { "_" } else { "*" };
    let mut sorted = spans.clone();
    sorted.sort_by_key(|e| e.start);
    for e in sorted {
        if e.ch == target {
            continue;
        }
        let inner = &ctx.content[e.content_start..e.content_end];
        let rep = format!("{}{}{}", tm, inner, tm);
        out.push(warn_abs(rule, ctx, e.start, e.end, format!("{} should use {} instead of {}", what, tm, fm), Some(Fix::new(e.start, e.end, rep))));
    }
    out
}

