use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::inline::LinkKind;
use crate::rule::*;
use crate::rules::util::*;
use std::collections::HashSet;
use toml::Value;

pub struct MD051;

/// strip inline markdown for anchor generation
pub fn strip_inline(text: &str) -> String {
    let mut s = String::new();
    let b: Vec<char> = text.chars().collect();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == '[' {
            // link: keep text
            if let Some(close) = b[i + 1..].iter().position(|&x| x == ']') {
                let close = i + 1 + close;
                if close + 1 < b.len() && b[close + 1] == '(' {
                    if let Some(pe) = b[close + 1..].iter().position(|&x| x == ')') {
                        let inner: String = b[i + 1..close].iter().collect();
                        s.push_str(&strip_inline(&inner));
                        i = close + 1 + pe + 1;
                        continue;
                    }
                }
            }
        }
        if c == '`' || c == '*' {
            i += 1;
            continue;
        }
        s.push(c);
        i += 1;
    }
    s
}

pub fn github_anchor(text: &str) -> String {
    let t = strip_inline(text).to_lowercase();
    let mut out = String::new();
    for c in t.chars() {
        if c.is_alphanumeric() || c == '-' || c == '_' {
            out.push(c);
        } else if c == ' ' {
            out.push('-');
        }
    }
    out
}

pub fn collect_anchors(ctx: &Ctx) -> HashSet<String> {
    let mut set = HashSet::new();
    let mut counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for h in &ctx.headings {
        let a = github_anchor(&h.text);
        let n = counts.entry(a.clone()).or_insert(0);
        let anchor = if *n == 0 { a.clone() } else { format!("{}-{}", a, n) };
        *n += 1;
        set.insert(anchor);
        if let Some(id) = &h.custom_id {
            set.insert(id.to_lowercase());
        }
    }
    // html ids and names
    let re = regex::Regex::new(r#"(?i)\b(?:id|name)\s*=\s*["']([^"']+)["']"#).unwrap();
    for (s, e, _) in crate::rules::md033::all_open_tags(ctx) {
        for c in re.captures_iter(&ctx.content[s..e]) {
            set.insert(c[1].to_lowercase());
        }
    }
    set
}

impl Rule for MD051 {
    fn name(&self) -> &'static str {
        "MD051"
    }
    fn description(&self) -> &'static str {
        "Link fragments should reference valid headings"
    }
    fn alias(&self) -> &'static str {
        "link-fragments"
    }
    fn category(&self) -> &'static str {
        "link"
    }
    fn default_severity(&self) -> Severity {
        Severity::Error
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("anchor-style", Value::String("github".into()))]
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let anchors = collect_anchors(ctx);
        let mut out = Vec::new();
        for l in &ctx.links {
            if l.image || l.kind != LinkKind::Inline {
                continue;
            }
            let d = l.dest.trim();
            if !d.starts_with('#') || d.len() < 2 {
                continue;
            }
            let frag = &d[1..];
            let decoded = frag.to_lowercase();
            if anchors.contains(&decoded) {
                continue;
            }
            out.push(warn_abs("MD051", ctx, l.start, l.end, format!("Link anchor '#{}' does not exist in document headings", frag), None));
        }
        out
    }
}
