pub struct MD053;

impl Rule for MD053 {
    fn name(&self) -> &'static str {
        "MD053"
    }
    fn description(&self) -> &'static str {
        "Link and image reference definitions should be needed"
    }
    fn alias(&self) -> &'static str {
        "link-image-reference-definitions"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("ignored-definitions", Value::Array(vec![]))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let ignored: Vec<String> = cfg.str_list("ignored-definitions").unwrap_or_default().iter().map(|s| s.to_lowercase()).collect();
        let mut used: HashSet<String> = HashSet::new();
        for l in &ctx.links {
            if matches!(l.kind, crate::inline::LinkKind::Full | crate::inline::LinkKind::Collapsed | crate::inline::LinkKind::Shortcut) {
                used.insert(crate::inline::normalize_label(&l.label));
            }
        }
        let mut seen: HashSet<String> = HashSet::new();
        let mut out = Vec::new();
        for d in &ctx.ref_defs {
            if d.label.starts_with('^') || d.label == "//" {
                continue;
            }
            if ignored.contains(&d.label) {
                continue;
            }
            let line = ctx.line(d.line);
            if !seen.insert(d.label.clone()) {
                out.push(warn("MD053", ctx, d.line, 0, line.len(), format!("Duplicate link or image reference definition: [{}]", d.label_raw), None));
                continue;
            }
            if !used.contains(&d.label) {
                out.push(warn("MD053", ctx, d.line, 0, line.len(), format!("Unused link/image reference: [{}]", d.label_raw), None));
            }
        }
        out
    }
}
