use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use regex::Regex;
use std::sync::OnceLock;

pub struct MD011;

fn re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"\(([^()\n]+)\)\[([^\[\]\n]+)\]").unwrap())
}

fn looks_like_url(s: &str) -> bool {
    let t = s.trim();
    t.contains("://") || t.starts_with("www.") || t.starts_with('/') || t.starts_with('#') || t.starts_with("mailto:") || t.starts_with("./") || t.starts_with("../") || t.ends_with(".md") || t.ends_with(".html")
}

impl Rule for MD011 {
    fn name(&self) -> &'static str {
        "MD011"
    }
    fn description(&self) -> &'static str {
        "Reversed link syntax"
    }
    fn alias(&self) -> &'static str {
        "no-reversed-links"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_severity(&self) -> Severity {
        Severity::Error
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        for i in 0..ctx.num_lines() {
            let li = &ctx.lines[i];
            if li.in_code || li.in_front_matter || li.in_html_block || li.in_html_comment {
                continue;
            }
            let line = ctx.line(i);
            for c in re().captures_iter(line) {
                let m = c.get(0).unwrap();
                let abs = li.start + m.start();
                if ctx.is_in_code_span(abs) {
                    continue;
                }
                let a = &c[1];
                let b = &c[2];
                let (text, url) = if looks_like_url(b) { (a, b) } else if looks_like_url(a) { (b, a) } else { (b, a) };
                let rep = format!("[{}]({})", text, url);
                out.push(warn("MD011", ctx, i, m.start(), m.end(), format!("Reversed link syntax: use {} instead", rep), Some(Fix::new(abs, li.start + m.end(), rep))));
            }
        }
        out
    }
}
