use crate::rule::*;
use crate::rules::util::*;

pub struct MD062;

impl Rule for MD062 {
    fn name(&self) -> &'static str {
        "MD062"
    }
    fn description(&self) -> &'static str {
        "Link destination should not have leading or trailing whitespace"
    }
    fn alias(&self) -> &'static str {
        "link-destination-whitespace"
    }
    fn category(&self) -> &'static str {
        "link"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        for l in &ctx.links {
            if l.kind != LinkKind::Inline {
                continue;
            }
            // find '(' after text
            let after_text = l.text_end + 1; // ']'
            let paren = after_text; // '(' position
            if paren >= l.end || ctx.content.as_bytes()[paren] != b'(' {
                continue;
            }
            let inner = &ctx.content[paren + 1..l.end - 1];
            if inner.contains('\n') {
                continue;
            }
            let lead = inner.len() - inner.trim_start().len() > 0;
            let trail = inner.len() - inner.trim_end().len() > 0;
            if !lead && !trail {
                continue;
            }
            let what = if l.image { "Image" } else { "Link" };
            let kind = match (lead, trail) {
                (true, true) => "leading and trailing",
                (true, false) => "leading",
                _ => "trailing",
            };
            let pre = &ctx.content[l.start..paren + 1];
            let rep = format!("{}{})", pre, inner.trim());
            out.push(warn_abs("MD062", ctx, l.start, l.end, format!("{} destination has {} whitespace", what, kind), Some(Fix::new(l.start, l.end, rep))));
        }
        out
    }
}
