use crate::context::Ctx;

#[derive(Clone, Debug)]
pub struct Table {
    pub header: usize,
    pub delim: usize,
    pub end: usize,
    /// byte length of container prefix (blockquote/list indentation) per line handled by content_start
    pub in_container: bool,
}

pub fn is_delim_row(s: &str) -> bool {
    let t = s.trim();
    if t.is_empty() || !t.contains('-') {
        return false;
    }
    let inner = t.strip_prefix('|').unwrap_or(t);
    let inner = inner.strip_suffix('|').unwrap_or(inner);
    if inner.trim().is_empty() {
        return false;
    }
    let cells: Vec<&str> = inner.split('|').collect();
    if cells.len() == 1 && !t.contains('|') {
        return false;
    }
    for c in cells {
        let c = c.trim();
        let c = c.strip_prefix(':').unwrap_or(c);
        let c = c.strip_suffix(':').unwrap_or(c);
        if c.is_empty() || !c.bytes().all(|b| b == b'-') {
            return false;
        }
    }
    true
}

/// Split row into cells: pipes inside code spans DO split (GFM), escaped pipes don't
pub fn split_row_raw(row: &str) -> Vec<String> {
    let t = row.trim();
    let mut cells = Vec::new();
    let mut cur = String::new();
    let b: Vec<char> = t.chars().collect();
    let mut i = 0;
    while i < b.len() {
        if b[i] == '\\' && i + 1 < b.len() {
            cur.push(b[i]);
            cur.push(b[i + 1]);
            i += 2;
            continue;
        }
        if b[i] == '|' {
            cells.push(std::mem::take(&mut cur));
            i += 1;
            continue;
