use crate::blocks::Kind;
use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use regex::Regex;
use std::sync::OnceLock;
use toml::Value;
use unicode_width::UnicodeWidthStr;

pub struct MD013;

fn link_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"(!?\[[^\]]*\])\([^)\s]*(?:\s+[^)]*)?\)").unwrap())
}
fn url_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r#"(?:https?|ftp)://[^\s<>"'`]+|www\.[^\s<>"'`]+"#).unwrap())
}

fn measure(s: &str, mode: &str) -> usize {
    match mode {
        "chars" => s.chars().count(),
        "bytes" => s.len(),
        _ => UnicodeWidthStr::width(s),
    }
}

impl Rule for MD013 {
    fn name(&self) -> &'static str {
        "MD013"
    }
    fn description(&self) -> &'static str {
        "Line length should not be excessive"
    }
    fn alias(&self) -> &'static str {
        "line-length"
    }
    fn category(&self) -> &'static str {
        "whitespace"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![
            ("abbreviations", Value::Array(vec![])),
            ("code-blocks", Value::Boolean(true)),
            ("headings", Value::Boolean(true)),
            ("length-mode", Value::String("visual".into())),
            ("line-length", Value::Integer(80)),
            ("paragraphs", Value::Boolean(true)),
            ("reflow", Value::Boolean(false)),
            ("reflow-mode", Value::String("default".into())),
            ("strict", Value::Boolean(false)),
            ("tables", Value::Boolean(false)),
        ]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        let limit = cfg.line_length(80);
        if limit == 0 {
            return vec![];
        }
        let code_blocks = cfg.bool("code-blocks", true);
        let headings = cfg.bool("headings", true);
        let tables_on = cfg.bool("tables", false);
        let paragraphs = cfg.bool("paragraphs", true);
        let strict = cfg.bool("strict", false);
        let mode = cfg.str("length-mode", "visual");
        let tables = crate::tables::detect_tables(ctx);
        let mut out = Vec::new();
        for i in 0..ctx.num_lines() {
            let li = &ctx.lines[i];
            let line = ctx.line(i);
            let full_len = measure(line, &mode);
            if full_len <= limit {
                continue;
            }
            if li.in_front_matter {
                continue;
            }
            let in_table = tables.iter().any(|t| i >= t.header && i <= t.end);
            if li.in_code {
                if !code_blocks {
                    continue;
                }
            } else if in_table {
                if !tables_on {
                    continue;
                }
            } else if li.heading.is_some() {
                if !headings {
                    continue;
                }
            } else {
                if li.in_html_block || li.in_html_comment {
                    continue;
                }
                if !strict && li.bq_depth > 0 {
                    continue;
                }
                if !paragraphs {
                    continue;
                }
            }
            if !strict && !li.in_code {
                if li.ref_def.is_some() {
                    continue;
