use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use regex::Regex;
use std::sync::OnceLock;

pub struct MD066;

pub struct FnRef {
    pub line: usize,
    pub label: String,
    pub raw: String,
}
pub struct FnDef {
    pub line: usize,
    pub label: String,
    pub raw: String,
    pub empty: bool,
}

fn ref_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"\[\^([^\]\s]+)\]").unwrap())
}
fn def_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"^\s{0,3}\[\^([^\]\s]+)\]:(.*)$").unwrap())
}

pub fn footnotes(ctx: &Ctx) -> (Vec<FnRef>, Vec<FnDef>) {
    let mut refs = Vec::new();
    let mut defs = Vec::new();
    let n = ctx.num_lines();
    for i in 0..n {
        let li = &ctx.lines[i];
        if li.in_code || li.in_front_matter || li.in_html_comment || li.in_html_block {
            continue;
        }
        let line = ctx.line(i);
        let content = ctx.line_content(i);
        let mut def_end = 0;
        if let Some(c) = def_re().captures(content) {
            let rest = c[2].trim();
            let mut empty = rest.is_empty();
            if empty {
                // continuation on next indented line
                if i + 1 < n {
                    let nl = ctx.line(i + 1);
                    if !nl.trim().is_empty() && (nl.starts_with("    ") || nl.starts_with('\t')) {
                        empty = false;
                    }
                }
            }
            defs.push(FnDef { line: i, label: c[1].to_lowercase(), raw: c[1].to_string(), empty });
            def_end = line.len() - content.len() + c.get(1).unwrap().end() + 2;
        }
        for m in ref_re().find_iter(line) {
            if m.start() < def_end {
                continue;
            }
            let abs = li.start + m.start();
            if ctx.is_in_code_span(abs) {
                continue;
            }
            let lab = &line[m.start() + 2..m.end() - 1];
            refs.push(FnRef { line: i, label: lab.to_lowercase(), raw: lab.to_string() });
        }
    }
    (refs, defs)
}

impl Rule for MD066 {
    fn name(&self) -> &'static str {
        "MD066"
    }
    fn description(&self) -> &'static str {
        "Footnote validation"
    }
    fn alias(&self) -> &'static str {
        "footnote-validation"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_severity(&self) -> Severity {
        Severity::Error
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let (refs, defs) = footnotes(ctx);
        let mut out = Vec::new();
        let def_labels: std::collections::HashSet<String> = defs.iter().map(|d| d.label.clone()).collect();
        let ref_labels: std::collections::HashSet<String> = refs.iter().map(|r| r.label.clone()).collect();
        let mut reported = std::collections::HashSet::new();
        for r in &refs {
            if !def_labels.contains(&r.label) && reported.insert((r.line, r.label.clone())) {
                out.push(warn("MD066", ctx, r.line, 0, ctx.line(r.line).len(), format!("Footnote reference '[^{}]' has no corresponding definition", r.raw), None));
            }
        }
        let mut first: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
        for d in &defs {
            if let Some(&f) = first.get(&d.label) {
                out.push(warn(
                    "MD066",
                    ctx,
                    d.line,
                    0,
                    ctx.line(d.line).len(),
                    format!("Duplicate footnote definition '[^{}]' (first defined on line {})", d.raw, f + 1),
                    None,
                ));
                continue;
            }
            first.insert(d.label.clone(), d.line);
            if !ref_labels.contains(&d.label) {
                out.push(warn("MD066", ctx, d.line, 0, ctx.line(d.line).len(), format!("Footnote definition '[^{}]' is never referenced", d.raw), None));
            }
        }
        out
    }
}
