use crate::rules::util::*;

pub struct MD067;

impl Rule for MD067 {
    fn name(&self) -> &'static str {
        "MD067"
    }
    fn description(&self) -> &'static str {
        "Footnote definitions should appear in order of first reference"
    }
    fn alias(&self) -> &'static str {
        "footnote-definition-order"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let (refs, defs) = crate::rules::md066::footnotes(ctx);
        let mut order: Vec<(String, String)> = Vec::new();
        for r in &refs {
            if !order.iter().any(|o| o.0 == r.label) {
                order.push((r.label.clone(), r.raw.clone()));
            }
        }
        let referenced: std::collections::HashSet<String> = order.iter().map(|o| o.0.clone()).collect();
        let mut seen = std::collections::HashSet::new();
        let ds: Vec<_> = defs.iter().filter(|d| referenced.contains(&d.label) && seen.insert(d.label.clone())).collect();
        for (k, d) in ds.iter().enumerate() {
            if k < order.len() && order[k].0 != d.label {
                return vec![warn(
                    "MD067",
                    ctx,
                    d.line,
                    0,
                    ctx.line(d.line).len(),
                    format!("Footnote definition '[^{}]' is out of order; expected '[^{}]' next (based on reference order)", d.raw, order[k].1),
                    None,
                )];
            }
        }
        vec![]
    }
}
