use std::path::Path;

pub struct MD057;

pub fn is_relative_candidate(url: &str) -> bool {
    let u = url.trim();
    if u.is_empty() || u.starts_with('#') || u.starts_with('/') || u.starts_with('~') || u.starts_with('?') {
        return false;
    }
    if u.contains('%') {
        return false;
    }
    // scheme
    if let Some(p) = u.find(':') {
        let scheme = &u[..p];
        if !scheme.is_empty() && scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
            return false;
        }
    }
    true
}

pub fn strip_fragment(u: &str) -> &str {
    match u.find('#') {
        Some(p) => &u[..p],
        None => u,
    }
}

pub fn exists_rel(base: &Path, rel: &str) -> bool {
    let p = base.join(rel);
    p.exists()
}

pub fn is_md_ext(path: &str) -> bool {
    let p = path.split('?').next().unwrap_or(path);
    let lower = p.to_ascii_lowercase();
    lower.ends_with(".md") || lower.ends_with(".markdown") || lower.ends_with(".mdx")
}

/// Cross-file check: inline links to markdown files that don't exist
pub fn cross_file_warnings(ctx: &Ctx, file: &Path) -> Vec<Warning> {
    let base = file.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    let mut out = Vec::new();
    for l in &ctx.links {
        if l.image || l.kind != LinkKind::Inline {
            continue;
        }
        if nested_image(ctx, l) {
            continue;
        }
        let u = l.dest.trim();
        if !is_relative_candidate(u) {
            continue;
        }
        let path = strip_fragment(u);
        let path = path.split('?').next().unwrap_or(path);
        if path.is_empty() || !is_md_ext(path) {
            continue;
        }
        if exists_rel(&base, path) {
            continue;
        }
        let mut w = warn_abs("MD057", ctx, l.dest_start, l.dest_start, format!("Relative link '{}' does not exist", path), None);
        w.severity = Severity::Error;
        let (_, c2) = ctx.offset_to_line_col(l.dest_start);
        w.end_column = c2;
        out.push(w);
    }
    out
}

fn nested_image(ctx: &Ctx, l: &crate::inline::Link) -> bool {
    ctx.links.iter().any(|o| o.image && o.start >= l.text_start && o.end <= l.text_end)
}

impl Rule for MD057 {
    fn name(&self) -> &'static str {
        "MD057"
    }
    fn description(&self) -> &'static str {
        "Relative links should point to existing files"
    }
    fn alias(&self) -> &'static str {
        "existing-relative-links"
    }
    fn category(&self) -> &'static str {
        "link"
    }
    fn default_severity(&self) -> Severity {
        Severity::Error
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let file = match &ctx.file_path {
            Some(f) => f.clone(),
            None => return vec![],
        };
        let base = file.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        let base = if base.as_os_str().is_empty() { std::env::current_dir().unwrap_or_default() } else { base };
        let mut out = Vec::new();
        for l in &ctx.links {
            if l.kind != LinkKind::Inline {
                continue;
            }
            if !l.image && nested_image(ctx, l) {
                continue;
            }
            let u = l.dest.trim();
            if !is_relative_candidate(u) {
                continue;
            }
            let path = strip_fragment(u);
            if path.is_empty() {
                continue;
            }
            if exists_rel(&base, path) {
                continue;
            }
            let pos = if l.image { l.start } else { l.dest_start };
            out.push(warn_abs("MD057", ctx, pos, pos + path.len(), format!("Relative link '{}' does not exist", path), None));
        }
        for d in &ctx.ref_defs {
            let u = d.url.trim();
            if d.label.starts_with('^') || d.label == "//" {
                continue;
            }
            if !is_relative_candidate(u) {
                continue;
            }
            let path = strip_fragment(u);
            if path.is_empty() || exists_rel(&base, path) {
                continue;
            }
            let line = ctx.line(d.line);
            let off = line.find(u).unwrap_or(0);
            out.push(warn("MD057", ctx, d.line, off, off + path.len(), format!("Relative link '{}' does not exist", path), None));
        }
        out
    }
}
