use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use regex::Regex;
use std::sync::OnceLock;
use toml::Value;

pub struct MD014;

fn prompt_re() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| Regex::new(r"^(\s*)([$>])\s+(\S.*)$").unwrap())
}

impl Rule for MD014 {
    fn name(&self) -> &'static str {
        "MD014"
    }
    fn description(&self) -> &'static str {
        "Commands in code blocks should show output"
    }
    fn alias(&self) -> &'static str {
        "commands-show-output"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![("show-output", Value::Boolean(true))]
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        if !cfg.bool("show-output", true) {
            return vec![];
        }
        let mut out = Vec::new();
        for cb in &ctx.blocks.code_blocks {
            if !cb.fenced || cb.fence_char != '`' {
                continue;
            }
            let lang = cb.info.split_whitespace().next().unwrap_or("").to_ascii_lowercase();
            if !["bash", "sh", "shell", "console", "terminal", "shell-session"].contains(&lang.as_str()) {
                continue;
            }
            let first = cb.start_line + 1;
            let last = if cb.closed { cb.end_line } else { cb.end_line + 1 };
            if first >= last {
                continue;
            }
            let mut first_cmd: Option<(usize, usize, String)> = None;
            let mut has_output = false;
            let mut new_lines = Vec::new();
            for l in first..last {
                let t = ctx.line(l);
                if t.trim().is_empty() {
                    new_lines.push(t.to_string());
                    continue;
                }
                if let Some(c) = prompt_re().captures(t) {
                    let ind = c.get(1).unwrap().as_str();
                    if first_cmd.is_none() {
                        first_cmd = Some((l, ind.len(), c[3].to_string()));
                    }
                    new_lines.push(format!("{}{}", ind, &c[3]));
                } else if t.trim_start().starts_with('#') {
                    new_lines.push(t.to_string());
                } else {
                    has_output = true;
                    break;
                }
            }
            if has_output {
                continue;
            }
            if let Some((l, col, cmd)) = first_cmd {
                let start = ctx.lines[first].start;
                let end = if last < ctx.num_lines() { ctx.lines[last].start } else { ctx.content.len() };
                let mut rep = new_lines.join("\n");
                rep.push('\n');
                out.push(warn(
                    "MD014",
                    ctx,
                    l,
                    col,
                    ctx.line(l).len(),
                    format!("Command '{}' should show output (add example output or remove $ prompt)", cmd),
                    Some(Fix::new(start, end, rep)),
                ));
            }
        }
        out
    }
}
