    let m = m as f64;
    let jaro = (m / a.len() as f64 + m / b.len() as f64 + (m - t as f64 / 2.0) / m) / 3.0;
    let mut l = 0;
    for i in 0..a.len().min(b.len()).min(4) {
        if a[i] == b[i] {
            l += 1;
        } else {
            break;
        }
    }
    jaro + l as f64 * 0.1 * (1.0 - jaro)
}

fn fix_text(r: &dyn Rule) -> &'static str {
    match r.fix_availability() {
        FixAvail::Always => "Fix is always available.",
        FixAvail::None => "Fix is not available.",
    }
}

fn fix_avail_name(r: &dyn Rule) -> &'static str {
    match r.fix_availability() {
        FixAvail::Always => "Always",
        FixAvail::None => "None",
    }
}

fn rule_url(r: &dyn Rule) -> String {
    format!("https://rumdl.dev/{}/", r.name().to_lowercase())
}

fn read_doc(r: &dyn Rule) -> Option<String> {
    let p = PathBuf::from("docs").join(format!("{}.md", r.name().to_lowercase()));
    std::fs::read_to_string(p).ok()
}

fn rule_json(r: &dyn Rule, explain: bool) -> serde_json::Value {
    let mut m = serde_json::Map::new();
    m.insert("code".into(), r.name().into());
    m.insert("name".into(), r.alias().into());
    let aliases: Vec<serde_json::Value> = r.extra_aliases().iter().map(|s| serde_json::Value::from(*s)).collect();
    m.insert("aliases".into(), serde_json::Value::Array(aliases));
    m.insert("summary".into(), r.description().into());
    m.insert("category".into(), r.category().into());
    m.insert("fix".into(), fix_text(r).into());
    m.insert("fix_availability".into(), fix_avail_name(r).into());
    m.insert("url".into(), rule_url(r).into());
    if explain {
        if let Some(d) = read_doc(r) {
            m.insert("explanation".into(), d.into());
        }
    }
    serde_json::Value::Object(m)
}

fn find_rule_by_code<'a>(rules: &'a [Box<dyn Rule>], name: &str) -> Option<&'a dyn Rule> {
    let up = name.to_ascii_uppercase();
    rules.iter().find(|r| r.name() == up).map(|r| r.as_ref())
}

const CATEGORIES: &[&str] = &["blockquote", "code-block", "emphasis", "front-matter", "heading", "html", "link", "list", "other", "whitespace"];

fn run_rule(m: &clap::ArgMatches) -> i32 {
    let rules = crate::rules::all_rules();
    let fmt = m.get_one::<String>("output_format").cloned().unwrap_or_else(|| "text".into());
    let explain = m.get_flag("explain");
    if m.get_flag("list_categories") {
        println!("Available categories:");
        for c in CATEGORIES {
            let n = rules.iter().filter(|r| r.category() == *c).count();
            println!("  {} ({} rules)", c, n);
        }
        return 0;
    }
    if let Some(name) = m.get_one::<String>("rule") {
        let r = match find_rule_by_code(&rules, name) {
            Some(r) => r,
            None => {
                eprintln!("Rule '{}' not found.", name);
                return 2;
            }
        };
        match fmt.as_str() {
            "json" => println!("{}", serde_json::to_string_pretty(&rule_json(r, explain)).unwrap()),
            "json-lines" => println!("{}", serde_json::to_string(&rule_json(r, explain)).unwrap()),
            _ => {
                println!("{} - {}", r.name(), r.description());
                println!();
                println!("Name: {}", r.alias());
                if !r.extra_aliases().is_empty() {
                    println!("Aliases: {}", r.extra_aliases().join(", "));
                }
                println!("Category: {}", r.category());
                println!("Fix: {}", fix_text(r));
                println!("Documentation: {}", rule_url(r));
                if explain {
                    if let Some(d) = read_doc(r) {
                        println!();
                        print!("{}", d);
                    }
                }
            }
        }
        return 0;
    }
    let fixable = m.get_flag("fixable");
    let cat = m.get_one::<String>("category").cloned();
    if let Some(c) = &cat {
        if !CATEGORIES.contains(&c.as_str()) {
            eprintln!("Invalid category: '{}'", c);
            eprintln!("Valid categories: {}", CATEGORIES.join(", "));
            return 2;
        }
    }
    let sel: Vec<&dyn Rule> = rules
        .iter()
        .map(|r| r.as_ref())
        .filter(|r| !fixable || r.fix_availability() != FixAvail::None)
        .filter(|r| cat.as_ref().map(|c| r.category() == c).unwrap_or(true))
        .collect();
    match fmt.as_str() {
        "json" => {
            let arr: Vec<serde_json::Value> = sel.iter().map(|r| rule_json(*r, explain)).collect();
            println!("{}", serde_json::to_string_pretty(&serde_json::Value::Array(arr)).unwrap());
        }
        "json-lines" => {
            for r in &sel {
                println!("{}", serde_json::to_string(&rule_json(*r, explain)).unwrap());
            }
        }
        _ => {
            let mut filters = Vec::new();
            if fixable {
                filters.push("fixable".to_string());
            }
            if let Some(c) = &cat {
                filters.push(format!("category={}", c));
            }
            if filters.is_empty() {
                println!("Available rules:");
            } else {
                println!("Available rules ({}):", filters.join(", "));
            }
            for r in &sel {
                println!("  {} - {}", r.name(), r.description());
            }
            println!();
            println!("Total: {} rules", sel.len());
        }
    }
    0
}

fn category_title(c: &str) -> &'static str {
    match c {
        "blockquote" => "Blockquote",
        "code-block" => "CodeBlock",
        "emphasis" => "Emphasis",
        "front-matter" => "FrontMatter",
        "heading" => "Heading",
        "html" => "Html",
        "link" => "Link",
        "list" => "List",
        "whitespace" => "Whitespace",
        _ => "Other",
    }
}

fn explain_default_config(r: &dyn Rule) -> Option<String> {
    let mut defs = r.default_config();
    if defs.is_empty() {
        return None;
    }
    match r.name() {
        "MD035" => defs = vec![("style", toml::Value::String("---".into()))],
        "MD044" => {
            for d in defs.iter_mut() {
                if d.0 == "code-blocks" || d.0 == "html-comments" {
                    d.1 = toml::Value::Boolean(true);
                }
            }
        }
        _ => {}
    }
    let mut t = toml::map::Map::new();
    for (k, v) in defs {
        t.insert(k.to_string(), v);
    }
    let body = toml::to_string_pretty(&toml::Value::Table(t)).unwrap_or_default();
    Some(body)
}

fn run_explain(m: &clap::ArgMatches, g: &GlobalOpts) -> i32 {
    let rules = crate::rules::all_rules();
    let name = m.get_one::<String>("rule").cloned().unwrap_or_default();
    let r = match find_rule_by_code(&rules, &name) {
        Some(r) if r.name() != "MD072" && r.name() != "MD073" => r,
        _ => {
            eprintln!("Error: Rule '{}' not found.", name);
            eprintln!();
            eprintln!("Use 'rumdl rule' to see all available rules.");
            return 2;
        }
    };
    let c = crate::output::Colors { on: g.color };
    let title = format!("{} - {}", r.name(), r.description());
    match read_doc(r) {
        None => {
            println!("{}", c.c("1", &title));
            println!();
            println!("Category: {}", category_title(r.category()));
            println!();
            println!("This rule helps maintain consistent Markdown formatting.");
            println!();
            println!("For more information, see the documentation at:");
            println!("  {}", rule_url(r));
        }
        Some(doc) => {
            println!("{}", c.c("1", &title));
            println!();
            let mut in_code = false;
            for (i, line) in doc.lines().enumerate() {
                if i == 0 && line.starts_with("# ") {
                    continue;
                }
                if line.trim_start().starts_with("```") {
                    in_code = !in_code;
                    println!("{}", c.c("2", line));
                    continue;
                }
                if let Some(h) = line.strip_prefix("## ") {
                    println!();
                    println!("{}", c.c("1;4", h));
                    continue;
                }
                if let Some(h) = line.strip_prefix("### ") {
                    println!();
                    println!("{}", c.c("1", h));
                    continue;
                }
                if in_code {
                    if line.is_empty() {
                        println!();
                    } else {
                        println!("  {}", line);
                    }
                    continue;
                }
                println!("{}", line);
            }
            if let Some(cfgs) = explain_default_config(r) {
                println!();
                println!("{}", c.c("1", "Default Configuration:"));
                println!("{}", c.c("2", &format!("[{}]", r.name())));
                for l in cfgs.lines() {
                    if l.is_empty() {
                        println!();
                    } else {
                        println!("{}", c.c("2", l));
                    }
                }
            }
        }
    }
    0
}

fn run_init(m: &clap::ArgMatches) -> i32 {
    let pyproject = m.get_flag("pyproject");
    let rumdl_tpl = include_str!("assets/init_rumdl.toml");
    let py_tpl = include_str!("assets/init_pyproject.toml");
    if pyproject {
        let p = Path::new("pyproject.toml");
        if p.exists() {
            println!("pyproject.toml already exists. Would you like to append rumdl configuration? [y/N]");
            print!("> ");
            use std::io::Write;
            let _ = std::io::stdout().flush();
            let mut ans = String::new();
            let _ = std::io::stdin().read_line(&mut ans);
            if ans.trim().eq_ignore_ascii_case("y") || ans.trim().eq_ignore_ascii_case("yes") {
                let existing = std::fs::read_to_string(p).unwrap_or_default();
                let idx = py_tpl.find("[tool.rumdl]").unwrap_or(0);
                let section = &py_tpl[idx..];
                let new = format!("{}\n\n{}", existing.trim_end_matches('\n').to_string() + "\n", section);
                let _ = std::fs::write(p, new);
                println!("Added rumdl configuration to pyproject.toml");
            } else {
                println!("Aborted. No changes made to pyproject.toml");
            }
            return 0;
        }
        if let Err(e) = std::fs::write(p, py_tpl) {
            eprintln!("Error: Failed to create pyproject.toml: {}", e);
            return 2;
        }
        println!("Created pyproject.toml with rumdl configuration");
        return 0;
    }
    let p = Path::new(".rumdl.toml");
    if p.exists() {
        eprintln!("Error: Failed to create config file: Configuration file already exists at .rumdl.toml");
        return 2;
    }
    if let Err(e) = std::fs::write(p, rumdl_tpl) {
        eprintln!("Error: Failed to create config file: {}", e);
        return 2;
    }
    println!("Created default configuration file: .rumdl.toml");
    println!();
    println!("Setup complete! You can now:");
    println!("  • Run rumdl check . to lint your Markdown files");
    println!("  • Open your editor to see real-time linting");
    0
}

fn run_schema(m: &clap::ArgMatches) -> i32 {
    let schema = include_str!("assets/schema.json");
    let schema = schema.trim_end_matches('\n');
    let cwd = std::env::current_dir().unwrap_or_default();
    let path = cwd.join("rumdl.schema.json");
    match m.subcommand() {
        Some(("print", _)) => {
            println!("{}", schema);
            0
        }
        Some(("generate", _)) => {
            let existing = std::fs::read_to_string(&path).ok();
            if existing.as_deref() == Some(schema) {
                println!("Schema is already up-to-date: {}", path.display());
                return 0;
            }
            if std::fs::write(&path, schema).is_err() {
                eprintln!("Error: Failed to write schema file: {}", path.display());
                return 2;
            }
            println!("Schema updated: {}", path.display());
            0
        }
        Some(("check", _)) => match std::fs::read_to_string(&path) {
            Ok(s) => {
                if s == schema {
                    println!("Schema is up-to-date: {}", path.display());
                    0
                } else {
                    eprintln!("Error: Schema is out of date: {}", path.display());
                    eprintln!("Run 'rumdl schema generate' to update it.");
                    2
                }
            }
            Err(_) => {
                eprintln!("Error: Schema file not found: {}", path.display());
                eprintln!("Run 'rumdl schema generate' to create it.");
                2
            }
        },
        _ => 2,
    }
}

fn run_completions(m: &clap::ArgMatches) -> i32 {
    if m.get_flag("list") {
        println!("Available shells:");
        println!("  bash         Bourne Again SHell");
        println!("  zsh          Z shell");
        println!("  fish         Friendly Interactive SHell");
        println!("  powershell   PowerShell");
        println!("  elvish       Elvish shell");
        return 0;
    }
    let shell = match m.get_one::<String>("shell") {
        Some(s) => s.clone(),
        None => {
            let sh = std::env::var("SHELL").unwrap_or_default();
            let name = sh.rsplit('/').next().unwrap_or("").to_string();
            if ["bash", "zsh", "fish", "elvish", "powershell", "pwsh"].contains(&name.as_str()) {
                if name == "pwsh" {
                    "powershell".to_string()
                } else {
                    name
                }
            } else {
                eprintln!("Error: Could not detect shell from $SHELL environment variable");
                eprintln!();
                eprintln!("Please specify a shell explicitly:");
                eprintln!("  rumdl completions bash");
                eprintln!("  rumdl completions zsh");
                eprintln!("  rumdl completions fish");
                eprintln!("  rumdl completions powershell");
                eprintln!("  rumdl completions elvish");
                eprintln!();
                eprintln!("Or use --list to see all available shells");
                return 2;
            }
        }
    };
    use clap_complete::{generate, Shell};
    let sh = match shell.as_str() {
        "bash" => Shell::Bash,
        "zsh" => Shell::Zsh,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        "elvish" => Shell::Elvish,
        _ => return 2,
    };
    let mut cmd = crate::cli::build_cli();
    generate(sh, &mut cmd, "rumdl", &mut std::io::stdout());
    0
}

fn run_clean(m: &clap::ArgMatches, g: &GlobalOpts) -> i32 {
    let _ = m;
    let cfg = load_config(g).unwrap_or_default();
    let dir = std::env::var("RUMDL_CACHE_DIR").ok().or(cfg.global.cache_dir.clone()).unwrap_or_else(|| ".rumdl_cache".into());
    let cwd = std::env::current_dir().unwrap_or_default();
    let p = cwd.join(&dir);
    if !p.exists() {
        println!("No cache found at {} (nothing to clean)", p.display());
        return 0;
    }
    // count files and bytes
    let mut files = 0u64;
    let mut bytes = 0u64;
    for e in walkdir(&p) {
        if let Ok(md) = std::fs::metadata(&e) {
            if md.is_file() {
                let name = e.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
                if name == ".gitignore" || name == "CACHEDIR.TAG" {
                    continue;
                }
                files += 1;
                bytes += md.len();
            }
        }
    }
    if files == 0 {
        println!("Cache is empty at {} (nothing to clean)", p.display());
        return 0;
    }
    let _ = std::fs::remove_dir_all(&p);
    println!("Cleared cache: {}", p.display());
    println!("  Removed {} across {} files", human_bytes(bytes), files);
    0
}

fn human_bytes(b: u64) -> String {
    if b < 1024 {
        format!("{} B", b)
    } else if b < 1024 * 1024 {
        format!("{:.1} KB", b as f64 / 1024.0)
    } else {
        format!("{:.1} MB", b as f64 / (1024.0 * 1024.0))
    }
}

fn walkdir(p: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(p) {
        for e in rd.flatten() {
            let pp = e.path();
            if pp.is_dir() {
                out.extend(walkdir(&pp));
            } else {
                out.push(pp);
            }
        }
    }
    out
}

fn run_import(m: &clap::ArgMatches) -> i32 {
    let file = m.get_one::<String>("file").cloned().unwrap_or_default();
    let p = Path::new(&file);
    if !p.exists() {
        eprintln!("Error: Failed to import config: File not found: {}", file);
        return 2;
    }
    let content = std::fs::read_to_string(p).unwrap_or_default();
    let lower = file.to_ascii_lowercase();
    let v: Option<serde_json::Value> = if lower.ends_with(".yaml") || lower.ends_with(".yml") {
        serde_yaml::from_str(&content).ok()
    } else {
        serde_json::from_str(&config::strip_json_comments(&content)).ok().or_else(|| serde_yaml::from_str(&content).ok())
    };
    let v = match v {
        Some(v) => v,
        None => {
            eprintln!("Error: Failed to parse config file: {}", file);
            return 2;
        }
    };
    // convert
    let mut disable: Vec<String> = Vec::new();
    let mut rules: std::collections::BTreeMap<String, toml::map::Map<String, toml::Value>> = std::collections::BTreeMap::new();
    if let serde_json::Value::Object(o) = &v {
        for (k, val) in o {
            if let Some(rule) = crate::rules::resolve_rule_name(k) {
                match val {
                    serde_json::Value::Bool(false) => disable.push(rule.to_string()),
                    serde_json::Value::Object(ro) => {
                        let e = rules.entry(rule.to_string()).or_default();
                        for (rk, rv) in ro {
                            if let Some(tv) = config::json_to_toml(rv) {
                                e.insert(config::norm_key(rk), tv);
                            }
                        }
                        if rule == "MD007" && e.contains_key("indent") && !e.contains_key("style") {
                            e.insert("style".into(), toml::Value::String("fixed".into()));
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    let format = m.get_one::<String>("format").cloned().unwrap_or_else(|| "toml".into());
    let out_text = if format == "json" {
        let mut root = serde_json::Map::new();
        if !disable.is_empty() {
            root.insert("global".into(), serde_json::json!({ "disable": disable }));
        }
        for (r, t) in &rules {
            let js = serde_json::to_value(toml::Value::Table(t.clone())).unwrap_or(serde_json::Value::Null);
            root.insert(r.clone(), js);
        }
        serde_json::to_string_pretty(&serde_json::Value::Object(root)).unwrap()
    } else {
        let mut s = String::new();
        if !disable.is_empty() {
            s.push_str("[global]\n");
            s.push_str(&format!("disable = [{}]\n\n", disable.iter().map(|d| format!("\"{}\"", d)).collect::<Vec<_>>().join(", ")));
        }
        for (r, t) in &rules {
            s.push_str(&format!("[{}]\n", r));
            for (k, v) in t {
                s.push_str(&format!("{} = {}\n", k, crate::config_display::fmt_value(v)));
            }
            s.push('\n');
        }
        s
    };
    if m.get_flag("dry_run") {
        println!("{}", out_text);
        return 0;
    }
    let output = m.get_one::<String>("output").cloned().unwrap_or_else(|| if format == "json" { "rumdl.json".into() } else { ".rumdl.toml".into() });
    if Path::new(&output).exists() {
        eprintln!("Error: Output file '{}' already exists", output);
        return 2;
    }
    if std::fs::write(&output, &out_text).is_err() {
        eprintln!("Error: Failed to write {}", output);
        return 2;
    }
    println!("Converted markdownlint config from '{}' to '{}'", file, output);
    println!("You can now use: rumdl check --config {} .", output);
    0
}

pub fn run(cmd: &str, m: &clap::ArgMatches, g: &GlobalOpts) -> i32 {
    match cmd {
        "rule" => run_rule(m),
        "explain" => run_explain(m, g),
        "init" => run_init(m),
        "schema" => run_schema(m),
        "completions" => run_completions(m),
        "clean" => run_clean(m, g),
        "import" => run_import(m),
        "config" => crate::config_display::run_config(m, g),
        "vscode" => {
            eprintln!("Error: VS Code (or compatible editor) not found. Please ensure one of the following commands is available: code, cursor, windsurf, codium, vscodium");
            2
        }
        "server" => {
            // Minimal: read stdin until EOF
            let mut s = String::new();
            use std::io::Read;
            let _ = std::io::stdin().read_to_string(&mut s);
            0
        }
        _ => 2,
    }
}

