struct Line {
    text: String,
    ann: Option<String>,
}

fn flavor_display(f: &Option<String>) -> String {
    match f {
        None => "Standard".into(),
        Some(s) => crate::context::Flavor::parse(s).map(|f| f.debug_name().to_string()).unwrap_or_else(|| "Standard".into()),
    }
