fn build_lines(cfg: &Config, show_defaults: bool, show_user: bool) -> Vec<Line> {
    let mut out: Vec<Line> = Vec::new();
    let src = "[from project config]".to_string();
    let def = "[from default]".to_string();
    let g = &cfg.global;
    let set = |k: &str| g.set_keys.iter().any(|x| x == k);
    let mut glines: Vec<Line> = Vec::new();
    let mut push = |text: String, is_set: bool| {
        if is_set && show_user {
            glines.push(Line { text, ann: Some(src.clone()) });
        } else if !is_set && show_defaults {
            glines.push(Line { text, ann: Some(def.clone()) });
        }
    };
    push(format!("enable = {}", str_list(g.enable.as_deref().unwrap_or(&[]))), set("enable"));
    push(format!("disable = {}", str_list(&g.disable)), set("disable"));
    push(format!("exclude = {}", str_list(&g.exclude)), set("exclude"));
    push(format!("include = {}", str_list(&g.include)), set("include"));
    push(format!("respect_gitignore = {}", g.respect_gitignore.unwrap_or(true)), set("respect-gitignore"));
    push(format!("flavor = {}", flavor_display(&g.flavor)), set("flavor"));
    if show_user && !show_defaults {
        if let Some(l) = g.line_length {
            glines.push(Line { text: format!("line_length = {}", l), ann: Some(src.clone()) });
        }
        if let Some(v) = g.force_exclude {
            glines.push(Line { text: format!("force_exclude = {}", v), ann: Some(src.clone()) });
        }
        if let Some(v) = g.cache {
            glines.push(Line { text: format!("cache = {}", v), ann: Some(src.clone()) });
        }
