pub fn run_config(m: &clap::ArgMatches, g: &GlobalOpts) -> i32 {
    let cfg = match load_config(g) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error: {}", e);
            return 2;
        }
    };
    for w in &cfg.warnings {
        crate::warn_yellow("[config warning]", w);
    }
    match m.subcommand() {
        Some(("file", _)) => {
            match &cfg.source {
                Some(p) => println!("{}", p.display()),
                None => println!("No configuration file found (using defaults)"),
            }
            return 0;
        }
        Some(("get", sm)) => {
            let key = sm.get_one::<String>("key").cloned().unwrap_or_default();
            let (sect, k) = match key.split_once('.') {
                Some(x) => x,
                None => {
                    eprintln!("Key must be in the form global.key or MDxxx.key");
                    return 2;
                }
            };
            if sect.eq_ignore_ascii_case("global") {
                let nk = norm_key(k);
                let lines = build_lines(&cfg, true, true);
                // find within global section
                let mut in_g = false;
                for l in &lines {
                    if l.text == "[global]" {
                        in_g = true;
                        continue;
                    }
                    if l.text.starts_with('[') {
                        in_g = false;
                    }
                    if in_g {
                        if let Some((lk, lv)) = l.text.split_once(" = ") {
                            if norm_key(lk) == nk {
                                println!("global.{} = {} {}", lk, lv, l.ann.clone().unwrap_or_default());
                                return 0;
                            }
                        }
                    }
                }
                eprintln!("Unknown global key: {}", k);
                return 2;
            }
            let rule = match crate::rules::resolve_rule_name(sect) {
                Some(r) => r,
                None => {
                    eprintln!("Unknown config key: {}", key);
                    return 2;
                }
            };
            let nk = norm_key(k);
            if let Some(t) = cfg.rules.get(rule) {
                if let Some(v) = t.get(&nk) {
                    if nk != "severity" {
                        println!("{}.{} = {} [from project config]", rule, nk, fmt_value(v));
                        return 0;
                    }
                }
            }
            let rules = crate::rules::all_rules();
            if let Some(r) = rules.iter().find(|r| r.name() == rule) {
                for (dk, dv) in r.default_config() {
                    if dk == nk {
                        println!("{}.{} = {} [from default]", rule, nk, fmt_value(&dv));
                        return 0;
                    }
                }
            }
            eprintln!("Unknown config key: {}", key);
            return 2;
        }
        _ => {}
    }
    let output = m.get_one::<String>("output").cloned().unwrap_or_else(|| "toml".into());
    if output == "json" {
        println!("{}", serde_json::to_string_pretty(&json_config(&cfg)).unwrap());
        return 0;
    }
    let defaults_only = m.get_flag("defaults");
    let no_defaults = m.get_flag("no_defaults");
    let lines = if defaults_only {
        build_lines(&Config::default(), true, false)
    } else if no_defaults {
        build_lines(&cfg, false, true)
    } else {
        build_lines(&cfg, true, true)
    };
    if no_defaults && lines.is_empty() {
        println!("All configurations are using default values.");
        return 0;
    }
    print_lines(&lines);
    0
}
