use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use toml::Value;

pub struct MD044;

fn find_matches(ctx: &Ctx, cfg: &RuleConfig) -> Vec<(usize, usize, String, String)> {
    let names = cfg.str_list("names").unwrap_or_default();
    if names.is_empty() {
        return vec![];
    }
    let code_blocks = cfg.bool("code-blocks", false);
    let html_comments = cfg.bool("html-comments", false);
    let html_elements = cfg.bool("html-elements", true);
    let mut excl: Vec<(usize, usize)> = Vec::new();
    if !code_blocks {
        for c in &ctx.code_spans {
            excl.push((c.start, c.end));
        }
    }
    for l in &ctx.links {
        if l.kind == crate::inline::LinkKind::Inline {
            excl.push((l.dest_start, l.dest_end));
        } else if l.kind == crate::inline::LinkKind::Autolink {
            excl.push((l.start, l.end));
        }
    }
    if !html_comments {
        for &(a, b) in &ctx.html_comment_ranges {
            excl.push((a, b));
        }
    }
    if !html_elements {
        for h in &ctx.html_tags {
            excl.push((h.start, h.end));
        }
    }
    let mut out = Vec::new();
    for i in 0..ctx.num_lines() {
        let li = &ctx.lines[i];
        if li.in_code && !code_blocks {
            continue;
        }
        if li.ref_def.is_some() {
            continue;
        }
        if li.in_html_comment && !html_comments {
            continue;
        }
        let line = ctx.line(i);
        let lower = line.to_lowercase();
        if lower.len() != line.len() {
            // fallback: skip complex unicode lines
        }
        for name in &names {
            let nl = name.to_lowercase();
            if nl.is_empty() {
                continue;
            }
            let mut from = 0;
            while let Some(p) = lower[from..].find(&nl) {
                let s = from + p;
