use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;

pub struct MD070;

impl Rule for MD070 {
    fn name(&self) -> &'static str {
        "MD070"
    }
    fn description(&self) -> &'static str {
        "Nested code fence collision - use longer fence to avoid premature closure"
    }
    fn alias(&self) -> &'static str {
        "nested-code-fence"
    }
    fn category(&self) -> &'static str {
        "code-block"
    }
    fn check(&self, ctx: &Ctx, _cfg: &RuleConfig) -> Vec<Warning> {
        let mut out = Vec::new();
        for cb in &ctx.blocks.code_blocks {
            if !cb.fenced || !cb.closed {
                continue;
            }
            let lang = cb.info.split_whitespace().next().unwrap_or("").to_ascii_lowercase();
            if !(lang.is_empty() || lang == "markdown" || lang == "md") {
                continue;
            }
            let mut nested: Option<usize> = None;
            let mut maxlen = 0;
            for l in cb.start_line + 1..cb.end_line {
                let t = ctx.line(l).trim_start();
                let n = t.chars().take_while(|&c| c == cb.fence_char).count();
                if n >= 3 {
                    maxlen = maxlen.max(n);
                    let info = t[n..].trim();
                    if !info.is_empty() && n >= cb.fence_len && nested.is_none() {
                        nested = Some(l);
                    }
                }
            }
            // closing fence length also counts
            let close_t = ctx.line(cb.end_line).trim_start();
            let cn = close_t.chars().take_while(|&c| c == cb.fence_char).count();
            if let Some(nl) = nested {
                maxlen = maxlen.max(cn);
                let outer: String = std::iter::repeat(cb.fence_char).take(cb.fence_len).collect();
                let sugg: String = std::iter::repeat(cb.fence_char).take(maxlen + 1).collect();
                let line = ctx.line(cb.start_line);
                out.push(warn(
                    "MD070",
                    ctx,
                    cb.start_line,
                    0,
                    line.len(),
                    format!("Nested {} at line {} closes block prematurely — use {} for outer fence", outer, nl + 1, sugg),
                    None,
                ));
            }
        }
        out
    }
}
EOF
