use crate::config::RuleConfig;
use crate::context::Ctx;
use crate::rule::*;
use crate::rules::util::*;
use crate::tables;
use toml::Value;
use unicode_width::UnicodeWidthStr;

pub struct MD060;

#[derive(Clone, Copy, PartialEq)]
enum Align {
    None,
    Left,
    Center,
    Right,
}

fn dw(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

fn parse_align(c: &str) -> Align {
    let t = c.trim();
    let l = t.starts_with(':');
    let r = t.ends_with(':') && t.len() > 1;
    match (l, r) {
        (true, true) => Align::Center,
        (true, false) => Align::Left,
        (false, true) => Align::Right,
        _ => Align::None,
    }
}

fn min_w(a: Align) -> usize {
    match a {
        Align::None => 3,
        Align::Left | Align::Right => 4,
        Align::Center => 5,
    }
}

fn pad(cell: &str, w: usize, a: Align) -> String {
    let l = dw(cell);
    if l >= w {
        return cell.to_string();
    }
    let p = w - l;
    match a {
        Align::Right => format!("{}{}", " ".repeat(p), cell),
        Align::Center => {
            let left = p / 2;
            format!("{}{}{}", " ".repeat(left), cell, " ".repeat(p - left))
        }
        _ => format!("{}{}", cell, " ".repeat(p)),
    }
}

fn delim_cell(w: usize, a: Align, nospace: bool) -> String {
    let w = if nospace { w + 2 } else { w };
    match a {
        Align::None => "-".repeat(w),
        Align::Left => format!(":{}", "-".repeat(w - 1)),
        Align::Right => format!("{}:", "-".repeat(w - 1)),
        Align::Center => format!(":{}:", "-".repeat(w - 2)),
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Style {
    Aligned,
    AlignedNoSpace,
    Compact,
    Tight,
}

fn format_table(rows: &[String], delim_idx: usize, style: Style, col_align: &str, header_align: &str, body_align: &str, loose_last: bool) -> Vec<String> {
    let cells: Vec<Vec<String>> = rows.iter().map(|r| tables::split_row_raw(r).iter().map(|c| c.trim().to_string()).collect()).collect();
    let ncol = cells.iter().map(|c| c.len()).max().unwrap_or(0);
    let aligns: Vec<Align> = (0..ncol).map(|j| cells[delim_idx].get(j).map(|c| parse_align(c)).unwrap_or(Align::None)).collect();
    let force = |s: &str| match s {
        "left" => Some(Align::Left),
        "center" => Some(Align::Center),
        "right" => Some(Align::Right),
        _ => None,
    };
    let mut out = Vec::new();
    match style {
        Style::Compact | Style::Tight => {
            for (i, row) in cells.iter().enumerate() {
                let sep = if style == Style::Compact { " " } else { "" };
                let inner: Vec<String> = row.iter().map(|c| format!("{}{}{}", sep, c, sep)).collect();
                let _ = i;
                out.push(format!("|{}|", inner.join("|")));
            }
        }
        Style::Aligned | Style::AlignedNoSpace => {
            let mut widths = vec![0usize; ncol];
            for (i, row) in cells.iter().enumerate() {
                if i == delim_idx {
                    continue;
                }
                for (j, c) in row.iter().enumerate() {
                    widths[j] = widths[j].max(dw(c));
                }
            }
            for j in 0..ncol {
                widths[j] = widths[j].max(min_w(aligns[j]));
            }
            for (i, row) in cells.iter().enumerate() {
                if i == delim_idx {
                    let parts: Vec<String> = (0..row.len())
                        .map(|j| {
                            let d = delim_cell(widths[j], aligns[j], style == Style::AlignedNoSpace);
                            if style == Style::AlignedNoSpace {
                                d
                            } else {
                                format!(" {} ", d)
                            }
                        })
                        .collect();
                    out.push(format!("|{}|", parts.join("|")));
                    continue;
                }
                let is_header = i == 0;
                let parts: Vec<String> = row
                    .iter()
                    .enumerate()
                    .map(|(j, c)| {
                        let ov = if is_header { force(header_align).or(force(col_align)) } else { force(body_align).or(force(col_align)) };
