fn detect_style(header: &str) -> Style {
    let cells_raw: Vec<String> = tables::split_row_raw(header);
    if cells_raw.iter().all(|c| !c.starts_with(' ') && !c.ends_with(' ')) {
        return Style::Tight;
    }
