        return Style::Compact;
    }
    Style::Aligned
}

fn pipe_positions(row: &str) -> Vec<usize> {
    let mut v = Vec::new();
    let mut col = 0;
    let mut prev_bs = false;
    for c in row.chars() {
        if c == '|' && !prev_bs {
            v.push(col);
        }
        prev_bs = c == '\\' && !prev_bs;
        col += UnicodeWidthStr::width(c.to_string().as_str());
    }
    v
}

impl Rule for MD060 {
    fn name(&self) -> &'static str {
        "MD060"
    }
    fn description(&self) -> &'static str {
        "Table columns should be consistently aligned"
    }
    fn alias(&self) -> &'static str {
        "table-cell-alignment"
    }
    fn category(&self) -> &'static str {
        "other"
    }
    fn default_config(&self) -> Vec<(&'static str, Value)> {
        vec![
            ("column-align", Value::String("auto".into())),
            ("column-align-body", Value::String("auto".into())),
            ("column-align-header", Value::String("auto".into())),
            ("enabled", Value::Boolean(false)),
            ("loose-last-column", Value::Boolean(false)),
            ("max-width", Value::Integer(0)),
            ("style", Value::String("any".into())),
        ]
    }
    fn opt_in(&self) -> bool {
        true
    }
    fn check(&self, ctx: &Ctx, cfg: &RuleConfig) -> Vec<Warning> {
        if !cfg.bool("enabled", false) {
            return vec![];
        }
        let style = cfg.str("style", "any");
        let col_align = cfg.str("column-align", "auto");
        let header_align = cfg.str("column-align-header", "auto");
        let body_align = cfg.str("column-align-body", "auto");
        let loose = cfg.bool("loose-last-column", false);
        let max_width = cfg.usize("max-width", 0);
        let mut out = Vec::new();
        for t in tables::detect_tables(ctx) {
            if t.in_container {
                continue;
            }
            let rows: Vec<String> = (t.header..=t.end).map(|l| ctx.line(l).to_string()).collect();
            if rows.iter().any(|r| r.contains('\u{200d}') || r.contains('\u{200b}') || r.contains('\u{200c}') || r.contains('\u{2060}')) {
                continue;
            }
            let delim_idx = t.delim - t.header;
            let explicit = match style.as_str() {
                "aligned" => Some(Style::Aligned),
                "aligned-no-space" => Some(Style::AlignedNoSpace),
                "compact" => Some(Style::Compact),
                "tight" => Some(Style::Tight),
                _ => None,
            };
            let st = explicit.unwrap_or_else(|| detect_style(&rows[0]));
            if let Some(es) = explicit {
                if es == Style::Aligned || es == Style::AlignedNoSpace {
                    let p0 = pipe_positions(&rows[0]);
                    let aligned = rows.iter().all(|r| pipe_positions(r) == p0);
                    let nospace_ok = es == Style::Aligned || !rows[delim_idx].contains(' ');
                    if aligned && nospace_ok {
                        continue;
                    }
                }
            }
            let mut formatted = format_table(&rows, delim_idx, st, &col_align, &header_align, &body_align, loose);
            if (st == Style::Aligned || st == Style::AlignedNoSpace) && max_width > 0 {
                if formatted.iter().any(|l| dw(l) > max_width) {
                    formatted = format_table(&rows, delim_idx, Style::Compact, &col_align, &header_align, &body_align, loose);
                }
            }
            let start = ctx.lines[t.header].start;
            let end = ctx.lines[t.end].end;
            let end_disp = if end < ctx.content.len() { end + 1 } else { end };
            let mut rep = formatted.join("\n");
            if t.end + 1 < ctx.num_lines() {
                rep.push('\n');
            }
            for (k, l) in (t.header..=t.end).enumerate() {
                if rows[k] != formatted[k] {
