                }
            }
        }
        out
    }
    fn fix(&self, ctx: &Ctx, _cfg: &RuleConfig, warnings: &[Warning]) -> Option<String> {
        let ws: Vec<Warning> = warnings
            .iter()
            .cloned()
            .map(|mut w| {
                if let Some(f) = w.fix.as_mut() {
                    if f.end > f.start && ctx.content.as_bytes().get(f.end - 1) == Some(&b'\n') && !f.replacement.ends_with('\n') {
                        f.end -= 1;
                    }
                }
                w
            })
            .collect();
        apply_fixes(&ctx.content, &ws)
    }
}
