];

fn has_internal_caps(w: &str) -> bool {
    w.chars().skip(1).any(|c| c.is_uppercase())
}

fn cap_first(w: &str) -> String {
    // skip leading [ ( " '
    let mut out = String::new();
    let mut done = false;
    for c in w.chars() {
        if !done {
            if c.is_alphabetic() {
                out.extend(c.to_uppercase());
                done = true;
                continue;
            }
            if "[(\"'".contains(c) {
                out.push(c);
                continue;
            }
            done = true;
        }
        out.push(c);
    }
    out
}

fn lower_word(w: &str) -> String {
    w.to_lowercase()
}

/// Split text into segments: (is_code_or_url, text)
fn segments(text: &str) -> Vec<(bool, String)> {
    let mut out: Vec<(bool, String)> = Vec::new();
    let b: Vec<char> = text.chars().collect();
    let mut i = 0;
    let mut cur = String::new();
    while i < b.len() {
        if b[i] == '`' {
            let mut n = 0;
            while i + n < b.len() && b[i + n] == '`' {
                n += 1;
            }
            // find closing
            let mut j = i + n;
            let mut found = None;
            while j < b.len() {
                if b[j] == '`' {
                    let mut m = 0;
                    while j + m < b.len() && b[j + m] == '`' {
                        m += 1;
                    }
                    if m == n {
                        found = Some(j + m);
                        break;
                    }
                    j += m;
                } else {
                    j += 1;
                }
            }
            if let Some(e) = found {
                if !cur.is_empty() {
                    out.push((false, std::mem::take(&mut cur)));
                }
                out.push((true, b[i..e].iter().collect()));
                i = e;
                continue;
            }
        }
        if b[i] == ']' && i + 1 < b.len() && b[i + 1] == '(' {
            if let Some(p) = b[i + 1..].iter().position(|&c| c == ')') {
                cur.push(']');
                out.push((false, std::mem::take(&mut cur)));
                out.push((true, b[i + 1..i + 1 + p + 1].iter().collect()));
                i = i + 1 + p + 1;
                continue;
            }
        }
        cur.push(b[i]);
        i += 1;
    }
    if !cur.is_empty() {
        out.push((false, cur));
    }
    out
}

