                    } else {
                        // hyphenated parts
                        w.split('-').map(cap_first).collect::<Vec<_>>().join("-")
                    }
                }
            }
        };
        new_segs[si].replace_range(a..b, &new);
    }
    new_segs.concat()
}

impl Rule for MD063 {
