        let preserve = cfg.bool("preserve-cased-words", true);
        let minl = cfg.usize("min-level", 1);
        let maxl = cfg.usize("max-level", 6);
        let style_name = match style.as_str() {
            "sentence_case" => "sentence case",
            "all_caps" => "ALL CAPS",
            _ => "title case",
        };
        let mut out = Vec::new();
        for h in &ctx.headings {
