        for l in fm.start_line + 1..fm.end_line {
            let t = ctx.line(l);
            if t.trim_start().starts_with('#') {
                has_comment = true;
            }
            let is_key = !t.starts_with(' ') && !t.starts_with('\t') && !t.trim().is_empty() && !t.starts_with('#') && !t.starts_with('-');
            let key = if is_key {
                match fm.kind {
                    FmKind::Yaml => t.find(':').map(|p| t[..p].trim().trim_matches(|c| c == '"' || c == '\'').to_string()),
                    FmKind::Toml => {
                        if t.starts_with('[') {
                            return vec![];
                        }
                        t.find('=').map(|p| t[..p].trim().trim_matches(|c| c == '"' || c == '\'').to_string())
                    }
                    FmKind::Json => None,
                }
            } else {
                None
            };
