                Some(k) => blocks.push((k, l, l + 1)),
                None => {
                    if let Some(b) = blocks.last_mut() {
                        b.2 = l + 1;
                    } else {
                        prefix_end = l + 1;
                    }
                }
            }
        }
        let _ = prefix_end;
        if blocks.len() < 2 {
            return vec![];
        }
        let keys: Vec<String> = blocks.iter().map(|b| b.0.clone()).collect();
        let mut sorted = keys.clone();
        sorted.sort_by_key(|a| a.to_lowercase());
        if sorted == keys {
            return vec![];
        }
        let pos = (0..keys.len()).find(|&i| keys[i] != sorted[i]).unwrap();
        let line = fm.start_line + 1;
        let msg = format!(
            "{} frontmatter keys are not sorted alphabetically: '{}' should come before '{}'{}",
            kind_name,
            sorted[pos],
            keys[pos],
            if has_comment { " (auto-fix unavailable: contains comments)" } else { "" }
        );
        let fix = if has_comment {
            None
        } else {
            let mut sorted_blocks = blocks.clone();
            sorted_blocks.sort_by_key(|b| b.0.to_lowercase());
            let mut lines: Vec<String> = Vec::new();
            for l in 0..=fm.start_line {
                lines.push(ctx.line(l).to_string());
            }
            let first_key = blocks[0].1;
            for l in fm.start_line + 1..first_key {
                lines.push(ctx.line(l).to_string());
            }
            for b in &sorted_blocks {
                for l in b.1..b.2 {
                    lines.push(ctx.line(l).to_string());
                }
            }
            for l in fm.end_line..ctx.num_lines() {
                lines.push(ctx.line(l).to_string());
            }
            let rep = lines.join("\n");
            let end = if ctx.content.ends_with('\n') { ctx.content.len() - 1 } else { ctx.content.len() };
            Some(Fix::new(0, end, rep))
        };
        vec![warn("MD072", ctx, line, 0, ctx.line(line).len(), msg, fix)]
    }
}
