// Text reflow helpers for MD013
use unicode_width::UnicodeWidthStr;

pub fn width(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

/// Tokenize text into atomic units separated by whitespace, keeping markdown constructs intact.
pub fn tokenize(text: &str) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let n = chars.len();
    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut i = 0;
    let find_close = |chars: &Vec<char>, start: usize, pat: &str| -> Option<usize> {
        let p: Vec<char> = pat.chars().collect();
        let mut j = start;
        while j + p.len() <= chars.len() {
            if chars[j..j + p.len()] == p[..] {
                return Some(j);
            }
            j += 1;
        }
        None
    };
    while i < n {
        let c = chars[i];
        if c.is_whitespace() {
            if !cur.is_empty() {
                tokens.push(std::mem::take(&mut cur));
            }
            i += 1;
            continue;
        }
        // code span
        if c == '`' {
            let mut k = 0;
            while i + k < n && chars[i + k] == '`' {
                k += 1;
            }
            let pat: String = "`".repeat(k);
            if let Some(e) = find_close(&chars, i + k, &pat) {
                let end = e + k;
                cur.extend(&chars[i..end]);
                i = end;
                continue;
            }
        }
        // link / image
        if c == '[' || (c == '!' && i + 1 < n && chars[i + 1] == '[') {
            let s = if c == '!' { i + 1 } else { i };
            // find matching ]
            let mut depth = 0;
            let mut j = s;
            let mut close = None;
            while j < n {
                if chars[j] == '[' {
                    depth += 1;
                } else if chars[j] == ']' {
                    depth -= 1;
                    if depth == 0 {
                        close = Some(j);
                        break;
                    }
                }
                j += 1;
            }
            if let Some(cl) = close {
                if cl + 1 < n && chars[cl + 1] == '(' {
                    if let Some(pe) = chars[cl + 1..].iter().position(|&x| x == ')') {
                        let end = cl + 1 + pe + 1;
                        cur.extend(&chars[i..end]);
                        i = end;
                        continue;
                    }
                } else if cl + 1 < n && chars[cl + 1] == '[' {
                    if let Some(pe) = chars[cl + 1..].iter().position(|&x| x == ']') {
                        let end = cl + 1 + pe + 1;
                        cur.extend(&chars[i..end]);
                        i = end;
                        continue;
                    }
                } else if chars[s..cl].contains(&' ') {
                    let end = cl + 1;
                    cur.extend(&chars[i..end]);
                    i = end;
                    continue;
                }
            }
        }
        // emphasis spans
        if c == '*' || c == '_' {
            let mut k = 0;
            while i + k < n && chars[i + k] == c && k < 3 {
                k += 1;
            }
            let prev_ok = i == 0 || chars[i - 1].is_whitespace() || cur.is_empty();
            if prev_ok && i + k < n && !chars[i + k].is_whitespace() {
                let pat: String = std::iter::repeat(c).take(k).collect();
                let mut j = i + k;
                let mut found = None;
                while let Some(e) = find_close(&chars, j, &pat) {
                    if e > i + k && !chars[e - 1].is_whitespace() {
                        found = Some(e);
                        break;
                    }
                    j = e + 1;
                }
                if let Some(e) = found {
                    let end = e + k;
                    cur.extend(&chars[i..end]);
                    i = end;
                    continue;
                }
            }
        }
        // html tag
        if c == '<' {
            if let Some(pe) = chars[i..].iter().position(|&x| x == '>') {
                let tag: String = chars[i..i + pe + 1].iter().collect();
                if tag.contains(' ') && (tag.starts_with("<a") || tag.chars().nth(1).map(|x| x.is_ascii_alphabetic()).unwrap_or(false)) {
                    cur.push_str(&tag);
                    i += pe + 1;
                    continue;
                }
            }
        }
        cur.push(c);
        i += 1;
    }
    if !cur.is_empty() {
        tokens.push(cur);
    }
    tokens
}

/// Greedy wrap tokens into lines with given first-line prefix width and subsequent prefix width
pub fn wrap(tokens: &[String], limit: usize, first_prefix: usize, rest_prefix: usize) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0;
    for t in tokens {
        let tw = width(t);
        let prefix = if lines.is_empty() { first_prefix } else { rest_prefix };
        if cur.is_empty() {
            cur.push_str(t);
            cur_w = tw;
        } else if prefix + cur_w + 1 + tw > limit {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(t);
            cur_w = tw;
        } else {
            cur.push(' ');
            cur.push_str(t);
            cur_w += 1 + tw;
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    lines
}

/// Reflow a sequence of text lines (already stripped of container prefix) into wrapped lines.
/// Hard breaks (two trailing spaces) are preserved.
pub fn reflow_lines(lines: &[String], limit: usize, first_prefix: usize, rest_prefix: usize) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut seg: Vec<String> = Vec::new();
    let mut flush = |seg: &mut Vec<String>, out: &mut Vec<String>, hard: bool| {
        if seg.is_empty() {
            return;
        }
        let joined = seg.iter().map(|s| s.trim()).collect::<Vec<_>>().join(" ");
        let toks = tokenize(&joined);
        let fp = if out.is_empty() { first_prefix } else { rest_prefix };
        let mut w = wrap(&toks, limit, fp, rest_prefix);
        if hard {
            if let Some(last) = w.last_mut() {
                last.push_str("  ");
            }
        }
        out.extend(w);
        seg.clear();
    };
    for l in lines {
        let hard = l.ends_with("  ") && !l.trim().is_empty();
        seg.push(l.clone());
        if hard {
            flush(&mut seg, &mut out, true);
        }
    }
    flush(&mut seg, &mut out, false);
    out
}
