// rumdl-style positional diff
pub fn unified_diff(old: &str, new: &str, old_name: &str, new_name: &str) -> String {
    let a: Vec<&str> = split_lines(old);
    let b: Vec<&str> = split_lines(new);
    let n = a.len().max(b.len());
    let changed = |i: usize| a.get(i) != b.get(i);
    let mut out = String::new();
    out.push_str(&format!("--- {}\n+++ {}\n", old_name, new_name));
    let mut i = 0;
    while i < n {
        if !changed(i) {
            i += 1;
            continue;
        }
        let start = i.saturating_sub(3);
        let end = (i + 1 + 3).min(n - 1);
        let len = end - start + 1;
        out.push_str(&format!("@@ -{},{} +{},{} @@\n", start + 1, len, start + 1, len));
        for j in start..=end {
            if !changed(j) {
                out.push_str(&format!(" {}\n", a[j]));
            } else {
                if let Some(x) = a.get(j) {
                    out.push_str(&format!("-{}\n", x));
                }
                if let Some(y) = b.get(j) {
                    out.push_str(&format!("+{}\n", y));
                }
            }
        }
        i += 2;
    }
    out
}

fn split_lines(s: &str) -> Vec<&str> {
    let mut v: Vec<&str> = s.split('\n').collect();
    if s.ends_with('\n') {
        v.pop();
    }
    v
}
