const GLOBAL_KEYS: &[&str] = &[
    "enable", "disable", "exclude", "include", "respect-gitignore", "line-length", "flavor", "output-format", "fixable", "unfixable", "cache",
    "cache-dir", "force-exclude",
];

impl Config {
    fn validate(&mut self, content: &str, file_name: &str, pyproject: bool) {
        let root: toml::Table = match content.parse::<toml::Table>() {
            Ok(r) => r,
            Err(_) => return,
        };
        let root = if pyproject {
            match root.get("tool").and_then(|t| t.get("rumdl")) {
                Some(Value::Table(t)) => t.clone(),
                _ => return,
            }
        } else {
            root
        };
        let rules = crate::rules::all_rules();
        let mut rule_warn: Vec<(String, String)> = Vec::new();
        let mut global_warn: Vec<String> = Vec::new();
        let mut unknown_rules: Vec<String> = Vec::new();
        for (k, v) in &root {
            let nk = norm_key(k);
            match (nk.as_str(), v) {
                ("global", Value::Table(t)) => {
                    for gk in t.keys() {
                        if !GLOBAL_KEYS.contains(&norm_key(gk).as_str()) {
                            global_warn.push(format!("Unknown global option in {}: {}", file_name, gk));
                        }
                    }
                }
                ("per-file-ignores", _) | ("per-file-flavor", _) | ("code-block-tools", _) => {}
                (_, Value::Table(t)) => match crate::rules::resolve_rule_name(k) {
                    Some(rn) => {
                        let r = rules.iter().find(|r| r.name() == rn).unwrap();
                        let defs = r.default_config();
                        let mut keys: Vec<&String> = t.keys().collect();
                        keys.sort();
                        for rk in keys {
                            let nrk = norm_key(rk);
                            if nrk == "severity" {
                                continue;
                            }
                            if nrk == "enabled" && r.opt_in() {
                                continue;
                            }
                            match defs.iter().find(|d| d.0 == nrk) {
                                Some(d) => {
                                    let uv = &t[rk];
                                    let (a, b) = (type_name(&d.1), type_name(uv));
                                    if a != b && !(a == "integer" && b == "array" && rn == "MD022") {
                                        rule_warn.push((rn.to_string(), format!("Type mismatch for {}.{}: expected {}, got {}", rn, nrk, a, b)));
                                    }
                                }
                                None => {
                                    if r.default_config().is_empty() && (nrk == "enabled") {
                                        rule_warn.push((rn.to_string(), format!("Unknown option for rule {}: {}", rn, rk)));
                                    } else {
                                        rule_warn.push((rn.to_string(), format!("Unknown option for rule {}: {}", rn, rk)));
                                    }
                                }
                            }
                        }
                    }
                    None => {
                        let s = crate::commands::suggest_rule(k);
                        match s {
                            Some(s) => unknown_rules.push(format!("Unknown rule in {}: {} (did you mean: {}?)", file_name, k, s)),
                            None => unknown_rules.push(format!("Unknown rule in {}: {}", file_name, k)),
                        }
                    }
                },
                _ => {
                    if pyproject && !GLOBAL_KEYS.contains(&nk.as_str()) {
                        global_warn.push(format!("Unknown global option in {}: {}", file_name, k));
                    }
                }
            }
        }
        rule_warn.sort_by(|a, b| a.0.cmp(&b.0));
        for (_, w) in rule_warn {
            self.warnings.push(w);
        }
        self.warnings.extend(global_warn);
        self.warnings.extend(unknown_rules);
    }
}'''
