/// Warning from absolute byte offsets with byte-based columns (rumdl quirk for some rules)
pub fn warn_abs_b(rule: &'static str, ctx: &Ctx, start: usize, end: usize, msg: impl Into<String>, fix: Option<Fix>) -> Warning {
    let l1 = ctx.line_of_offset(start);
    let l2 = ctx.line_of_offset(end.max(start));
    let c1 = start - ctx.lines[l1].start + 1;
    let c2 = end.saturating_sub(ctx.lines[l2].start) + 1;
    Warning::new(rule, l1 + 1, c1, l2 + 1, c2, msg).with_fix(fix)
}

/// Warning on a line with byte-based columns
pub fn warn_b(rule: &'static str, line: usize, start_byte: usize, end_byte: usize, msg: impl Into<String>, fix: Option<Fix>) -> Warning {
    Warning::new(rule, line + 1, start_byte + 1, line + 1, end_byte + 1, msg).with_fix(fix)
}
