#!/usr/bin/env python3
import sys, subprocess, os
from concurrent.futures import ThreadPoolExecutor
O='/workspace/executable'; M='/workspace/target/release/rumdl'
cfg = sys.argv[1]; files = sys.argv[2:]
def run(b, f):
    try:
        p = subprocess.run([b,'fmt','--no-cache','--stdin','--config',cfg], input=open(f).read(), capture_output=True, text=True, timeout=30)
        return p.stdout
    except Exception:
        return 'ERR'
bad=0
with ThreadPoolExecutor(8) as ex:
    for f,o,m in ex.map(lambda f: (f, run(O,f), run(M,f)), files):
        if o != m:
            bad += 1
            import difflib
            d=list(difflib.unified_diff(o.split('\n'), m.split('\n'), lineterm='', n=0))
            print('=== FMT DIFF', os.path.basename(f), len(d))
            if os.environ.get('V'): print('\n'.join(d[:20]))
print(f'{len(files)-bad}/{len(files)} match')
EOF
